// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст мученику Вонифатію Тарсійському","e":"Akathist to the Martyr Boniface of Tarsus","secs":[{"h":"Кондак 1","ps":["Ізбра́нний во́їне Христо́в, вінце́м сла́ви украше́нний, му́ченичеською сме́ртію ві́чния сме́рти ізба́вивийся, от мра́ка гріхо́внаго отврати́вийся і к ві́чному сві́ту прише́дий, прийми́ моле́ніє на́ше, в похвалу́ тебі́ приноси́моє, і нас ізба́ви от сіте́й лука́ваго врага́ на́шего, да тебі́ с ра́достію побі́дною зове́м:","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Ікос 1","ps":["А́нгелом сві́тлим, огнь муче́ній твої́х росо́ю благода́ті угаси́вшим, огражде́н бил єси́, страда́льче Христо́во Вонифа́тіє, да не когда́ я́ко грі́шник нераска́янний поги́бнеши, і пред Го́сподем в оде́жді бра́чней предста́неши. Научи́ і нас облещи́ся в сві́тлия ри́зи свя́тости, тебі́ зову́щих:","Ра́дуйся, жизнь за Христа́ отда́вий;","ра́дуйся, страда́нієм Єго́ подража́вий.","Ра́дуйся, о́чі своя́ к Бо́гу обрати́вий;","ра́дуйся, во́лю свою́ в доброді́теліх укріпи́вий.","Ра́дуйся, ра́бе Христо́во ві́рний;","ра́дуйся, святи́й коне́ць житія́ своєго́ приє́мий.","Ра́дуйся, к покая́нію сердца́ обраща́яй;","ра́дуйся, ко Христу́, Путі́ і́стинному, приводя́й.","Ра́дуйся, Ду́хом Святи́м просвіще́нний;","ра́дуйся, собла́знами ми́ра сего́ не прельще́нний.","Ра́дуйся, змі́я лука́ваго посрами́вий;","ра́дуйся, святи́х лик возвесели́вий.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 2","ps":["Ви́дя многом'яте́жіє ми́ра сего́ і печа́лі земни́я, і сія́ вся, я́ко прах вміни́в, к преми́рним возве́л єси́ ум твой, страда́льче Христо́в. На висоту́ богоразу́мія возше́д, Христа́ Бо́га пред всі́ми іспові́дал єси́. І ни́ні ду́ші всіх во грісі́х погиба́ющих к милосе́рдому Го́споду зове́ши, да во смире́нії пока́ються і во слеза́х умиле́нно Єму́ вопію́ть: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум трезве́нієм укріпи́л єси́ і страсте́й пла́мень покая́нієм угаси́л єси́, Вонифа́тіє преди́вний. От За́пада на Восто́к із Ри́ма прише́л єси́, спострада́ти Го́споду Ісу́су Христу́ намі́реніє свято́є нося́, да благода́ть в тебі́ преізоби́луєть. І нас ни́ні в храм Бо́жий привле́кл єси́, тебі́ глаго́лющих:","Ра́дуйся, стра́сті побора́ти науча́яй;","ра́дуйся, отча́янним наде́жду спасе́нія подава́яй.","Ра́дуйся, суєту́ жи́зні земни́я позна́вий;","ра́дуйся страда́нія своя́ предсказа́вий.","Ра́дуйся, трезвя́щихся отра́до і ободре́ніє;","ра́дуйся, немощни́х во́лею укріпле́ніє.","Ра́дуйся, я́ко тобо́ю от пія́нства отвраща́ємся;","ра́дуйся, я́ко тобо́ю к Бо́гу обраща́ємся.","Ра́дуйся, ісціле́ній істо́чниче неісчерпа́ємий;","ра́дуйся, чуде́с сокро́вище неоскудіва́ємоє.","Ра́дуйся, науча́яй нас при́сно возноси́ти ум наш к Бо́гу;","ра́дуйся, обріти́й і́стинную от гріхо́в свобо́ду.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 3","ps":["Си́ла милосе́рдія Бо́жия неізрече́нная на тебі́ откри́ся, і́бо житія́ твоєго́, му́чениче, ди́вноє повіствова́ніє я́вно нам сказу́єть, ка́ко ве́лії грі́шници ми́лостиво Отце́м на́шим Бо́гом приє́млються, єгда́ Єму́ покая́ніє принесу́ть. Та́ко і ти Бо́гу угоди́л єси́, і вмі́сто го́ркия сме́рті ві́чную жизнь прия́л єси́. Научи́ і нас Бо́гу пі́ти всегда́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ни́ні ра́дость ві́чную в небе́сних селе́ніях, і нас грі́шних на землі́ не забива́єши, му́чениче Христо́во Вонифа́тіє. Ми же, тружда́ющіїся і обремене́ннії, к тебі́ прибіга́єм: не оста́ви нас си́рих і неду́жних, по́мощі у тебе́ прося́щих, но мольби́ на́ша на олта́р небе́сний принеси́, да ра́достно тебі́ зове́м:","Ра́дуйся, бли́жняго, я́ко себе́ сама́го, возлюби́вий;","ра́дуйся, во грісі́х се́рдце своє́ не ожесточи́вий.","Ра́дуйся, стра́нником і пу́тником со вся́ким тща́нієм служи́вий;","ра́дуйся, я́ко сего́ ра́ди но́щію сто́гни гра́да обходи́вий.","Ра́дуйся, бога́тия милосе́рдію науча́яй;","ра́дуйся, си́рия і вдови́ці защища́яй.","Ра́дуйся, бе́дствующим до́брий предста́телю;","ра́дуйся, за оби́димих і уничижа́ємих при́сний хода́таю.","Ра́дуйся, нестерпи́мою жа́ждою пія́нства пали́мия трезве́нієм прохлажда́яй;","ра́дуйся, вина́ ра́ди обнища́вшия к трезве́нію призива́яй.","Ра́дуйся, же́ни рида́ющия утіша́яй;","ра́дуйся, сле́зи їх ко Го́споду принося́й.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 4","ps":["Бу́ри гріхо́вния тебі́ не потопи́ша, ніже́ во́лни страсте́й покри́ша, му́чениче Христо́в: не поги́бл єси́, но ко Христу́ прише́л єси́ і жизнь свою́, я́ко же́ртву благово́нную, Єму́, Сладча́йшему Спаси́телю на́шему, прине́сл єси́. Моли́ся у́бо, да і ми, в жите́йськом мо́рі су́щії, к ти́хому приста́нищу, Го́споду Спаси́телю, притеце́м, во умиле́нії зову́ще: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шим і ми єва́нгельськую при́тчу, ка́ко блу́дний син на страні́ дале́че імі́ніє своє́ іжди́вий, от гла́да душе́внаго в себі́ прише́д, во об'я́тія о́тчі притече́, в покая́нії зови́й: «О́тче, согріши́х на не́бо і пред тобо́ю»; та́ко і ти, му́чениче Вонифа́тіє, не погуби́в себі́, но от роже́ць гріха́ отврати́вся, ко Христу́ обрати́лся єси́. Ми же, ісправле́нію твоєму́ ра́дующеся, поє́м ті си́це:","Ра́дуйся, глад крі́пок в рабо́ті страсте́м іспита́вий;","ра́дуйся, Христа́ Бо́га, я́ко Хлі́ба жива́го, взалка́вий.","Ра́дуйся, пречи́стия Кро́ві Єго́, я́ко і́стиннаго питія́ приобщи́вийся;","ра́дуйся, я́ко пресла́вним му́чеником приложи́вийся.","Ра́дуйся, на крилеіх трезві́нія к Бо́гу возлеті́вий;","ра́дуйся, се́рдце своє́ го́ре імі́вий.","Ра́дуйся, ко Го́споду си́лою Животворя́щаго Креста́ прише́дий;","ра́дуйся, я́ко прия́л єси́ віне́ць побі́ди.","Ра́дуйся, душі́ на́шея сокро́вище нетлі́нноє;","ра́дуйся, Це́ркве на́шея украше́ніє многоці́нноє.","Ра́дуйся, красоти́ ми́ра сего́ отве́ргий;","ра́дуйся, гріхо́вную оде́жду с себі́ совлеки́й.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 5","ps":["Богото́чную Кров Христо́ву за всіх нас, недосто́йних, і кров му́ченичеськую за Христа́ пролія́нную па́м'ятующи, си́це тебі́ віща́ше Аглаї́да: «Сам ві́си, сколь мно́гими гріхми́ оскверне́ні єсьми́, і о бу́дущем житія́ на́шего небреже́м. Аз же от боже́ственнаго му́жа сли́шах, я́ко му́чеников мо́щі спасе́ніє да́рують, і́же му́ченика я́ко храни́теля і хода́тая пред Бо́гом і́мать». — І ми тебі́ глаго́лем: «Ти єси́ наш храни́тель і хода́тай пред Го́сподем на́шим», і́бо со а́нгели предстої́ши Пресвяті́й Тро́йце, поя́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дим ни́ні і разумі́єм, ка́ко сії́ глаго́ли Аглаї́ди ду́шу твою́ пробуди́ша, і ти к воздержа́нію призва́л єси́ себе́, му́чениче Вонифа́тіє. І нам помози́ подража́ти тебі́, да не поги́бнем в пучи́ні беззако́нія потопля́ємі, но ра́достно тебі́ зове́м:","Ра́дуйся, от страсте́й, я́ко от поги́бельнаго сна, пробуди́вийся;","ра́дуйся, от уз гріхо́вних свободи́вийся.","Ра́дуйся, сомнева́ющихся в милосе́рдії Бо́жиєм обличе́ніє;","ра́дуйся, безконе́чния ра́досте утвержде́ніє.","Ра́дуйся, зови́й нас к по́двигу воздержа́нія;","ра́дуйся, ти бо зна́менієм Креста́ посі́кл єси́ страсте́й взигра́нія.","Ра́дуйся, стяжа́вий себі́ ві́чноє імі́ніє;","ра́дуйся, і нас пробужда́яй к труду́ спасе́нія.","Ра́дуйся, я́ко ви́нноє весе́ліє презрі́л єси́;","ра́дуйся, я́ко плотські́я ра́ни, я́ко безпло́тен, претерпі́л єси́.","Ра́дуйся, за іспові́даніє Христа́ от враго́в ізбіє́нний;","ра́дуйся, нестерпи́мим огне́м за Него́ опале́нний.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 6","ps":["Пропові́дниця поклоне́нія святи́м моще́м яви́ся Аглаї́да, госпожа́ твоя́, страда́льче Христо́в, єгда́ посла́ тя на Восто́к святи́я мо́щі му́чеников, за ві́ру Христо́ву пострада́вших, принести́, і́миже благодія́нія істоча́ються оби́льно, і ві́чноє спасе́ніє подає́ться всім, к му́ченичеському ли́ку усе́рдно притека́ющим. Даждь і нам утіше́ніє от Го́спода прия́ти, Єму́же а́нгельськую піснь прино́сим: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ нам, я́ко звізда́ незаходи́мая, ди́вним житіє́м твої́м, му́чениче преблаже́нне, і́го Христо́во ле́гкоє і вседраго́є на себі́ приє́мий і спасе́ніє получи́вий, путі́ бо благоче́стія без Христа́ Го́спода обрісти́ ніка́коже возмо́жно єсть. Ті́мже і нас моли́твами твої́ми в го́рняя оби́телі приведи́, тя восхваля́ющих си́це:","Ра́дуйся, зако́на Христо́ва скрижа́ль богоначерта́нная;","ра́дуйся, моли́тв ко Го́споду ми́ро благоуха́нноє.","Ра́дуйся, пра́вия ві́ри Христо́вой сто́лпе о́гненний;","ра́дуйся, честни́й ві́нче от за́повідей Бо́жиїх, я́коже от ка́меній драги́х, устро́єнний.","Ра́дуйся, трезві́нія лі́ствице небовосхо́дная;","ра́дуйся, болі́зні і ра́ни врачу́яй гріхо́вния.","Ра́дуйся, я́ко от Го́спода Ісу́са Христа́ благода́ть і си́лу прия́л єси́;","ра́дуйся, я́ко світ Христо́в нам возсія́л єси́.","Ра́дуйся, воздержа́нієм от гріхо́в освяща́ти пра́здники нас науча́яй;","ра́дуйся, от сме́ртнаго вина́ нас охраня́яй.","Ра́дуйся, умерщвле́нния страстьми́ сві́том Христо́вим оживля́яй;","ра́дуйся, ти́я к но́вому житію́ призива́яй.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 7","ps":["Хотя́ отити́ от до́му своєго́ в путь на Восто́к, кончи́ну житія́ твоєго́ предре́кл єси́, достохва́льне, Аглаї́де глаго́ля: «Госпоже́ моя́, прийми́ моє́ ті́ло, за Христа́ му́чимоє, єгда́ єго́ принесу́ть ті»; в душі́ твоє́й мисль за Христа́ пострада́ти тая́, Єму́ сокрове́нно моли́лся єси́. І на́шу ві́ру укріпи́, да бу́дем гото́ви і ми єя́ ра́ди страда́ти, Го́споду пою́ще: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вному і пресла́вному ісправле́нію твоєму́ не ві́руя, поми́сли лука́воє в се́рдці своє́м Аглаї́да, гріхо́м бо хуле́нія оболга́ти тя хотя́щи, та́ко отвіща́ ті: «Ни́ні не глумле́нія вре́м'я, бра́те, но благогові́нія; ві́дий бу́ди, я́ко мо́щі святи́я і́маши носи́ти. Госпо́дь же да по́слеть а́нгела Своєго́ пред тобо́ю і напра́вить стопи́ твоя́ милосе́рдієм Свої́м». Ми же чистоту́ се́рдця твоєго́, ди́вний Вонифа́тіє, зря́ще, вопіє́м ті:","Ра́дуйся, святи́х моще́й почита́телю;","ра́дуйся, благогові́нія о́браза нам пода́телю.","Ра́дуйся, безчи́нств храни́тися нам повелі́вий;","ра́дуйся, вся, о ни́хже си́нове ві́ка сего́ ра́дуються, презрі́вий.","Ра́дуйся, ізві́стний наш помо́щниче;","ра́дуйся, благи́х наме́реній таї́нниче.","Ра́дуйся, всім борю́щимся со гріхми́ покрови́телю;","ра́дуйся, покая́нія на́шего пред Бо́гом поручи́телю.","Ра́дуйся, я́ко твої́ми моли́твами Госпо́дь оставля́єть прегріше́нія;","ра́дуйся, помога́яй нам терпі́ти ско́рби і поноше́нія.","Ра́дуйся, лико́м а́нгельським сотвори́вий ра́дость і удивле́ніє;","ра́дуйся, духо́в зло́би приведи́й в посрамле́ніє.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 8","ps":["Стра́нно тебі́ бисть язи́чеськоє і́долом служе́ніє, і ти, святи́й му́чениче, в Тарс прише́д, не преклони́л єси́ колі́н пред бога́ми чужди́ми, но апо́столом показа́лся єси́ ревни́тель. Ті́мже моли́ся за ни, да возгорі́мся і ми огне́м любве́ ко Влади́ці Христу́, пою́ще всегда́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь распали́лся єси́ ре́вностію свято́ю, хуле́нія на Го́спода не терп'я́, і іспо́лнился єси́ Ду́ха Бо́жия, осліпле́ніє і безу́міє покланя́ющихся ло́жним бого́м облича́я. Сего́ ра́ди цар нечести́вий казнь наведе́ на тя, му́чениче, го́ркую, бичми́ нестерпи́мо бія́ і ра́ни нанося́ неісці́льния. Ми же тебі́ похвалу́ поє́м:","Ра́дуйся, злові́рія обличи́телю дерзнове́нний;","ра́дуйся, в пра́вду Бо́жию, а́ки в броню́ облече́нний.","Ра́дуйся, я́ко ко́сті твоя́ от ран за Христа́ обнажа́хуся;","ра́дуйся, я́ко чистота́ душі́ твоєя́ тогда́ откри́шася.","Ра́дуйся, я́ко наслі́довал єси́ небе́сная селе́нія;","ра́дуйся, я́ко і ни́ні облича́єши злих челові́к на Христа́ хуле́нія.","Ра́дуйся, за Христа́ о́стрими тростьми́ пробода́ємий;","ра́дуйся, са́да ра́йськаго цві́те неув'яда́ємий.","Ра́дуйся, я́ко зла́то горни́лом язв очище́нний;","ра́дуйся, за Христа́ ударе́нний.","Ра́дуйся, кончи́ною своє́ю Бо́гу угоди́вий;","ра́дуйся, да́же до сме́рти му́ченичеськия Єго́ возлюби́вий.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 9","ps":["Всего́ себе́ Го́споду Бо́гу преда́в, страстоте́рпче Христо́в, єгда́ нечести́вий цар повелі́ раскри́ти уста́ твоя́ і о́лово кип'я́щеє вли́ти, ру́ці свої́ воздви́гл єси́ к не́бу, та́ко моля́ся: «Го́споди, Бо́же мой, Ісу́се Христе́, укріпи́вий мене́ в му́ках, пребу́ди і ни́ні со мно́ю, моя́ страда́нія облегчи́ і не оста́ви мене́ одоле́ну би́ти лука́вим кня́зем». Тім і нас любві́ ко Христу́ науча́єши, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї суєму́дреннії да реку́ть нам, ка́ко о́лово разжже́нноє горта́ні твоєя́ не опали́, ніже́ іна́го вреда́ тебі́ сотвори́, му́чениче Вонифа́тіє. От Го́спода бо зна́меніє побі́ди над мучи́телем проси́л єси́, і сіє́ зна́меніє тебі́ дано́ бисть. Сего́ ра́ди всі чудя́щеся восклиця́ху: «Ве́лій єсть Ісу́с Христо́с, ві́руєм в Тя, Го́споди». Ми же сла́вим тя, му́чениче, си́це:","Ра́дуйся, я́ко тобо́ю ві́рнії просвіща́ються;","ра́дуйся, я́ко тобо́ю от пости́дния сме́рті ізбавля́ються.","Ра́дуйся, во єди́нім Христе́ утіше́ніє полага́яй;","ра́дуйся, во страда́ніях призива́ти Бо́га науча́яй.","Ра́дуйся, я́ко мучи́теліє тебі́ не превозмого́ша;","ра́дуйся, я́ко стра́сті тебі́ не поборо́ша.","Ра́дуйся, ти бо те́рнія гріхо́во в себі́ попали́л єси́;","ра́дуйся, ти бо огне́м неопале́н преби́л єси́.","Ра́дуйся, при́сно живи́й страстоте́рпче ра́достний;","ра́дуйся, моли́твенниче наш бла́гостний.","Ра́дуйся, я́ко тобо́ю очеса́, гріхми́ осліпле́нния, отверза́ються;","ра́дуйся, я́ко по́мощію твоє́ю печа́лі на ра́дость прелага́ються.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 10","ps":["Спасе́н би́ти восхоті́в, пла́менні возжелі́л єси́ до конця́ за Го́спода пострада́ти, му́чениче Вонифа́тіє, Єму́же і возопи́л єси́: «Го́споди, Го́споди, Бо́же мой, сподо́би м'я ми́лостей Твої́х і бу́ди мі помо́щник, да за беззако́нія моя́, безу́мно соді́янния, враг не прегради́ть мі путі́ к небесі́; прийми́ с ми́ром ду́шу мою́, вчини́ м'я с му́чениками, кров за Тя пролія́вшими і ві́ру до конця́ соблю́дшими», і ни́ні вопію́щими Ті: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ крі́пкая, ко́зньми врага́ неодоле́нная, преби́л єси́ до конця́, му́чениче Христо́в. Єгда́ же глава́ твоя́ от тілесе́ отсіче́на бисть, о чудесе́! А́біє кров і млеко́ із ра́ни твоєя́ істеко́ша, я́ко і неві́рним, чу́до сіє́ зря́щим, Христа́ просла́вити і с на́ми зва́ти тебі́:","Ра́дуйся, я́ко муче́нія твоя́ зря́ще, мно́жество люде́й ко Христу́ обрати́шася;","ра́дуйся, я́ко тебе́ ра́ди на кня́зя зло́би они́ устреми́шася.","Ра́дуйся, твоя́ бо кончи́на просвіти́ уми́ помраче́нния;","ра́дуйся, твоя́ бо сла́вная смерть воскреси́ со́вісти во грісі́х погребе́нния.","Ра́дуйся, нераска́янних грі́шников обличе́ніє;","ра́дуйся, во́лею разсла́бленних от вина́ ісціле́ніє.","Ра́дуйся, в нощі́ неві́дінія блужда́ющих вразумле́ніє;","ра́дуйся, злата́я у́диці, із глубини́ гріхо́во влеку́щая ко спасе́нію.","Ра́дуйся, я́ко от Бо́га в моли́твах усли́шан бил єси́;","ра́дуйся, я́ко в небе́снім Ца́рствіє всели́лся єси́.","Ра́дуйся, порфи́рою от крове́й твої́х облече́нний;","ра́дуйся, я́ко зри́ши ни́ні світ неізрече́нний.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 11","ps":["Пі́ніє немо́лчноє прино́сиши Го́сподеві, му́чениче Вонифа́тіє, с му́ченичеськими ли́ки Пресвяті́й Тро́йце предстоя́, за Ню́же себі́ преда́л єси́, да і ми, ду́ші своя́, а́ки неві́сти, украси́вше, нетлі́нному Жениху́ Христу́, предста́вим со свяще́нною пі́снію: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ любве́ і по сме́рті возсія́л єси́, Вонифа́тіє ди́вний, єгда́ бо дру́зі твою́ усіче́нную главу́ обрі́тше, пла́кахуся го́рко, глаго́люще: «Ра́бе Христо́в, забу́ди нам гріх непра́веднаго осужде́нія і безразсу́дних руга́ній на́ших». Тогда́ лик твой, я́ко луча́ми живи́ми просвіти́ся, проще́ніє їм явля́я. Сего́ ра́ди с любо́вію тебі́ зове́м:","Ра́дуйся, імі́яй уста́ кро́тости сладковеща́нния;","ра́дуйся, любве́ вмісти́лище простра́нноє.","Ра́дуйся, о тебі́ бо весели́ться Це́рков со свої́ми ча́ди;","ра́дуйся, ти бо преше́л єси́ к ви́шнему небе́сному гра́ду.","Ра́дуйся, в сме́рті своє́й апо́столом ра́вний;","ра́дуйся, ре́вностію по Бо́зі пресла́вний.","Ра́дуйся, жите́йськія молви́ облича́яй зли́я сплете́нія;","ра́дуйся, всіх нас от вра́жия ізбавля́яй ловле́нія.","Ра́дуйся, ти бо защища́єши непра́ведно гони́мия;","ра́дуйся, пред престо́лом Госпо́днім лампа́до неугаси́мая.","Ра́дуйся, по за́повіді Христо́вой і враго́во возлюби́вий;","ра́дуйся, злосло́вія і клевети́ нівочто́же вміни́вий.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 12","ps":["Благода́ть ісціле́ній точа́щия мо́щі твоя́, єгда́ к Ри́му приближа́хуся, А́нгел Госпо́день яви́ся Аглаї́де, глаго́ля: «Би́вшаго ті дре́вле раба́, ни́ні же на́шего бра́та і сослуже́бника прийми́, я́коже влади́ку, і упоко́й до́брі, да гріси́ твоя́ оста́в'яться», той бо с на́ми ни́ні в небесі́х поє́ть Всеви́шнему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ твоя́, храм ди́вний созда́ тебі́, во́їне Христо́в, Аглаї́да, в не́мже і мо́щі твоя́ положи́, і сама́, бога́тство ни́щим разда́вши і п'ятьна́десят літ в по́двизіх поста́ і покая́нія пожи́вши, ли́ка святи́х дости́же. Ті́мже, велича́юще чудеса́ твоя́, прославля́єм тя си́це:","Ра́дуйся, ду́шу свою́ сотвори́вий, храм Бо́гу прекра́сний;","ра́дуйся, чу́дних Бо́жиїх діл кни́го я́сная.","Ра́дуйся, от внеза́пния сме́рті ізбавля́яй;","ра́дуйся, ско́рбния же́ни от злих пія́ниць огражда́яй.","Ра́дуйся, па́дшия к возста́нію от гріхо́в призива́яй;","ра́дуйся, світ чистоти́ їм подава́яй.","Ра́дуйся, ти бо укроща́єши страсте́й огне́вицю;","ра́дуйся, тобо́ю бо оставля́єм гріхо́вную темни́цю.","Ра́дуйся, ма́лия ча́да от собла́знов ми́ра соблюда́яй;","ра́дуйся, ти́я Христо́ву уче́нію наставля́яй.","Ра́дуйся, ве́стниче тре́звости, во ві́ки прославля́ємий;","ра́дуйся, уго́дниче Христо́в, при́сно почита́ємий.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 13","ps":["О, пресла́вний му́чениче Христо́во Вонифа́тіє! Прийми́ от нас сіє́ ма́лоє похва́льноє приноше́ніє, є́же пред іко́ною твоє́ю колі́на прекло́ньше, і ру́ці свої́ к тебі́ просте́рши, тебі́ ни́ні прино́сим; і да́руй нам твоє́ пред Го́сподем заступле́ніє, найпа́че же погиба́ющим от пія́нства бра́тіям на́шим ісціле́ніє ниспосли́ і житія́ блага́го нача́ло положи́ти всіх нас сподо́би, да спасе́ніє улучи́вше моли́твами твої́ми, во ві́ки восхва́лим Бо́га, пою́ще Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом сві́тлим, огнь муче́ній твої́х росо́ю благода́ті угаси́вшим, огражде́н бил єси́, страда́льче Христо́во Вонифа́тіє, да не когда́ я́ко грі́шник нераска́янний поги́бнеши, і пред Го́сподем в оде́жді бра́чней предста́неши. Научи́ і нас облещи́ся в сві́тлия ри́зи свя́тости, тебі́ зову́щих:","Ра́дуйся, жизнь за Христа́ отда́вий;","ра́дуйся, страда́нієм Єго́ подража́вий.","Ра́дуйся, о́чі своя́ к Бо́гу обрати́вий;","ра́дуйся, во́лю свою́ в доброді́теліх укріпи́вий.","Ра́дуйся, ра́бе Христо́во ві́рний;","ра́дуйся, святи́й коне́ць житія́ своєго́ приє́мий.","Ра́дуйся, к покая́нію сердца́ обраща́яй;","ра́дуйся, ко Христу́, Путі́ і́стинному, приводя́й.","Ра́дуйся, Ду́хом Святи́м просвіще́нний;","ра́дуйся, собла́знами ми́ра сего́ не прельще́нний.","Ра́дуйся, змі́я лука́ваго посрами́вий;","ра́дуйся, святи́х лик возвесели́вий.","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Кондак 1","ps":["Ізбра́нний во́їне Христо́в, вінце́м сла́ви украше́нний, му́ченичеською сме́ртію ві́чния сме́рти ізба́вивийся, от мра́ка гріхо́внаго отврати́вийся і к ві́чному сві́ту прише́дий, прийми́ моле́ніє на́ше, в похвалу́ тебі́ приноси́моє, і нас ізба́ви от сіте́й лука́ваго врага́ на́шего, да тебі́ с ра́достію побі́дною зове́м:","Ра́дуйся, Вонифа́тіє, му́чениче многострада́льний."]},{"h":"Молитва перша","ps":["О, многострада́льний і всехва́льний му́чениче Вонифа́тіє! Ко твоєму́ заступле́нію ни́ні прибіга́єм, моле́ній нас, пою́щих тебі́, не отве́ржи, но ми́лостиво усли́ши нас. Виждь бра́тія і се́стри на́ша, тя́жким неду́гом пія́нства одержи́мия, виждь того́ ра́ди от ма́тері своєя́ Це́ркві Христо́вой і ві́чнаго спасе́нія отпа́дающия. О, святи́й му́чениче Христо́во Вонифа́тіє, косни́ся серде́ць їх да́нною ті от Бо́га благода́тію, ско́ро возста́ви от паде́ній гріхо́вних і ко спаси́тельному воздержа́нію приведи́ їх. Умоли́ Го́спода Бо́га, Єго́же ра́ди страда́л єси́, да, прости́в нам согріше́нія на́ша, не отврати́ть ми́лости Своєя́ от сино́в Свої́х, но да укріпи́ть нас в трезве́нії і цілому́дрії, да помо́жеть Своє́ю десни́цею трезвя́щимся спаси́тельний обі́т свой до конця́ сохрани́ти, во дні і в нощі́ о нем бо́дрствующе, і до́брий отві́т о нем возда́ти на стра́шнім Суди́щі.","Прийми́, уго́дниче Бо́жий, моли́тви ма́терей, о ча́діх свої́х сле́зи пролива́ющих; жен честни́х, о мужеіх свої́х рида́ющих; чад си́рих і убо́гих, от пія́ниць оста́вленних; і всіх нас, і да при́йдеть сей вопль наш моли́твами твої́ми ко престо́лу Всеви́шняго, дарова́ти всім, по моли́твам їх, здра́віє і спасе́ніє душ і тіле́с, найпа́че же Ца́рствіє Небе́сноє.","Покри́й і соблюди́ нас от лука́ваго ловле́нія і всіх ко́зней вра́жиїх, в стра́шний же час ісхо́да на́шего помози́ прейти́ непреткнове́нно возду́шния мита́рства, і моли́твами твої́ми ізба́ви ві́чнаго осужде́нія.","Умоли́ же Го́спода дарова́ти нам ко оте́честву на́шему любо́в нелицемі́рную і непоколеби́мую, пред врага́ми Це́ркві святи́я, ви́димими і неви́димими, да покри́єть нас ми́лость Бо́жия в несконча́ємия ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, всехва́льний му́чениче Вонифа́тіє! Ки́я пі́сні воспоє́м ті, ві́чною красото́ю украше́нному? Кий віне́ць сплете́м, сві́тлостію оде́янному? Кі́ї да́ри принесе́м ті, всі́ми бла́гами обогаще́нному? Вся у́бо с любо́вію приє́млеши: і слове́с кра́сная і сла́дкая пі́нія, і честни́я да́ри – свіщи́, єле́й і кади́ло благоуха́нноє. Но нічто́же та́ко ті уго́дно бива́єть, я́ко житіє́ непоро́чноє, нрав благи́й, душа́ чи́стая, се́рдце кро́ткоє, ті́ло чистото́ю освяще́нноє, любо́в к Бо́гу те́плая і ко бли́жнему нелицеме́рная, моли́тва ча́стая і прилі́жная, воздиха́нія умиле́нная, страсте́й умерщвле́ніє, оче́с целому́дріє, язи́ка воздержа́ніє, настоя́щих благ презрі́ніє і бу́дущих жела́ніє, о сме́рті поуче́ніє, воскресе́нія ча́яніє, ві́чних мук трепета́ніє, Ца́рства небе́снаго всера́достная наде́жда. Си́ми дарми́ нам ниспосли́, святи́й му́чениче, угоди́ти Го́сподеві во і́м'я твоє́ вседраго́є, да сподо́бимся от Всеще́драго Бо́га бога́тия ми́лости.","Твої́м предста́тельством і те́плим заступле́нієм от озлобле́нія ви́димих і неви́димих враг нас ізба́ви, да в настоя́щем ві́ці ми́рноє і безм'яте́жноє житіє́ поживе́м, в бу́дущем же всера́достнаго і безконе́чнаго Ца́рствія прича́стници бу́дем во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, святи́й уго́дниче Христо́в, страстоте́рпче і му́чениче Вонифа́тіє! Душе́ю на небесі́ предстоя́й престо́лу Бо́жию, і Трийпоста́сния Сла́ви Бо́жия наслажда́яйся, іко́ною свято́ю на землі́ в Боже́ственних хра́міх пребива́яй, і да́нною ті сви́ше благода́тію разли́чния істоча́яй чудеса́. При́зри ми́лостивим твої́м о́ком на предстоя́щия лю́ди і честні́й твоє́й іко́ні уми́льно моля́щіяся і прося́щия от тебе́ ціле́бния по́мощі і заступле́нія, і іспроси́ душа́м на́шим оставле́ніє согріше́ній. Се́рдцем сокруше́ним і ду́хом смире́нним, тебі́, хода́тая ми́лостива ко Влади́ці і моли́твенника за ни грі́шния призива́єм, я́ко прия́л єси́ от Него́ неду́ги отгоня́ти і стра́сті ісціля́ти. Тебе́ у́бо про́сим: не пре́зри нас недосто́йних, моля́щихся ті і твоєя́ по́мощі тре́бующих; бу́ди нам в печа́ліх уті́шитель, стра́ждущим от пія́нства врачь і ісціли́тель, во сла́ву Бо́жию трезвя́щимся ско́рий покрови́тель і гото́війший предста́тель; ісхода́тайствуй всім вся, я́же ко спасе́нію поле́зная, я́ко да твої́ми ко Го́споду Бо́гу моли́твами получи́вше благода́ть і ми́лость, просла́вим всіх благи́х Істо́чника і Дарода́теля Бо́га, Єди́наго в Тро́йці Святі́й сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["К сосло́вію по́слан му́чеников, / му́ченик бил єси́ і́стинен, / пострада́в за Христа́ кріпча́йше, всехва́льне, / мощми́ же возврати́лся єси́ ві́рою посла́вшей тя, / Вонифа́тіє блаже́нне, / моли́ Христа́ Бо́га // прия́ти нам гріхо́в проще́ніє."]},{"h":"Кондак, глас 4","ps":["Свяще́ніє непоро́чноє самово́льне Тебі́ приве́л єси́, / І́же от Ді́ви тебе́ ра́ди роди́тися Хотя́щему, // свя́те вінчено́сче, прему́дре Вонифа́тіє."]},{"h":"Інший кондак, глас 6","ps":["Звізда́ сві́тлая яви́лся єси́ непреле́стная ми́рові, Со́лнця Христа́ возвіща́ющи заря́ми твої́ми, страстоте́рпче Вонифа́тіє, і пре́лесть погаси́л єси́ всю, нам же пода́вши світ, моли́ся непреста́нно о всіх нас."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпче святи́й Вонифа́тіє, і чтем честна́я страда́нія твоя́, і́же за Христа́ претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст мученику Трифону Апамейському","e":"Akathist to the Martyr Tryphon of Apamea","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от Бо́га і к ли́ку святи́х сопричте́нний, святи́й му́чениче Три́фоне! Моли́ся о нас, грі́шних, Влади́ці Христу́ і помога́й нам побіжда́ти мир, плоть і дия́вола, многообра́зно вою́ющия на ни, я́коже побіди́л єси́ їх благода́тію і си́лою возлю́бленнаго тобо́ю Христа́, да, ізба́вльшеся от враго́в на́ших ви́димих і неви́димих, благода́рственно воззове́м ті:","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим!"]},{"h":"Ікос 1","ps":["О́бразу благоче́стія роди́телей твої́х подража́я, христия́нськия нра́ви от літ ма́лих прия́л єси́, святи́й му́чениче, і мал сий лі́ти, стар же ра́зумом, воі́стину христия́нин соверше́н яви́лся єси́. Ми же, воспомина́юще доброді́тельноє житіє́ твоє́, восхваля́єм тя си́це:","Ра́дуйся, добронра́вних роди́телей благочести́вий си́не;","ра́дуйся, вели́коє їх утіше́ніє.","Ра́дуйся, А́нгела твоєго́ Храни́теля непреста́нноє весе́ліє;","ра́дуйся, от ю́ности твоєя́ всего́ себе́ Бо́гу преда́вий.","Ра́дуйся, от ю́ности Христа́ возлюби́вий;","ра́дуйся, от ма́лих літ благода́ть Бо́жию оби́льно стяжа́вий.","Ра́дуйся, ду́шу свою́ непоро́чну яви́вий;","ра́дуйся, себі́ самаго́ в храм Ду́ха Свята́го угото́вавий.","Ра́дуйся, о́троком о́браз житія́ свята́го показа́вий;","ра́дуйся, благоче́стієм твої́м ві́рния возвеселя́яй.","Ра́дуйся, от ма́лих літ за вся сія́ Бо́гом возлю́бленний.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь, я́ко во́лею по стезі́ благоче́стія, в не́мже от роди́телей твої́х наста́влен бил єси́, тече́ши, і я́ко воі́стину лю́биши Бо́га, сотвори́ тя в жили́ще Свята́го Ду́ха от літ ма́лих і отве́рзе уста́ твоя́ пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Си́лу ві́ри твоєя́ показу́я, Влади́ка Христо́с дарова́ тебі́, святи́й му́чениче, єще́ о́троку би́вшу, дар чудотворе́ній, сего́ ра́ди вопіє́м ті:","Ра́дуйся, от ма́лих літ соверше́нную любо́в к Бо́гу показа́вий;","ра́дуйся, за́повідей Єго́ не то́кмо сли́шатель, но і ді́латель от младе́нчества би́вий.","Ра́дуйся, от ю́ности твоєя́ доброді́телі христия́нськия стяжа́вий;","ра́дуйся, от ма́лих літ житіє́м, ві́рою і любо́вію твоє́ю Бо́гу угоди́вий.","Ра́дуйся, дар ісціле́ній от Него́ прия́вий;","ра́дуйся, дар той на по́льзу бли́жнім іждива́ющий.","Ра́дуйся, многоразли́чния болі́зні ісціля́ющий;","ра́дуйся, в неду́зіх облегче́ніє да́рующий.","Ра́дуйся, страда́нія в ра́дость обраща́ющий;","ра́дуйся, ісціле́нія сія́ во сла́ву Бо́жию соверша́ющий.","Ра́дуйся, ті́ми і́стину ві́ри правосла́вния показу́ющий;","ра́дуйся, ті́ми нас к славосло́вію Бо́га возбужда́ющий.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 3","ps":["Ві́рою і любо́вію стяжа́л єси́ от Бо́га власть ізгоня́ти ду́хи нечи́стия, му́чащия челові́ки і претя́щия їм воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Ви́дя дарова́нную ті, святи́й му́чениче, си́лу Бо́жию, всп'ять біжа́ша де́мони, і́миже одержи́ми бя́ху біснова́тії лю́діє. Ви́дящії же сія́, воспіва́ху ті си́це:","Ра́дуйся, от Бо́га власть на нечи́стия ду́хи прия́вий;","ра́дуйся, си́лою Бо́жию сих ізгоня́ющий.","Ра́дуйся, врагу́ челові́чеському вреди́ти лю́дем возбраня́ющий;","ра́дуйся, ко́зні дия́вола і а́нгелов єго́ разруша́ющий.","Ра́дуйся, си́лу їх низлага́ющий;","ра́дуйся, безси́ліє їх явля́ющий.","Ра́дуйся, стра́хом і тре́петом їх поража́ющий;","ра́дуйся, ві́ри Христо́ви си́лу показу́ющий.","Ра́дуйся, ві́рних к прославле́нію Бо́га воздвига́ющий;","ра́дуйся, в біда́х і ско́рбіх су́щих прибіга́ти к предста́тельству святи́х наставля́ющий.","Ра́дуйся, в ну́ждах на́ших обраща́тися к Бо́гу науча́ющий;","ра́дуйся, помо́щниче наш, Бо́гом нам дарова́нний.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 4","ps":["Восхоті́в тобо́ю обрати́ти язи́ки от путі́ нече́стія і откри́ти їм путь і́стинний, веду́щий в Живо́т Ві́чний, сі єсть ві́ру і́стинную, ві́ру правосла́вную, да́же до Ри́ма із Компса́ди приведе́ тя Госпо́дь, да і в черто́гах ца́рських пропові́си Бо́га і та́мо мно́гія научи́ши пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Хотя́й обрати́ти мно́гія на путь спасе́нія, попусти́ Госпо́дь де́мону всели́тися в дщер царе́ву, і жесто́ко му́чити і вверга́ти ю многоча́стні во огнь і во́ду. Враче́ве нічто́же успева́ху і ничи́мже страда́нія дще́ри царе́вой утоли́ти возмого́ша. Єгда́ же і си́льнії ми́ра сего́ і вся́кую враче́бную хи́трость ві́дущії нічто́же возмого́ша і іспові́даху не́мощ свою́, тогда́ велі́нієм Бо́жиїм проглаго́ла дия́вол, я́ко єди́н єсть, і́же ізгна́ти єго́ і́мать, і се єсть Три́фон. Тогда́ прилі́жно іска́ху і обріто́ша єго́ в Компса́ді. Гряду́щу же єму́ і єще́ дале́че от Ри́ма су́щу, возопи́ гла́сом ве́ліїм дия́вол і ізи́де, і ісцілі́ діви́ця. Ви́дящії сія́ дивля́хуся і глаго́лаху:","Ра́дуйся, Три́фоне, єще́ дале́че су́щий в бі́гство дия́вола обрати́вий;","ра́дуйся, я́ко дия́вол безси́ліє пред тобо́ю іспові́да.","Ра́дуйся, моля́щимся тебі́ ско́рий помо́щниче;","ра́дуйся, неду́гов си́лою Бо́жию ціли́телю.","Ра́дуйся, оста́вленних врача́ми на свої́ ру́ці приє́млющий;","ра́дуйся, печа́лі на ра́дость пременя́ющий.","Ра́дуйся, печа́льним утіше́ніє і скорб'я́щим ра́дованіє посила́ющий.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 5","ps":["Ви́діша ві́рнії, і́же в Ри́мі, чу́до, прише́ствієм твої́м би́вшеє, укріпи́шася во ві́рі своє́й і воспі́ша Бо́гу, побіди́вшему а́дськаго змі́я і да́рующему ві́рующим в Него́ такову́ю си́лу: Аллилу́я."]},{"h":"Ікос 5","ps":["Увіре́нія іща́, тебі́ прише́дшу в Рим, святи́й Три́фоне, я́ко ти єси́ той, єго́же убоя́ся де́мон, моли́ тя імпера́тор Гордія́н, да яви́ши і єму́ і синкли́ту єго́, і лю́дем в чу́вственнем ви́ді дия́вола, і не отре́клся єси́, но, возложи́в на ся пост, помоли́ся Го́споду дній шесть. В день же седьми́й, прише́дшим царю́, синкли́ту і лю́дем, возопи́л єси́: «Тебі́ глаго́лю, душе́ нечи́стий, во і́м'я Го́спода моєго́ Ісу́са Христа́ яви́ся сі́мо і покажи́ свой де́монський о́браз зді су́щим, і безси́ліє своє́ іспові́ждь…». І бисть та́ко. І зря́ху всі безобра́зіє де́монськоє і дивля́хуся ві́рі свята́го, вопію́ще:","Ра́дуйся, Три́фоне, єго́же де́мони ослу́шатися не мо́гуть;","ра́дуйся, Три́фоне, по єго́же велі́нію ду́си нечи́стії в тіле́снім ви́ді явля́ються.","Ра́дуйся, Три́фоне, си́лою Бо́жиєю повелі́вий дия́волу іспові́дати, я́ко на христия́ни, і́же святу́ю правосла́вную і апо́стольськую ві́ру соде́ржать, вла́сті не і́мать;","ра́дуйся, Три́фоне, єму́же возві́щено бисть, я́ко де́мони власть і́муть му́чити то́кмо тіх, і́же свої́м по́хотем гріхо́вним сле́дують і ді́ла, уго́дная дия́волу, творя́ть.","Ра́дуйся, Три́фоне, я́ко научи́л єси́ нас бі́гати язи́чеськаго нече́стія;","ра́дуйся, Три́фоне, я́ко науча́єши всіх бі́гати вся́каго гріха́, в доброді́теліх же подвиза́тися.","Ра́дуйся, ві́ру правосла́вную тве́рдо содержа́ти наставля́яй нас;","ра́дуйся, хотя́щим благоче́стно жи́ти помога́яй.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 6","ps":["Ви́дівше, ка́ко мла́до отроча́ повеліва́єть вла́стно духово́м зло́би поднебе́сним, убоя́хуся мно́зі, і сли́шаще от де́мона і ви́дяще воо́чію, якову́ си́лу і́мать ві́ра Христо́ва, обрати́шася к Бо́гу; нече́стіє же і про́чая заблужде́нія своя́ отло́жше, крести́шася і усти́ свої́ми от се́рдця чи́ста благода́рственно воспі́ша Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Благодаря́ще тя, цар вложи́ в ру́ці твої́, му́чениче, да́ри і зла́то, ти же, Христа́ Бо́га приобріти́й, ні во что же вміни́л єси́ вся, я́же в ми́рі сем я́ко бла́га почита́ються, і прия́л єси́ да́ри царе́ви, да послужи́ши си́ми бли́жнім твої́м, і шед во оте́чество твоє́ Компса́ду, дал єси́ вся ни́щим, си́рим і всім в нужді́ су́щим, непреста́нно па́м'ятуя, я́ко расточи́в бога́тство земно́є, тлі́нноє, собере́ши себе́ на Небесі́ бога́тство нетлі́нноє, ві́чноє. Ми же, науча́ємії тобо́ю та́кожде твори́ти, вопіє́м ті си́це:","Ра́дуйся, Три́фоне, ду́шу свою́ чу́жду сребролю́бія показа́вий;","ра́дуйся, милосе́рдіє душі́ твоєя́ ви́ну явля́яй.","Ра́дуйся, ни́щих пита́тель би́вий; ра́дуйся, неіму́щим сострада́ніє показа́вий.","Ра́дуйся, за́повідь Христа́ «Прося́щему у тебе́ дай» іспо́лнивий;","ра́дуйся, і нас ісполня́ти за́повіді Бо́жії научи́вий.","Ра́дуйся, я́коже ше́ствієм в Рим і возвраще́нієм свої́м в Кампса́ду мно́гих уті́шивий, ободри́вий і возвесели́вий;","ра́дуйся, показа́вий нам о́браз, ка́ко бога́тством ги́бнущим на землі́ неги́блющеє бога́тство на Небесі́ собира́ти.","Ра́дуйся, бли́жнім служи́ти нас науча́ющий;","ра́дуйся, бли́жніх люби́ти нас наставля́ющий.","Ра́дуйся, о́браз житія́ пра́веднаго нам показу́ющий;","ра́дуйся, я́ко пра́вило ві́ри в Бо́га, наде́жди на Него́, любве́ к Нему́ і бли́жнім і про́чих христия́нських доброді́телей яви́ нам собо́ю.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 7","ps":["Взи́де на престо́л ри́мський нечести́вий цар Де́кий, і пролія́ся по вселе́нній кров христия́нськая. Прибли́жися вре́м'я, єгда́ і тебі́, святи́й му́чениче, суди́ Госпо́дь под'я́ти страда́нія, да кро́вію і му́ченичеством свої́м запечатле́єши ві́ру і вели́кую свою́ любо́в к Бо́гу і тім до конця́ низложи́ши сопроти́вния си́ли і наста́виши мно́гих, да гряду́ть на муче́нія, ра́дующеся, я́коже і ти, страстоте́рпче, і пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Я́ко укри́тися не мо́жеть град верху́ го́ри стоя́й, та́ко і тебі́, святи́й му́чениче, гоне́нію от Де́кия царя́ на христия́н би́вшу, невозмо́жно бисть укри́тися от мучи́телей, і́бо ти, я́ві без стра́ха Христа́ всім іспові́дав, си́лою сло́ва обраще́ніє мно́гих ко Христу́ устро́їл і мно́гія в неду́зіх і́менем Єго́ ісціли́л єси́. Уві́дівше же о тебі́, святи́й Три́фоне, іге́мон Аквили́н, взя тя і пред суди́щем поста́ви, ти же вся гряду́щая на тя в ру́ці Бо́га твоєго́ преда́л єси́, ра́дуяся я́ко і тя сподо́би Госпо́дь би́ти о́бщника страда́ній Єго́, і ві́рнії, ви́дяще ре́вность твою́ по Бо́зі, вопія́ху ті:","Ра́дуйся, Три́фоне, ко спасе́нію мно́гих приведи́й;","ра́дуйся, мно́гих от злові́рія к ві́рі і́стинній, правосла́вній обрати́вий.","Ра́дуйся, чудеси́ твої́ми, си́лою Бо́жиєю соді́янними, во ві́рі, і́ми восприя́той, їх утверди́вий;","ра́дуйся, я́ко ді́йственная ві́ра твоя́ в Бо́га ви́ну всім по всей вселе́нній яви́ся.","Ра́дуйся, безме́здний врачу́, си́лою Бо́жиєю, я́коже дре́вле, та́кожде і ни́ні вся́кую болі́знь ско́ро врачу́ющий;","ра́дуйся, наде́ждо оста́вленних врача́ми.","Ра́дуйся, ско́роє утіше́ніє боля́щих, к тебі́ с моли́твою прибіга́ющих;","ра́дуйся, небоя́зненно пропові́давий Христо́ву ві́ру.","Ра́дуйся, от неві́рних за про́повідь Христа́ Бо́га на муче́ніє я́тий;","ра́дуйся, не устраши́вийся гряду́щаго муче́нія.","Ра́дуйся, науча́ющий нас не боя́тися челові́чеських преще́ній;","ра́дуйся, во всем на Бо́га упова́ніє возложи́вий.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 8","ps":["Усли́шав, я́ко і́щуть тя во́їни, не утаї́лся єси́ от них, му́чениче, ні в гора́х, ні в пусти́ніх, но, огради́вся моли́твою і кресто́м, дерзнове́нно себі́ преда́л єси́ в ру́ці мучи́телей і с ра́достію вели́кою стопи́ твоя́ напра́вил в Ніке́ю, да возвісти́ши всім ві́ру і́стинную і наста́виши пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Єгда́ вопроси́ тя іге́мон на суди́лище: «Кто єси́, ка́я судьба́ твоя́, і ка́ко ві́руєши?», ти, не обину́яся, отвіща́л єси́ єму́ си́це: «Три́фон і́м'я моє́; оте́чество - Компса́да; судьби́ же ність у нас, зане́ ві́руєм, я́ко вся Про́мислом Бо́жиїм бива́ють. По ві́рі же - христия́нин єсьм, Христо́с же єсть і моя́ си́ла, і моя́ крі́пость, і сла́ва, і ра́дость моя́». Сіє́ іспові́даніє твоє́ сли́шаще, ублажа́єм тя, святи́й Три́фоне, си́це:","Ра́дуйся, непра́ведному суди́лищу дерзнове́нно предста́вий;","ра́дуйся, ві́рующих в про́мисл Бо́жий укріпля́яй.","Ра́дуйся, лю́ди, живо́т свой судьбі́ вверя́ющия, посрамля́яй;","ра́дуйся, науча́яй нас во всем упова́ніє на́ше на Бо́га возла́гати.","Ра́дуйся, ви́ну себі́ би́ти служи́теля Христо́ва іспові́дуяй;","ра́дуйся, іспові́данієм тім весе́ліє ві́рним да́руяй.","Ра́дуйся, собо́рища нечести́вих іспові́данієм святи́м отлучи́вийся;","ра́дуйся, гряду́щих муче́ній от нечести́вих за іспові́даніє і́стиннаго Бо́га не устраши́вийся.","Ра́дуйся, і́стину єди́ную, Боже́ственную возлюби́вий;","ра́дуйся, лжі і отця́ єя́, дия́вола, отверги́йся.","Ра́дуйся, Христа́ свої́м упова́нієм імену́яй;","ра́дуйся, Єго́ своє́ю крі́постію нариця́яй.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 9","ps":["Сли́шавше твоє́ іспові́даніє, я́рости іспо́лнишася нечести́вії і преща́ху ті ра́нами і муче́нієм. Ти же, му́чениче Три́фоне, под'я́тіє страда́ній за Христа́ весе́лієм почита́я, взива́л єси́ немо́лчно Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нний Аквили́н, ви́дя, я́ко ти не убоя́лся єси́ преще́ній лю́тих, я́ко овча́ кро́ткоє яви́ся, іща́ прельсти́ти тя словеси́ ласка́тельними, но, нічто́же успева́я, па́ки во во́лка лю́таго обра́щся, усугубля́ше преще́нія своя́. Ти же тверд і непоколеби́м преби́л єси́ благода́тію Бо́жиєю, воздвиза́я ві́рних возглаша́ти тебі́ сицева́я:","Ра́дуйся, преще́ній лю́тих не убоя́вийся;","ра́дуйся, сме́рті тіле́сной не устраши́вийся.","Ра́дуйся, ду́шу свою́ за ві́ру правосла́вную положи́ти не отре́кшийся;","ра́дуйся, ра́зум соверше́нний в том положи́вий, да сохрани́ши ві́ру і́стинную во Єди́наго Бо́га.","Ра́дуйся, не к земні́й, но к Небе́сній му́дрости устреми́вийся;","ра́дуйся, іге́мону, врагу́ твоєму́, спасе́нія жела́вий.","Ра́дуйся, к позна́нію і́стиннаго Бо́га привести́ мучи́теля твоєго́ тща́вийся;","ра́дуйся, пропові́дниче Христо́в сладкогла́сний.","Ра́дуйся, христия́нине, Христо́м возлю́бленний;","ра́дуйся, во́лею на страда́нія ше́дий.","Ра́дуйся, муче́ній тіх за Христа́, я́ко сокро́вища, хоті́вий;","ра́дуйся, во вре́м'я муче́ній лю́тих Боже́ственним сві́том осія́нний.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 10","ps":["Усли́шав тя глаго́лавша, я́ко не іспові́дующих і́стинния, правосла́вния ві́ри жре́бій єсть огнь неугаси́мий, зіло́ разгні́вася Аквили́н і повелі́ тя, святи́й Три́фоне, пове́сив, би́ти; ти же, в повелі́нії сем усли́шав Госпо́день глас, призива́вший тя на страда́льчеський по́двиг, возопи́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Я́ко свіща́ огне́м возгара́ється, та́ко душа́ твоя́, святи́й Три́фоне, возгорі́ся любо́вію к возлюби́вшему тя Бо́гу, і, усли́шав повелі́ніє іге́мона, є́же на тя, сам совле́кл єси́ ри́зи твоя́ і ті́ло твоє́ преда́л єси́ в ру́ці мучи́телей, да сотворя́ть вся, я́же повелі́ іге́мон. Зря́ще такову́ю ре́вность твою́ по Бо́зі, всі ві́рнії глаго́лаху:","Ра́дуйся, с весе́лієм угото́вавий себі́ к прия́тію ран за Христа́;","ра́дуйся, риз свої́х совлеки́йся ра́ди обнаже́ннаго ні́когда за гріхи́ на́ша Іскупи́теля.","Ра́дуйся, доброво́льно в ру́ці мучи́телей себі́ преда́вий, Христу́ подража́я;","ра́дуйся, от них свя́занний і пове́шенний на муче́ніє.","Ра́дуйся, прия́вий за Христа́ лю́тая ударе́нія;","ра́дуйся, три ча́са терпі́вий неща́дноє біє́ніє.","Ра́дуйся, му́чиму би́вшу, ні єди́наго стена́нія і ні єди́наго гла́са іспусти́вий;","ра́дуйся, біє́нія, у́зи, ра́ни, опале́нія і іни́я многоразли́чния страда́нія претерпі́вий.","Ра́дуйся, в молча́нії прия́вий ударе́нія, от ни́хже ра́нами із'я́звися ті́ло твоє́;","ра́дуйся, страда́нієм свої́м си́лу Бо́жию просла́вивий.","Ра́дуйся, терпі́нієм свої́м мучи́телей посрами́вий;","ра́дуйся, по́двигом свої́м христия́н возвесели́вий.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 11","ps":["Ви́діша терпі́ніє і по́двиг твой, святи́й Три́фоне, єще́ же і адама́нтову крі́пость твою́, і просла́виша предстоя́щії лю́діє Подвигополо́жника Христа́ Бо́га пі́снію: Аллилу́я."]},{"h":"Ікос 11","ps":["Я́ко сті́ну тве́рду і непоколеби́му ви́ді тя нечести́вий судія́, оба́че не просла́ви Бо́га, дарова́вшаго тебі́ крі́пость сію́, но па́че тща́шеся склони́ти тя і ле́стію і стра́хом сме́рті, да принесе́ши же́ртву бі́совом. Ти же, святи́й му́чениче, іспові́дав во у́шію всіх ві́ру Христо́ву, обличи́л єси́ безу́міє гони́телей і показа́л єси́ му́дрость тіх, і́же во Христа́ ві́рують; іге́мон же, ізмишля́я на тя іна́я муче́нія, повелі́ тя со столпа́ сня́ти і, прив'яза́в ко коню́ своєму́, влече́ за собо́ю. Ми же потщі́мся просла́вити страда́нія твоя́:","Ра́дуйся, уя́звленний ті́лом і за коне́м би́стро влеко́мий;","ра́дуйся, хлад зи́мній претерпі́вий.","Ра́дуйся, науча́яй нас в ско́рбіх земни́х ум свой к Бо́гу устремля́ти;","ра́дуйся, наставля́яй в ми́рі сем хла́дном согріва́тися любо́вію, я́же к Бо́гу.","Ра́дуйся, ді́лом нам показу́яй, ка́ко подоба́єть ні во что же вміня́ти скоропреходя́щая на землі́ страда́нія;","ра́дуйся, любве́ і милосе́рдія ко всім лю́дем іспо́лненний.","Ра́дуйся, ра́ди любве́ тоя́ за враги́ своя́ моли́тви Бо́гу возноси́вий;","ра́дуйся, па́ки в темни́цю вве́рженний і в заточе́нії лю́том томле́ніє, му́ку і болі́зні претерпі́вий.","Ра́дуйся, я́сно явля́ющий, я́ко люті́йшая страда́нія земна́я нічто́же суть, а́ще к Бо́гу прибіга́ють лю́діє і Бо́га ра́ди те́рп'ят ско́рби і ра́ни;","ра́дуйся, на усікнове́ніє глави́ твоєя́ ра́достно ше́дий і пред усікнове́нієм тім в ру́ці Бо́га твоєго́, Єго́же ра́ди вся лю́тая под'я́л єси́, ду́шу свою́ святу́ю преда́вий.","Ра́дуйся, пре́жде усікнове́нія моли́вийся о вся́ком, і́же воспомина́ти тя і в па́м'ять твою́ святи́я же́ртви приноси́ти бу́деть, да усли́шить єго́ Госпо́дь і вся́коє проше́ніє єго́ іспо́лнить;","ра́дуйся, по успе́нії твоє́м во виді́нії повелі́вий погребсти́ тя во оте́чествії твоє́м, науча́я тім і нас своє́ оте́чество люби́ти.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 12","ps":["Не то́кмо на землі́, святи́й му́чениче, бил єси́ помо́щник і засту́пник всім, твоєя́ по́мощі тре́бующим, но і по сме́рті не престає́ши ізбавля́ти от бід к тебі́ с ві́рою і любо́вію притека́ющих, я́коже ізба́вил єси́ ца́рськаго гні́ва боля́рина Три́фона, єгда́ внеза́пу яви́лся єму́ на коні́ і дал єси́ єму́ отлете́вшаго ца́рськаго со́кола. О́ний же Три́фон соко́льник на мі́сті сем, іді́же єму́ от тебе́ по́мощ яви́ся, во благодаре́ніє тебі́ за ізбавле́ніє своє́ воздви́же святи́й храм во і́м'я твоє́, му́чениче Три́фоне. Ми же благодія́нія, от тебе́ би́вшая, воспомина́юще, возно́сим благода́рственную Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ многоразли́чная чудеса́, твою́ ди́вную і ско́рою по́мощ, я́ко нікого́же усе́рдно прибіга́ющаго к тебі́ с ві́рою, любо́вію і упова́нієм нікогда́же отри́нул єси́, но всіх к тебі́ притека́ющих і пред свято́ю іко́ною твоє́ю смире́нно моля́щихся от внеза́пних бід і скорбе́й ізбавля́єши, про́чеє вре́м'я живота́ їх во бла́го устроя́єши, неду́зі врачу́єши, печа́лі утоля́єши і кому́ждо в біда́х і ско́рбіх к тебі́ припа́дающему по́мощ і осла́бу да́руєши, благода́рні восхваля́єм тя си́це:","Ра́дуйся, на́ша моле́нія і проше́нія приє́мляй;","ра́дуйся, за ни пред Престо́лом Бо́жиїм моля́щийся.","Ра́дуйся, от Бо́га ми́лости нам непреста́нно прося́щий;","ра́дуйся, от неча́янних бід і зол непрело́жноє на́ше ізбавле́ніє.","Ра́дуйся, от бід і напа́стей, дви́жимих на ни гріх ра́ди на́ших, ско́роє прибі́жище;","ра́дуйся, мно́гія сле́зи, от ско́рби пролива́ємия, ізсуши́вий.","Ра́дуйся, мно́гія печа́лі утоли́вий;","ра́дуйся, нікто́же припа́дий к святі́й іко́ні твоє́й тощ от нея́ оти́де.","Ра́дуйся, вся́каго притека́ющаго к тебі́ под кров свой і заступле́ніє приє́мляй;","ра́дуйся, здра́вія тре́бующим ско́роє ісціле́ніє.","Ра́дуйся, оста́вленних врача́ми і ра́ди неісці́льних і тя́жких неду́г свої́х ча́ющих себі́ сме́рті, ско́роє і безме́здноє врачева́ніє;","ра́дуйся, і ни́ні, я́коже і дре́вле, жи́ву ті су́щу, неізсяка́ємий істо́чниче неізче́тних і многообра́зних чудотворе́ній.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 13","ps":["О святи́й му́чениче Три́фоне! Прийми́ сіє́ ма́лоє, оба́че от лю́б'ящих і благода́рних серде́ць приноси́моє тебі́ на́ше моле́ніє, вознеси́ ко Го́споду Бо́гу те́плия моли́тви твоя́ за ни, недосто́йния: боля́щия ісціли́, печа́льния уті́ши, заблу́ждшия вразуми́, бе́дствующим помози́, і вся нам потре́бная для здра́вія тіле́снаго і спасе́нія душе́внаго у Бо́га Щедрода́вця іспроси́, найпа́че же ізба́ви нас от лука́вих бісо́в, да пам'яту́я ви́ну твоя́ ди́вная о нас заступле́нія, просла́вим Бо́га, дарова́вшаго нам такова́го моли́твенника, ціли́теля і чудотво́рця, воспіва́юще піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["О́бразу благоче́стія роди́телей твої́х подража́я, христия́нськия нра́ви от літ ма́лих прия́л єси́, святи́й му́чениче, і мал сий лі́ти, стар же ра́зумом, воі́стину христия́нин соверше́н яви́лся єси́. Ми же, воспомина́юще доброді́тельноє житіє́ твоє́, восхваля́єм тя си́це:","Ра́дуйся, добронра́вних роди́телей благочести́вий си́не;","ра́дуйся, вели́коє їх утіше́ніє.","Ра́дуйся, А́нгела твоєго́ Храни́теля непреста́нноє весе́ліє;","ра́дуйся, от ю́ности твоєя́ всего́ себе́ Бо́гу преда́вий.","Ра́дуйся, от ю́ности Христа́ возлюби́вий;","ра́дуйся, от ма́лих літ благода́ть Бо́жию оби́льно стяжа́вий.","Ра́дуйся, ду́шу свою́ непоро́чну яви́вий;","ра́дуйся, себі́ самаго́ в храм Ду́ха Свята́го угото́вавий.","Ра́дуйся, о́троком о́браз житія́ свята́го показа́вий;","ра́дуйся, благоче́стієм твої́м ві́рния возвеселя́яй.","Ра́дуйся, от ма́лих літ за вся сія́ Бо́гом возлю́бленний.","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим."]},{"h":"Кондак 1","ps":["Ізбра́нний от Бо́га і к ли́ку святи́х сопричте́нний, святи́й му́чениче Три́фоне! Моли́ся о нас, грі́шних, Влади́ці Христу́ і помога́й нам побіжда́ти мир, плоть і дия́вола, многообра́зно вою́ющия на ни, я́коже побіди́л єси́ їх благода́тію і си́лою возлю́бленнаго тобо́ю Христа́, да, ізба́вльшеся от враго́в на́ших ви́димих і неви́димих, благода́рственно воззове́м ті:","Ра́дуйся, Три́фоне, ско́рий помо́щниче всім, с ві́рою і любо́вію к тебі́ притека́ющим!"]},{"h":"Молитва","ps":["О святи́й му́чениче Христо́в Три́фоне, ско́рий помо́щниче і всім к тебі́ прибега́ющим і моля́щимся пред святи́м твої́м о́бразом скоропослу́шний предста́телю! Усли́ши ни́ні і на вся́кий час моле́ніє нас, недосто́йних рабо́в твої́х, почита́ющих святу́ю па́м'ять твою́ во всечестні́м хра́мі сем, і предста́тельствуй о нас пред Го́сподем на вся́ком мі́сті. Ти бо, уго́дниче Христо́в, во вели́ких чудесі́х возсія́вий, істоча́яй цільби́ притека́ющим к тебі́ с ві́рою і су́щия в ско́рбіх челові́ки заступа́яй, сам обіща́лся єси́ пре́жде ісхо́да твоєго́ от житія́ сего́ тлі́ннаго моли́тися за ни ко Го́споду і іспроси́л єси́ у Него́ дар сей: а́ще кто в како́й-ли́бо нужді́, печа́лі і болі́зні душе́вній іли́ тіле́сній призива́ти начне́ть свято́є і́м'я твоє́, той да ізба́влен бу́деть от вся́каго прило́га зла́го. І я́коже ти іногда́ дщер царе́ву, в Ри́мі гра́де от дия́вола му́чиму, ісціли́л єси́, си́це і нас от лю́тих єго́ ко́зней сохрани́ во вся дні живота́ на́шего, найпа́че же в день послі́дняго на́шего іздиха́нія предста́тельствуй о нас. Бу́ди нам тогда́ помо́щник і ско́рий прогони́тель лука́вих духо́в, і к Ца́рствію Небе́сному предводи́тель. І іді́же ти ни́ні предстої́ши с ли́ки святи́х у Престо́ла Бо́жия, моли́ Го́спода, да сподо́бит і нас прича́стники би́ти присносу́щнаго весе́лія і ра́дости, да с тобо́ю ку́пно прославля́єм Отця́ і Си́на і Свята́го Уті́шителя Ду́ха во ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Му́ченик Твой, Го́споди, Три́фон / во страда́нії своє́м віне́ць прия́т нетлі́нний от Тебе́, Бо́га на́шего: / імі́яй бо крі́пость Твою́, / мучи́телей низложи́, / сокруши́ і де́монов немощни́я де́рзости. / Того́ моли́твами // спаси́ ду́ші на́ша."]},{"h":"Інший тропар, глас 4","ps":["Пи́щі Боже́ственния, треблаже́нне, / наслажда́яся на Небесі́х неоску́дно, / сла́в'ящих пі́сньми па́м'ять твою́ покри́й / і сохрани́ от вся́кия ну́жди, / отжени́ вредя́щих ни́вам живо́тних, / да тебі́ от любве́ вопіє́м всегда́: // ра́дуйся, Три́фоне, му́чеников укріпле́ніє."]},{"h":"Кондак, глас 8","ps":["Тро́йчеською тве́рдостію / многобо́жіє разруши́л єси́ от коне́ць, всесла́вне, / че́стен во Христі́ бив, і, побіди́в мучи́телі во Христі́ Спаси́телі, / віне́ць прия́л єси́ му́ченичества твоєго́ / і дарова́нія Боже́ственних ісціле́ній, // я́ко непобіди́мь."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпче святи́й Три́фоне, і чтим честна́я страда́нія твоя́, я́же за Христа́ претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст святим мученикам Адріану і Наталії","e":"Akathist to the Holy Martyrs Adrian and Natalia","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії служи́теліє Бо́жії і всехва́льнії му́ченици Христо́ві, всю ми́ра сего́ суєту́ презрі́вшії любве́ ра́ди ко Христу́, Си́ну Бо́жию, і живо́т свой положи́вшії, я́ко же́ртву непоро́чную і чи́стую, па́че жела́я прия́ти муче́нія і смерть, не́же отрещи́ся Бо́га і́стиннаго, восхваля́єм ви любо́вію, святі́ї Адрія́не і Ната́ліє! Ви же, во весе́лії предстоя́ще Престо́лу сла́ви Госпо́дні і ви́ну наслажда́ющеся Того́ лицезрі́нієм, молі́теся о нас, грі́шних, с ві́рою і благогові́нієм к вам притека́ющих, да благода́рственно вопіє́м вам:","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Ікос 1","ps":["А́нгельською ко Го́споду горя́щи любо́вію, непреста́нно возсилала єси́ усе́рдния моли́тви к Бо́гу Спаси́телю твоєму́, Ната́ліє всеблаже́нная, да просвіти́ть луче́м Своєя́ благода́ті помраче́нноє се́рдце супру́га твоєго́ і обрати́ть є к позна́нію Єго́, Творця́ і Влади́ки твоєго́, до́ндеже Цар царе́й усли́ша сле́зния проше́нія твоя́ і косну́ся се́рдця Адріянова, і а́біє уві́рова супру́г твой от всея́ душі́, і бо́дренним се́рдцем претерпі́ люті́йшия муки́, і са́мую смерть за Христа́ не убоя́ся прия́ти. Ті́мже благогові́йно удивля́ющеся ва́шей ко Христу́ любві́ і ре́вности по Бо́зі, ра́достно взива́єм вам:","Ра́дуйтеся, світи́льници всесві́тлії, горя́щії любо́вію Боже́ственною;","ра́дуйтеся, столпи́ непоколеби́мії проти́ву озлобле́ній ідолослужи́телей нечести́вих.","Ра́дуйтеся, Крест Христо́в с терпі́нієм і преданностію поне́сшії;","ра́дуйтеся, сим побі́ди святи́я зна́менієм побіди́вшії дия́вола і єго́ ко́зні посрами́вшії.","Ра́дуйтеся, нетлі́нія вінці́ восприя́вшії і сла́вою от Го́спода вінча́ннії;","ра́дуйтеся, я́ко ни́ні на Небесі́ предстоїте́ Престо́лу Вседержителеву і молі́теся за ни, грі́шния.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь чистоту́ се́рдця твоєго́, Адрія́не всече́стне, а́ще і помраче́ннаго тьмо́ю многобо́жія, оба́че гото́ваго прия́ти І́стину, благоволи́ призва́ти тя в чу́дний Свой світ і откри́ти тебі́ две́рі Ца́рствія Своєго́, моли́твами святи́я супру́жници твоєя́, с не́юже во весе́лії взива́л єси́ Трієди́ному Бо́гу, просвіти́вшему твою́ ду́шу, хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум і́стиннаго богові́дінія внеза́пу об'я ду́шу твою́, Адрія́не, єгда́, по повелі́нію царе́ву, вписивал єси́ с про́чими нотарії імена́ святи́х му́ченик, на страда́ніє і смерть за і́м'я Христо́во ведо́мих, єгда́ бо вопроси́л єси́ служи́телей Госпо́дніх, ко́є воздая́ніє і́муть прия́ти от Го́спода во Ца́рствії Єго́ за вся муки́, ті́ї отвіща́ша ті, я́ко ність мо́щно бре́нному язи́ку ізрещи́ і уму́ слабому пости́гнути, я́же угото́ва Бог лю́б'ящим Єго́. Ти же, а́біє оста́вль все і́дольськоє злові́ріє, всім се́рдцем ко Христу́ устреми́лся єси́ і возопи́л єси́ дерзнове́нно: «І аз христия́нин єсьм!» Почита́юще у́бо твоє́ обраще́ніє ко і́стинному Со́лнцю Пра́вди мо́лим тя, прийми́ вку́пі с супру́жницею твоє́ю, свято́ю Ната́лією, от нас, грі́шних, похвали́ сицеви́я:","Ра́дуйтеся, і́стиннаго Бо́га святі́ї служи́теліє;","ра́дуйтеся, Того́ во́лі ревностнії ісполни́теліє.","Ра́дуйтеся, я́ко вся кра́сная і сла́дкая ми́ра сего́ любве́ ра́ди Христо́ви презрі́ли єсте́;","ра́дуйтеся, я́ко любо́в земну́ю і супру́жеськоє сча́стіє в же́ртву Возлюби́вшему ви принесли́ єсте́.","Ра́дуйтеся, научающії нас не приліпля́тися к земни́м бла́гам, но возноси́тися ду́хом горі́, к Бо́гу;","ра́дуйтеся, не́мощ на́шу просвіща́ющії і восходи́ти на лі́ствицю святи́ні нам помога́ющії.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 3","ps":["Си́лою сви́ше укрепленний, ше́ствовал єси́, блаже́нне, му́жественно на предлежа́щий ті по́двиг, жажда́я умре́ти за возлю́бленнаго Спаси́теля і Бо́га твоєго́. Супру́жниця же твоя́, свята́я Наталія, моли́твами і увещанії помога́ше ті под'яти крест, от Го́спода тебі́ посила́ємий, і прия́ти і віне́ць нетлі́нія, угото́ванний ті на Небесах, і дерзнове́нно Бо́гу воспіва́ти: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй ізи́ти на беззако́нноє суди́ще Максиміяново, затворе́н бил єси́ в темни́цю мра́чную, іді́же с про́чими святи́ми му́ченики всю нощ в моли́твах, піснопі́ніїх і бесі́дах духо́вних прове́л єси́. Любвеоби́льная же супру́жниця твоя́, не́мощ же́нськую презрі́вши і єсте́ственную любо́в плотську́ю ні во что́же вміни́вши, вся́чеськи тя убеждаше не отступа́ти от ві́ри Христо́ви, но до конця́ преби́ти непоколеби́мим іспові́дником і́мене Ісу́сова і не боя́тися сме́рті. Ті́мже вам, я́ко і́стинним во́їном Христо́вим, в духо́вном весе́лії взива́єм:","Ра́дуйтеся, правові́рія му́жественнії ревни́теліє;","ра́дуйтеся, злові́рія неустрашимії обличи́теліє.","Ра́дуйтеся, терпі́нієм, я́ко крі́пкою броне́ю, обле́кшіїся;","ра́дуйтеся, Крест Христо́в я́ко непобіди́моє ору́жіє в ру́ці приє́мшії.","Ра́дуйтеся, я́ко беззако́нних мучи́телей преєсте́ственним му́жеством ва́шим удивили єсте́;","ра́дуйтеся, я́ко ва́ми і́м'я Бо́жиє просла́вися.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 4","ps":["Бу́рю малоду́шія і боя́зні от се́рдця твоєго́ отгоня́ющи, сла́вно Адрія́не, і на предлежа́щий му́ченичеський по́двиг тя укріпля́ющи, блаже́нная жена́ твоя́ Ната́лія всю нощ не престава́ше с тобо́ю бесі́довати о чу́дном і вели́цім воздая́нії, є́же Бог угото́ва за Него́ живо́т свой положившим, і та́ко віща́ше тебі́: «Блаже́н єси́, господи́не мой, я́ко обрі́л єси́ сокро́вище безці́нноє, драгоці́нний би́сер - Христа́ Го́спода твоєго́! Не отступа́й па́ки во тьму і́дольськую, но ви́ну пребива́й ві́рен Возлюби́вшему тя, вопія́ Єму́ от всего́ се́рдця: Аллилу́я»."]},{"h":"Ікос 4","ps":["Сли́ша свята́я Ната́лія, в до́му своє́м сідя́щая, я́ко гряде́ши к ней із темни́ці, і возмневши, я́ко мук убоя́лся єси́ і отве́рглся єси́ Христа́, пла́кася го́рко і, предте́кши тебі́ із две́рей до́ма, нача́ укоря́ти тя, почто́ от ві́ри Христо́ви отступи́л єси́. Ти же, ра́дуяся ду́хом і па́че укріпля́яся на страда́нія, со слеза́ми єй пові́дал єси́, я́ко не то́кмо не отступи́л єси́ от Христа́, но па́че жела́єши за і́м'я Єго́ Свято́є страда́ти. Такові́й висоті́ любве́ христия́нськия удивля́ющеся, со умиле́нієм вам взива́єм:","Ра́дуйтеся, о́браз і́стинний супру́жества христия́нськаго явившії;","ра́дуйтеся, любо́в небе́сную в себі́ поі́стинні показа́вшії.","Ра́дуйтеся, на по́двиг самоотверже́нія Христа́ ра́ди нас одушевляющії;","ра́дуйтеся, вся кра́сная ми́ра сего́ преходя́щаго презира́ти нас научающії.","Ра́дуйтеся, до́льняя оставля́ти і ду́хом взлетати ко го́рнім нас увещевающії;","ра́дуйтеся, во всіх, бива́ємих с на́ми, во́лю Бо́жию зрі́ти нам помога́ющії.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 5","ps":["Чу́дноє милосе́рдіє і любо́в показу́ющи, о Ната́ліє, припадала єси́ к нога́м у́зников, в темни́ці вку́пі с муже́м твої́м за і́м'я Христо́во заключе́нних, і свяще́нния я́зви їх лобиза́ющи, отирала єси́ гной їх, облегче́ніє і отра́ду вся́чеськи їм содіва́я і в серде́чном умиле́нії к Бо́гу Небе́сному вопію́щи а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Узрі́в мучи́тель злочести́вий у́зники святи́я, в темни́ці с тобо́ю затворе́нния, толи́каго от ран ізнеможе́нія достигшия, я́ко отню́д не мо́щі їм претерпі́ти люті́йшия муки́, повелі́ єди́наго тя, Адрія́не, привести́ пред суди́ще своє́ і вся́чеськи тя увіщева́ше отрещи́ся Христа́, устраша́я тя предлежа́щими му́ками. Оба́че, ви́ше укріпля́ємий і блаже́нною супру́гою твоє́ю утешаємий, преби́л єси́ тверд, а́ки адама́нт, проти́ву іскуше́нія вра́жеськаго. Сего́ ра́ди твоє́ за Христа́ страда́ніє любо́вію ублажа́юще і святу́ю супру́жницю твою́ велича́юще, ра́достно вам взива́єм:","Ра́дуйтеся, Бо́га Ви́шняго побідоно́снії служи́теліє;","ра́дуйтеся, ві́ри Христо́ви громогласнії іспові́дниці.","Ра́дуйтеся, і́дольськия пре́лести дерзнове́ннії обличи́теліє;","ра́дуйтеся, сла́ви Бо́жия неустрашимії пропові́дателіє.","Ра́дуйтеся, Максиміянова гні́ва не убоявшіїся;","ра́дуйтеся, того́ я́рость ні во что́же вміни́вшії.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 6","ps":["Пропові́дник велегла́сний яви́лся єси́, Адрія́не, єгда́, предстоя́ суди́щу царе́ву, небоя́зненно ісповедивал єси́ Христа́ би́ти Бо́га і́стиннаго, сотвори́вшаго не́бо і зе́млю, і́дольськую же пре́лесть обличи́л єси́, і за сіє́ іспові́даніє і обличе́ніє жесточайшеє біє́ніє под'ял єси́, к Подвигополо́жнику твоєму́ вопія́: Аллилу́я."]},{"h":"Ікос 6","ps":["Світ сла́ви Небе́сния осія́ лице́ твоє́, му́дрий страда́льче, єгда́ по чре́ву біє́мий, я́ко і утро́бі твоє́й ізлія́тися от же́стоких ударов, не престава́л єси́ сла́вити Христа́ і пред всім наро́дом і́м'я Єго́ Свято́є іспові́дати. Блаже́нная же Ната́лія ра́довашеся ду́хом, зря́щи терпі́ніє твоє́ і му́жество, і моли́твенно тя укріпля́ше, да не ізнемо́жеть душа́ твоя́ і да пребу́деши до конця́ ві́рний служи́тель Христо́в, є́йже вку́пі с тобо́ю ми, грі́шнії, воспіва́єм си́це:","Ра́дуйтеся, Ду́ха Свята́го свяще́нная жили́ща;","ра́дуйтеся, благода́ті Христо́ви сла́вная вмісти́лища.","Ра́дуйтеся, душе́вно і тіле́сно сві́том Боже́ственним осіяваємії;","ра́дуйтеся, от Христа́ Царя́ сви́ше просвіща́ємії.","Ра́дуйтеся, си́лою Божества́ Єго́ укрепляємії;","ра́дуйтеся, на по́двиг страда́нія небоя́зненно ше́ствовавшії.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 7","ps":["Хотя́ цар злочести́вий па́ки тя призва́ти на суди́щі, сла́вно Адрія́не, в темни́цю тя затвори́ с про́чими святи́ми му́ченики, іді́же приступи́ к тебі́ Ната́лія свята́я і нача́ терпі́ніє твоє́ ублажа́ти і укріпля́ти тя, глаго́лющи: «Блаже́н єси́, господи́не мой, я́ко сподо́бился єси́ ча́сти святи́х му́чеников Христо́вих!» С не́юже ра́дуяся, Бо́гу взива́л єси́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую кознь ізмишляя мучи́тель злий, повелі́ во́єм свої́м отню́д не впускати в темни́цю к у́зником жен, із гра́да приходя́щих утіше́нія ра́ди і облегче́нія страда́льцев Христо́вих. Тогда́ і тебі́, свята́я Ната́ліє, возбранено́ бисть му́жа твоєго́ ви́діти і служи́ти єму́; оба́че повелі́ніє царе́во небре́гши, в мужеськом оді́янії в темни́цю приходи́ла єси́ і я́коже пре́жде свята́го супру́га твоєго́ подкрепляла єси́, да му́жественно гряде́ть на муче́нія і смерть за Христа́ Го́спода. Сего́ ра́ди досто́йно восхваля́єм тя вку́пі со святи́м муже́м твої́м і си́це вам вопіє́м:","Ра́дуйтеся, служи́телей Христо́вих украше́ніє пресві́тлоє;","ра́дуйтеся, іспові́дников і́мене Ісу́сова велелі́пная сла́во.","Ра́дуйтеся, путь у́зький возлюбльшії і нам єго́ указу́ющії;","ра́дуйтеся, я́ко путе́м сим ти́хаго приста́нища, Ца́рствія Христо́ва, достиго́сте.","Ра́дуйтеся, я́ко ни́ні в сла́ві і блаже́нстві несконча́ємім пребива́єте;","ра́дуйтеся, я́ко нас моли́твами ва́шими от бід і напа́стей сохраня́єте.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 8","ps":["Стра́нноє і чу́дноє зри́мо бисть в темни́ці, іді́же заключе́н бил єси́, Адрія́не, с про́чими страда́льці Христо́вими, єгда́ по повелі́нію гро́знаго мучи́теля го́лени твої́ сокруша́ти хотя́ху. Тогда́ бо свята́я жена́ твоя́ сама́ под'я но́зі твої́ і положи́ їх на наковальню, да пребіються от мук мучи́тельських, і ти скорі́є соєдини́шися с Господом твої́м, воспіва́я непреста́нно Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь го́ря любо́вію ко Христу́, му́чениче Адрія́не, в терпі́нії пребива́л єси́ до са́мия блаже́нния кончи́ни твоєя́, єгда́ чи́стая душа́ твоя́ с Господом твої́м соєдини́ся, за Єго́же і́м'я толи́ко страда́л єси́, я́ко і ру́ці твоє́й отсеченной би́ти. Почита́юще у́бо твою́ му́ченичеськую кончи́ну, ві́рою тебі́ і святі́й Ната́лії взива́єм:","Ра́дуйтеся, душевниє муки́ вку́пі с тіле́сними за Христа́ претерпі́вшії;","ра́дуйтеся, крила́ми небе́сния любве́ горі́ к Бо́гу возлетевшії.","Ра́дуйтеся, я́ко орли́, к Со́лнцю Пра́вди воспарившії;","ра́дуйтеся, к Сві́ту Невече́рнему із юдо́лі пла́ча возвисившіїся.","Ра́дуйтеся, в со́нмі святи́х му́ченик водворившіїся;","ра́дуйтеся, вку́пі со всі́ми святи́ми на Небесі́х чу́дную піснь Бо́гу воспіва́ющії.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 9","ps":["Вся горди́ня мучи́теля безчелові́чнаго посра́млена бисть, єгда́ си́льний дождь погаси́ пла́мень о́гненний і не допусти сгорі́ти честни́м оста́нком святи́х му́ченик Христо́вих, єще́ же і град весь потопле́н бисть водо́ю, і лю́ди нечести́вії гро́мом і мо́лнією устраше́ни би́ша. Ти же, блаже́нная Ната́лія, во весе́лії воспіва́ла єси́ Христу́, вся благоустрояющему: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство похва́л земни́х не довлі́єть ко восхвале́нію по́двигов ва́ших, святі́ї му́ченици Христо́ві Адрія́не і Ната́ліє, ов у́бо о вре́менній сла́ві і вели́чії земно́м небре́г, вся оста́ви і положи́ ду́шу свою́ за ві́ру во Христа́, о́ва же, єсте́ственную же́нськую не́мощ преодолевши, му́жеськи подвиза́ся, укріпля́ющи супру́га своєго́ в єго́ муче́ніїх і ра́дующися єго́ блаже́нній кончи́ні. Толи́кая дія́нія ва́ша досто́йно восхвали́ти недоумі́юще, с любо́вію вам взива́єм:","Ра́дуйтеся, бо́дренним се́рдцем Крест Христо́в на ра́мо под'ємшії;","ра́дуйтеся, под тя́жестію єго́ не ізнемогшії.","Ра́дуйтеся, подража́теліє Христо́вих страсте́й би́вшії;","ра́дуйтеся, плоть ва́шу со страстьми́ і похотьми́ расп'явшії.","Ра́дуйтеся, о́браз любве́ і кро́тости в себі́ показа́вшії;","ра́дуйтеся, друг дру́га тяготи́ носи́ти нас научи́вшії.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 10","ps":["Спасти́ хотя́ тілеса́ святи́х му́ченик от поруга́нія і безче́стія, при́йде ні́кий благочести́вий муж с жено́ю своє́ю ко святі́й Ната́лії і про́чей бра́тії христия́нстій, прося́ їх соізволити єму́, да во́зьметь с собо́ю во Византій святи́я мо́щі і положи́ть їх та́мо че́стно до вре́мене, єгда́ у́мреть Максимія́н злочести́вий. Христия́не же гра́да Никомиді́ї соізво́лиша проше́нію сего́ му́жа і препоручивше єму́ многоці́нноє сокро́вище, Бо́гу ра́достно вопія́ху: Аллилу́я."]},{"h":"Ікос 10","ps":["Я́ко стіно́ю огражда́єми єсьми́ ва́шими святи́ми моли́твами, святі́ї Адрія́не і Ната́ліє, се бо во вся́ких біда́х і напа́стіх на́ших нам всегда́ помога́єте, найпа́че же єгда́ па́м'ять ва́шу с любо́вію пра́зднуєм і сла́вим о вас Христа́ Бо́га на́шего. Сохраня́ємії у́бо ва́шими те́плими о нас моли́твами, ві́рно восхваля́єм вас зва́нії си́ми:","Ра́дуйтеся, о нас к Бо́гу непреста́нніі моли́твенниці;","ра́дуйтеся, любо́вію к нам горя́щії те́плії на́ші помо́щници.","Ра́дуйтеся, ско́рії засту́пници на́ші і наста́вници;","ра́дуйтеся, учи́теліє на́ші, жи́ти богоуго́дно нас научающії.","Ра́дуйтеся, любвеобильнії дру́зі на́ші, к не́мощем на́шим снизходящії;","ра́дуйтеся, на висоту́ ді́вственния чистоти́ і безстра́стія нас возводя́щії.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 11","ps":["Пі́ніє Бо́гу от всего́ се́рдця приноси́ла єси́, блаже́нная Ната́ліє, єгда́ ізба́ви тя от руки́ трибуна, желавшаго тя себі́ в жену́ поя́ти. Ти бо, я́ко ві́рная супру́га му́ченика Христо́ва Адрія́на, не восхоті́ла єси́ второ́є пося́гнути за му́жа і с моли́твою бежала єси́, сі́дши на кора́бль, во Византій, іді́же ті́ло свята́го му́жа твоєго́ положе́но бисть. Дости́гши у́бо гра́да сего́, с любо́вію взива́ла єси́ Го́споду Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник пресві́тлий яви́ся кора́бль, на не́мже морську́ю пучи́ну проплила єси́, імі́я с собо́ю многоці́нний би́сер, ру́ку свята́го му́жа твоєго́, єго́же моли́твами преследованія трибуна ізбегнувши, невреди́мо Византі́я дости́гла єси́ і, с ра́достною душе́ю лобиза́ющи ті́ло блаже́ннаго господи́на твоєго́, в душе́вном умиле́нії ду́шу твою́ в ру́ці Госпо́дні предала́ єси́. Велича́юще у́бо твоє́ ко Го́споду отше́ствіє вку́пі с Адрія́ном святи́м, воспіва́єм ви си́це:","Ра́дуйтеся, супру́зі блаже́ннії, на землі́ в любві́ пожи́вшії і по сме́рті не разлучи́вшіїся;","ра́дуйтеся, бли́жнії дру́зі Госпо́дні, у Престо́ла Єго́ пребива́ющії.","Ра́дуйтеся, лицезрі́нієм Єго́ всесві́тлим ви́ну наслажда́ющіїся;","ра́дуйтеся, блаже́нство ві́чноє всеці́ло вкуша́ющії.","Ра́дуйтеся, в селе́ніїх пра́ведних упокоє́ніє обрі́тшії;","ра́дуйтеся, на землі́ святи́я мо́щі своя́ на ісціле́ніє нам оста́вившії.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 12","ps":["Благода́ті іспо́лненнії сосу́ди показа́шася честни́я ва́ша мо́щі, Христо́м Бо́гом нам дарова́нния, к ни́мже усе́рдно притека́юще святі́ї му́ченици Христо́ві, гріхо́в разріше́ніє моли́твами ва́шими приє́млем, всім се́рдцем вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще честно́є ва́ше страда́ніє і блаже́нную кончи́ну, є́юже взидо́сте в Го́рняя, ко всім святи́м, от ві́ка Бо́гу угодившим, хва́лим вас, всесла́внії му́ченици Христо́ві, Адрія́не і Ната́ліє, і усе́рдно мо́лим непреста́нно помина́ти у Престо́ла Сла́ви нас, ублажа́ющих ви си́це:","Ра́дуйтеся, му́ченици прехва́льнії і до́блії во́їни Христо́ві;","ра́дуйтеся, непобіди́мії страстоте́рпці і побідоно́сці сла́внії.","Ра́дуйтеся, і́стинния ві́ри побо́рници ізря́днії;","ра́дуйтеся, доброді́телей світи́льници неугасимії.","Ра́дуйтеся, у́гліє, любо́вію Боже́ственною горя́щії;","ра́дуйтеся, вінцено́сці, небе́сними благами от Христа́ вінча́ннії.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 13","ps":["О святі́ї му́ченици Христо́ви, Адрія́не і Ната́ліє! Усли́шіте нас, усе́рдно вам моля́щихся і в храм ваш притека́ющих, і молі́те ми́лостиваго Влади́ку Го́спода на́шего Ісу́са Христа́ дарова́ти нам мир і здра́віє душ і тіле́с, і спасти́ душі́ на́ша, да ви́ну поє́м Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельською ко Го́споду горя́щи любо́вію, нерестанно возсилала єси́ усе́рдния моли́тви к Бо́гу Спаси́телю твоєму́, Ната́ліє всеблаже́нная, да просвіти́ть луче́м Своєя́ благода́ті помраче́нноє се́рдце супру́га твоєго́ і обрати́ть є к позна́нію Єго́, Творця́ і Влади́ки твоєго́, до́ндеже Цар царе́й усли́ша сле́зния проше́нія твоя́ і косну́ся се́рдця Адріянова, і а́біє уві́рова супру́г твой от всея́ душі́, і бо́дренним се́рдцем претерпі́ люті́йшия муки́, і са́мую смерть за Христа́ не убоя́ся прия́ти. Ті́мже благогові́йно удивля́ющеся ва́шей ко Христу́ любві́ і ре́вности по Бо́зі, ра́достно взива́єм вам:","Ра́дуйтеся, світи́льници всесві́тлії, горя́щії любо́вію Боже́ственною;","ра́дуйтеся, столпи́ непоколеби́мії проти́ву озлобле́ній ідолослужи́телей нечести́вих.","Ра́дуйтеся, Крест Христо́в с терпі́нієм і преданностію поне́сшії;","ра́дуйтеся, сим побі́ди святи́я зна́менієм побіди́вшії дия́вола і єго́ ко́зні посрами́вшії.","Ра́дуйтеся, нетлі́нія вінці́ восприя́вшії і сла́вою от Го́спода вінча́ннії;","ра́дуйтеся, я́ко ни́ні на Небесі́ предстоїте́ Престо́лу Вседержителеву і молі́теся за ни, грі́шния.","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Кондак 1","ps":["Ізбра́ннії служи́теліє Бо́жії і всехва́льнії му́ченици Христо́ві, всю ми́ра сего́ суєту́ презрі́вшії любве́ ра́ди ко Христу́, Си́ну Бо́жию, і живо́т свой положи́вшії, я́ко же́ртву непоро́чную і чи́стую, па́че жела́я прия́ти муче́нія і смерть, не́же отрещи́ся Бо́га і́стиннаго, восхваля́єм ви любо́вію, святі́ї Адрія́не і Ната́ліє! Ви же, во весе́лії предстоя́ще Престо́лу сла́ви Госпо́дні і ви́ну наслажда́ющеся Того́ лицезрі́нієм, молі́теся о нас, грі́шних, с ві́рою і благогові́нієм к вам притека́ющих, да благода́рственно вопіє́м вам:","Ра́дуйтеся, святі́ї Адрія́не і Ната́ліє, му́ченици Христо́ві всехва́льнії і страда́льці непобіди́мії!"]},{"h":"Молитва","ps":["О свяще́нная дво́їце, святі́ї му́ченици Христо́ві, Адрія́не і Ната́ліє, блаже́ннії супру́зі і до́блії страда́льці! Усли́шіте ни, моля́щіїся вам со слеза́ми, і низпослі́те на ни вся благопотре́бная душа́м і тілесе́м на́шим, і молі́те Христа́ Бо́га, да поми́луєть нас і сотвори́ть с на́ми по ми́лості Своє́й, да не поги́бнем во грісі́х на́ших! Єй, святі́ї му́ченици, приймі́те глас моле́нія на́шего і ізба́віте ни моли́твами ва́шими от гла́да, губи́тельства, тру́са, пото́па, огня́, гра́да, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні, от напра́сния сме́рти і от всіх бід, печа́лей і болі́зней, да ви́ну, ва́шими моли́твами і предста́тельством укрепляємії, просла́вим Го́спода Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Му́ченици Твої́, Го́споди, / во страда́ніїх свої́х вінці́ прия́ша нетлі́нния от Тебе́, Бо́га на́шего: / іму́ще бо крі́пость Твою́, / мучи́телей низложи́ша, / сокруши́ша і де́монов немощни́я де́рзости. / Тіх моли́твами // спаси́ ду́ші на́ша."]},{"h":"Інший тропар мученику Адріану, глас 3","ps":["Бога́тство неіждиву́щеє вміни́л єси́ / ві́ру спасе́нную, треблаже́нне, / оста́вль оте́чеськоє нече́стіє / і Влади́ки стопа́ми ше́ствуя, / Боже́ственними дарова́нії обогати́лся єси́, / Адрія́не сла́вне; / Христа́ Бо́га моли́ // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Му́ченик возсія́ Боже́ственная па́м'ять / і земни́я озари́ вся конці́ сві́тло, с весе́лієм зову́щих: // Ти єси́ му́чеников, Христе́, ра́дованіє."]},{"h":"Інший кондак, глас 4","ps":["Жени́ Богому́дрия Боже́ственная словеса́ в се́рдці положи́в, / Адрія́не, му́чениче Христо́в, к муче́нієм усе́рдно устреми́лся єси́, // с супру́гою віне́ць приє́м."]},{"h":"Величання","ps":["Велича́єм вас, святи́є му́ченици Адрія́не і Ната́ліє, і чтим честна́я страда́нія ва́ша, я́же за Христа́ претерпі́ли єсте́."]}],"notes":[]},{"u":"Акафіст преподобному Герману Алясканському, чудотворцю","e":"Akathist to our Venerable Father Herman of Alaska, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і пресла́вний уго́дниче Христо́в, богоно́сне о́тче наш Ге́рмане, Аля́ськи украше́ніє і Це́ркве Правосла́вния ра́дованіє, воспіва́єм ті похвали́ сія́. Ти же, я́ко Небе́сний наш покрови́тель і всемо́щний пред Бо́гом моли́твенник, не преста́й хода́тайствовати о нас, ча́діх твої́х, усе́рдно тебі́ вопію́щих:","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць предизбра́ тя, о́тче Ге́рмане, пропові́дником би́ти правосла́вния ві́ри в земля́х но́вих і посла́ тя, я́ко благові́стника, ко язи́чником, да возсія́єть їм світ І́стини. Благода́рнії же лю́діє воспіва́ють тебі́, я́ко Небе́сному покрови́телю, похвали́ сія́:","Ра́дуйся, пусти́нею Саро́вською ізді́тська взраще́нний;","ра́дуйся, Валаа́мськия оби́телі о́трасле пречестна́я.","Ра́дуйся, пусти́нноє уєдине́ніє возлюби́вий;","ра́дуйся, Бо́жиєю Ма́терію от сме́рти спасе́нний.","Ра́дуйся, апо́столов послі́дователю;","ра́дуйся, світ і́стинния ві́ри во Аме́рику принеси́й.","Ра́дуйся, Фаво́рським сві́том озаре́нний;","ра́дуйся, тьму ідолослуже́нія Христо́м просвіти́вий.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь пла́менную любо́в твою́, є́юже от ю́ности возгорі́ся, преподо́бне, во оби́тель Саро́вськую Єму́ єди́ному послужи́ти приведе́ тя, посліди́ же на о́стров Валаа́мський путь твой упра́ви, іді́же в со́нмі і́ноков ти воспіва́л єси́ неуста́нно: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум духо́вний тебі́ от ю́ности дарова́ся, свя́тче Бо́жий, да уразумі́єши красоту́ небе́сную і сла́дость єя́. Сего́ ра́ди от прему́драго ігу́мена Наза́рія, наста́вника преподо́бнаго Серафи́ма Саро́вськаго, поуча́лся єси́ прему́дрости Бо́жієй і путе́м Госпо́днім, ті́мже Свята́я Це́рков восхваля́єть тя:","Ра́дуйся, в де́бріх саро́вських ста́рцю пусти́ннику послужи́вий;","ра́дуйся, с преподо́бним Серафи́мом єди́наго наста́вника імі́вий.","Ра́дуйся, я́ко пчела́, от вели́каго Фео́дора духо́вний некта́р в Санакса́рі собра́вий;","ра́дуйся, во пресла́вную оби́тель Валаа́мськую на по́двиги прише́дий.","Ра́дуйся, я́ко тезоімени́тому тебі́ Ге́рману, первонача́льнику Валаа́мському, свя́тостію уподо́бился єси́;","ра́дуйся, я́ко по́двиги пустинножи́тельськия под'я́л єси́.","Ра́дуйся, за кро́тость і ти́хость бра́тією валаа́мською почита́ємий;","ра́дуйся, ни́ні все́ю Це́рковію прославля́ємий.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго повелі́ богому́дрому Петро́ва гра́да святи́телю Гавриї́лу посла́ти пропові́дники правосла́вния ві́ри в зе́млю Аля́скинскую і тебі́, преподо́бне Ге́рмане, сей жре́бій апо́стольський прия́ти. Ті́мже всі лю́діє, просвіще́ннії сві́том Христо́вим труди́ твої́ми і о́бразом житія́ твоєго́, воспі́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я не то́кмо тща́ніє о по́двизі і́ночестім, но і ре́вность апо́стольськую в пропові́данії, ти, преподо́бне Ге́рмане, лю́дем, во тьмі язи́чеськаго неві́дінія сідя́щим, Христа́ расп'я́таго і воскре́сшаго возвісти́л єси́. Помина́юще у́бо і́ночеськая бді́нія твоя́ і труди́ апо́стольськія, с любо́вію восхваля́єм тя:","Ра́дуйся, безро́потноє послуша́ніє ігу́мену яви́вий;","ра́дуйся, в путь да́льній про́повіді ра́ди єва́нгельськия отше́дий.","Ра́дуйся, любве́ ко оте́честву не угаси́вий;","ра́дуйся, но́воє твоє́ оте́чество пла́менні возлюби́вий.","Ра́дуйся, і́ночеськаго житія́ во Аме́риці первонача́льниче;","ра́дуйся, правосла́вния ві́ри ре́вностний пропові́дниче.","Ра́дуйся, о́бразе преподо́бних оби́телі Ла́дожськия;","ра́дуйся, Сі́верния Фиваї́ди о́трасле, во Аля́скі процвіти́й.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю злих напа́стей і скорбе́й претерпі́л єси́, преподо́бне, і по́двигом до́брим во страні́ но́вій подвиза́лся єси́, сего́ ра́ди і Христо́с тя просла́ви і да́ром прозрі́нія і чуде́с обогати́ і дарова́ тебі́ Ца́рство Небе́сноє, іді́же ти со А́нгели воспіва́єши Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще о чудесі́х твої́х, лю́дем явле́нних, єгда́ о́гненноє запале́ніє і наводне́ніє губи́тельноє ти останови́л єси́ моли́твою своє́ю, всі лю́діє умиля́хуся се́рдцем. Мо́лим тя і нам яви́ти си́лу твою́ і по́мощ, к тебі́ вопію́щим:","Ра́дуйся, богопропові́дниче, ре́вностію твоє́ю нас вдохновля́яй;","ра́дуйся, боголю́бче, сердця́ на́ша ра́достію ісполня́яй.","Ра́дуйся, за всіх унива́ющих те́плий моли́твенниче;","ра́дуйся, душ см'яте́нних пресла́достний умири́телю.","Ра́дуйся, я́ко смире́нієм твої́м подає́ши стра́ждущим ісціле́ніє;","ра́дуйся, я́ко кро́тостію твоє́ю окриля́єши ду́ші на́ша во є́же созерца́ти го́рняя.","Ра́дуйся, тве́рдий вразуми́телю всіх отше́дших от Правосла́вія;","ра́дуйся, любо́вію твоє́ю направля́яй нас на путь пра́вий.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Я́ко звізда́ во страні́ полу́нощній возсія́л єси́, преподо́бне, на о́строві Єло́вем, Но́вий Валаа́м нарече́ннім, да озари́ши сві́том любве́ твоєя́ і богомо́щною моли́твою твоє́ю всю зе́млю Америка́нськую, да со всіх конце́в єя́ лю́діє правосла́внії воспою́ть те́плі Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще смире́ніє твоє́, о́тче наш Ге́рмане, всі дивля́хуся зіло́, ка́ко ти, преподо́бному Анто́нію Пече́рському, первонача́льнику мона́шества на Русі́, подража́я, восхоті́л єси́ прости́м і́ноком би́ти і по вели́кому смире́нію твоєму́ от служе́нія свяще́нничеськаго отре́клся єси́. Сего́ ра́ди взива́єм ті такова́я:","Ра́дуйся, первонача́льниче мона́шества во Аме́риці;","ра́дуйся, смире́нієм Небе́снаго Оте́чества дости́гнувий.","Ра́дуйся, небе́сною сла́вою увінча́нний;","ра́дуйся, оби́тель на мі́сті по́двигов твої́х предреки́й.","Ра́дуйся, мо́щі твоя́ предрече́нной оби́телі дарова́вий;","ра́дуйся, істо́чник чуде́с от них ми́ру яви́вий.","Ра́дуйся, защи́тниче те́плий бра́тії, тобо́ю собира́ємия;","ра́дуйся, і́ноком вождь ве́лій на бра́ні неви́димой.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дуєть пусти́ня сі́верная по́двиги і чудеса́ твоя́, преподо́бне, і тя, я́ко но́вую вітв виногра́дника Це́ркве Ру́ськия, на землі́ Америка́нстій прозя́бшую, прославля́єть. Ти бо де́бри Аля́ськи і ліса́ єя́ моли́твою твоє́ю облагоуха́л єси́ і, подви́жником дре́внім подража́я, в безмо́лвії нощні́м взива́л єси́ к Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Просвіти́вий люде́й, во тьмі язи́честій пребива́ющих, і о́браз подви́жничеськаго житія́ сим показа́вий, моли́ся о всіх нас, богоно́сне о́тче наш Ге́рмане, да і ми, благодаря́ще Го́спода за ми́лость Єго́, нам явле́нную, непреста́нно воспіва́єм ті похва́льния сія́ глаго́ли:","Ра́дуйся, Пресвяти́я Тро́йці служи́телю ві́рний;","ра́дуйся, пусти́ні Єло́вия подви́жниче усе́рдний.","Ра́дуйся, щит ві́ри живи́я і разу́мния всім подава́яй;","ра́дуйся, тьму сві́том єва́нгельським просвіща́яй.","Ра́дуйся, я́ко суєту́ і уни́ніє богоми́слієм отгна́л єси́;","ра́дуйся, я́ко убо́га себі́ імену́я, смире́нію всіх поуча́л єси́.","Ра́дуйся, сердця́ на́ша ра́достію твоє́ю іспо́лнивий;","ра́дуйся, наде́ждою благо́ю нас укріпи́вий.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́й возсія́ти сві́ту богопозна́нія во страні́ язи́честій, благоволи́ Госпо́дь сі́яти сі́мена ві́ри правосла́вния і повелі́ тебі́, преподо́бне, да всіх научи́ши ві́рі і́стинній і защити́ши ю. Ти же, я́ко па́стир безстра́шний ма́лому ста́ду єванге́льськи взива́єши, да не убої́мся, я́ко обетова́но єсть нам Небе́сноє Ца́рствіє, ті́мже науче́ннії тобо́ю, ра́достні поє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно во ви́шніх моли́твенно пребива́л єси́, преподо́бне, но і в ни́жніх на землі́ су́щих не забива́л єси́, найпа́че же о сирота́х ве́ліє попече́ніє яви́л єси́, устроя́я прию́ть їм і учи́лище, іді́же за́повідем Госпо́днім поуча́л єси́ їх. Сих ра́ди трудо́в твої́х прийми́ от нас похвали́ сія́:","Ра́дуйся, ни́щих і сиро́т защи́тителю;","ра́дуйся, бла́гостний о них попечи́телю.","Ра́дуйся, я́ко стра́ху Бо́жию ча́да своя́ науча́л єси́;","ра́дуйся, я́ко живо́ю водо́ю Єва́нгелія всіх напоя́л єси́.","Ра́дуйся, моли́тви непреста́нния учи́телю;","ра́дуйся, хлі́бом небе́сним і земни́м сиропита́телю.","Ра́дуйся, плоть покоря́ти ду́ху поуча́вий;","ра́дуйся, Бо́га всім се́рдцем люби́ти наставля́вий.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до яви́ человіколю́бець Госпо́дь, дарова́ бо тебе́, преподо́бне, дар прозрі́нія і ісціле́нія я́ко істо́чник утіше́нія лю́дем Свої́м. Ти же ді́ли свої́ми і словеси́ приве́л єси́ мно́гія к любві́ Бо́жієй. Ті́мже сія́нієм по́двигов твої́х просвіще́ннії, лю́діє взива́ху ко Го́споду: Аллилу́я."]},{"h":"Ікос 8","ps":["Ізбра́н Бо́гом бил єси́, о́тче преподо́бне, ті́мже лю́діє новопросвіще́ннії сві́том Христо́ви ві́ри притека́ху к тебі́ в болі́зніх і печа́ліх. Ти же, я́ко оте́ць чадолюби́вий, предста́тельствовал єси́ за всіх в моли́твах, істоча́я ісціле́нія і утіша́я всіх, к тебі́ о по́мощі взива́ющих, ті́мже сла́вляху тя духо́вная ча́да твоя́:","Ра́дуйся, душ см'яте́нних умири́телю пресла́дкий;","ра́дуйся, врачу́ наш безме́здний і благода́тний.","Ра́дуйся, не́мощей на́ших ціли́телю милосе́рдний;","ра́дуйся, в біда́х і обстоя́ніїх помо́щниче ско́рий.","Ра́дуйся, лише́нним кро́ва те́плоє прибі́жище;","ра́дуйся, обурева́ємим, я́ко \"Скала́ Мона́шеськая\", ти́хоє приста́нище.","Ра́дуйся, гряду́щая я́ко настоя́щая прови́дівий;","ра́дуйся, прегріше́ній сокрове́нних обличи́телю прозорли́вий.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Всего́ себе́ Го́сподеві пре́дал єси́, блаже́нне, ті́мже со А́нгели в пусти́ні сла́достно бесі́довал єси́. І ни́ні с ли́ки А́нгельськими на Небесі́х непреста́нно взива́єши Творцю́ всіх і Созда́телю хвале́бноє: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть ісчи́слити чудеса́ твоя́, лю́дем явле́нная, я́ко і ду́си нечи́стії по словесі́ твоєму́ от люде́й стра́ждущих ісхожда́ху. Єгда́ же бисть наводне́ніє ве́ліє, ти моли́твою своє́ю пред іко́ною Бо́жия Ма́тере останови́л єси́ мо́ре, глаго́ля: \"Да́ліє сея́ черти́ не пре́йдеть вода́\". Ті́мже ті воспіва́єм си́це:","Ра́дуйся, стихі́ї водни́я усмири́телю ди́вний;","ра́дуйся, от запале́нія лесна́го ізба́вителю пресла́вний.","Ра́дуйся, святи́теля Інноке́нтія, в мо́рі взива́вшаго к тебі́, усли́шавий;","ра́дуйся, по мо́рю пла́вающим ко́рмчий наде́жний.","Ра́дуйся, я́ко гнів злих люде́й ти́хостію ісправля́л єси́;","ра́дуйся, я́ко ди́вноє благоуха́ніє с небесе́ к тебі́ прибега́ющим низпосила́л єси́.","Ра́дуйся, ве́лія зна́менія при жи́зні твоє́й показа́вий;","ра́дуйся, і по сме́рті твоє́й мно́гая чудеса́ яви́вий.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спаси́тельнаго сі́янія Госпо́дня, во вертогра́ді землі́ Америка́нськия насажде́ннаго, плод кра́сний ду́хом прови́дя, піснь благода́рственную Пресвяті́й Тро́йце посреді́ пусти́ні сі́верния возноси́л єси́, о́тче святи́й Ге́рмане, і со А́нгели небе́сними взива́л єси́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ всім, прибега́ющим к тебі́, о́тче, я́ко в житії́ твоє́м пресла́вная показа́л єси́ і при кончи́ні твоє́й ди́вноє чу́до яви́л. Лю́діє же, ви́дяще в час кончи́ни твоєя́ о́гненний столп до небесе́ і нетлі́ніє тілесе́ твоєго́, возопи́ша тебі́ такова́я:","Ра́дуйся, пра́ведною кончи́ною в свя́тости твоє́й нас уві́ривий;","ра́дуйся, я́ко восхожде́ніє твоє́ на небеса́ столпо́м о́гненним зна́менася.","Ра́дуйся, я́ко і гроб твой неду́жним ісціле́нія істоча́ше;","ра́дуйся, мо́щі твоя́ благоуха́нния в наслі́діє нам оста́вивий;","Ра́дуйся, я́ко у ра́ки твоєя́ хромі́ї воста́ша і глас твой із гро́ба сли́шаша.","Ра́дуйся, я́ко істо́чник води́ святи́я і ціле́бния нам дарова́л єси́.","Ра́дуйся, я́ко ста́рцю Гера́симу яви́лся єси́, на Єло́вий о́стров того́ призива́яй;","ра́дуйся, та́їнственно, я́ко живи́й, на о́строві сем пребива́яй.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє тебі́ прино́сим, о́тче преподо́бне, о пра́веднім житії́ твоє́м. Восхваля́єм і честну́ю кончи́ну твою́, я́ко предузна́л єси́ час преставле́нія своєго́, учени́к же твой Гера́сим обоня́л єсть благоуха́ніє ди́вноє в час той. Пресла́вно бисть і погребе́ніє твоє́, єгда́ іспо́лнися предрече́нноє тобо́ю. Ми же воспіва́єм чудоді́ющему Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельний світи́льник бил єси́ всему́ і́ночеському чи́ну да́льнія Аме́рики, преподо́бне о́тче наш Ге́рмане, науча́я по́двигу, защища́я от напа́стей, хода́тайствуя о них і глаго́ля: \"Не в морськи́х то́кмо волна́х обурева́ємся, но среди́ преле́стнаго і многом'яте́жнаго ми́ра стра́ждем і скита́ємся, оба́че к небе́сному на́шему Оте́честву гряде́м\". Сего́ ра́ди вопіє́м ті:","Ра́дуйся, ві́рний сподви́жниче Іоаса́фа, пе́рваго єпи́скопа Ру́ськия Аме́рики;","ра́дуйся, свиді́телю ре́вности Іувена́лієви да́же до сме́рти.","Ра́дуйся, алеу́та Петра́ пронареки́й новому́ченика;","ра́дуйся, предви́дівий святи́тельство Інноке́нтія в землі́ Алеу́тстей.","Ра́дуйся, ученику́ своєму́ Се́ргію о́браз і́ночеськаго житія́ показа́вий;","ра́дуйся, і́нока Гера́сима на Но́вий Валаа́м чуде́сно призва́вий.","Ра́дуйся, на Русі́, безбо́жієм плене́нней, Адрія́на пресви́тера от темни́ці огради́вий;","ра́дуйся, святи́теля Іоа́нна тебі́ просла́вити подви́гнувий.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ті іспо́лнена ві́дуще тя, преподо́бне о́тче, про́сим: моли́ся те́плі ко Го́споду, да огради́ть Це́рков Свою́ Святу́ю от ду́ха ми́ра сего́, вою́ющаго на сино́в єя́ неві́рієм і отвраща́ющаго от богодарова́нния жи́зні, даби́ восходи́ти нам от землі́ на не́бо і воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ прославле́ніє, преподо́бне, ублажа́єм тя, я́ко многомо́щна моли́твенника і предста́теля на́шего. Ти же, стяжа́вий Ду́ха Свята́го і Тім просвіти́вий лю́ди землі́ Америка́нськия, усли́ши нас, вопію́щих к тебі́ такова́я:","Ра́дуйся, моли́тву чи́стую і теплоту́ серде́чную стяжа́вий;","ра́дуйся, слез твої́х тече́ньми пусти́ні безпло́дноє возде́лавий.","Ра́дуйся, я́ко се́рдце твоє́ бисть благода́ті Бо́жия іспо́лнено.","Ра́дуйся, сві́том сокрове́нним осія́нний.","Ра́дуйся, умо́м очище́нним та́йни Боже́ственния созерца́вий;","ра́дуйся, тишини́ і ми́ра по́мислов дости́гнувий.","Ра́дуйся, сердца́ Ду́хом Святи́м просвіща́яй;","ра́дуйся, соверше́нство обріти́й і нас к сему́ призива́яй.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О пресла́вний уго́дниче Бо́жий, преподо́бне і богоно́сне о́тче наш Ге́рмане, прийми́ ма́лоє сіє́ моле́ніє на́ше, в похвалу́ тебі́ возноси́моє, і предстоя́ ни́ні престо́лу Го́спода Вседержи́теля, непреста́нно моли́ся о нас, ча́діх твої́х, да, пребива́юще в любві́ і єдиноми́слії, нави́кнем всегда́ твори́ти во́лю Бо́жию по сло́ву твоєму́: \"От сего́ дне, от сего́ часа́ да бу́дем люби́ти Бо́га преви́ше всего́ і твори́ти святу́ю во́лю Єго́\", і ку́пно с тобо́ю сподо́бимся воспіва́ти хвале́бную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць предизбра́ тя, о́тче Ге́рмане, пропові́дником би́ти правосла́вния ві́ри в земля́х но́вих і посла́ тя, я́ко благові́стника, ко язи́чником, да возсія́єть їм світ І́стини. Благода́рнії же лю́діє воспіва́ють тебі́, я́ко Небе́сному покрови́телю, похвали́ сія́:","Ра́дуйся, пусти́нею Саро́вською ізді́тська взраще́нний;","ра́дуйся, Валаа́мськия оби́телі о́трасле пречестна́я.","Ра́дуйся, пусти́нноє уєдине́ніє возлюби́вий;","ра́дуйся, Бо́жиєю Ма́терію от сме́рти спасе́нний.","Ра́дуйся, апо́столов послі́дователю;","ра́дуйся, світ і́стинния ві́ри во Аме́рику принеси́й.","Ра́дуйся, Фаво́рським сві́том озаре́нний;","ра́дуйся, тьму ідолослуже́нія Христо́м просвіти́вий.","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і пресла́вний уго́дниче Христо́в, богоно́сне о́тче наш Ге́рмане, Аля́ськи украше́ніє і Це́ркве Правосла́вния ра́дованіє, воспіва́єм ті похвали́ сія́. Ти же, я́ко Небе́сний наш покрови́тель і всемо́щний пред Бо́гом моли́твенник, не преста́й хода́тайствовати о нас, ча́діх твої́х, усе́рдно тебі́ вопію́щих:","Ра́дуйся, преподо́бне о́тче наш Ге́рмане, пресла́вний чудотво́рче."]},{"h":"Молитва","ps":["О преди́вний уго́дниче Бо́жий, преподо́бне о́тче наш Ге́рмане, ти по́двигом до́брим подвиза́лся єси́, хлад і іни́я тяготи́ в землі́ Алеу́тстей претерпі́л єси́. Ни́ні же іспо́лнися сло́во Госпо́днє на тебі́, в ма́лім ві́рним Єму́ би́вшем, ті́мже і поста́ви тя Госпо́дь я́ко Небе́снаго покрови́теля Це́ркве Америка́нськия. Ми же всі взива́єм ті те́плою моли́твою: моли́ся за Це́рков на́шу Святу́ю, да огради́ть ю Госпо́дь от те́мних сил вра́жиїх, нас да сохрани́ть в чистоті́ і благоче́стії, да утверди́ть во ві́рі кре́пкой і несумне́нной. І іспроси́ всім нам ду́ха ми́ра і любве́, ду́ха кро́тости і смире́нія, горди́ні отгна́ніє, от самопревозноше́нія огражде́ніє, боля́щим по́мощ і ісціле́ніє, скорб'я́щим утіше́ніє, а́лчущим пра́вди духо́вния пи́щу небе́сную. Да, улучи́вше жела́ємая, обря́щем пра́ведноє воздая́ніє в день Стра́шнаго Суда́ і со всі́ми святи́ми воспоє́м і просла́вим Живонача́льную Тро́йцю, Отця́ Непостижи́маго, І́стиннаго і Єдиноро́днаго Си́на і Свята́го Уті́шителя Ду́ха, во ві́ки. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Ло́зу Правосла́вія прине́сл єси́ в Аме́рику із Украї́ни благочести́вия / і, удобри́в ко́рень по́стничеськими труда́ми / і напоі́в оби́льні моли́твенними слеза́ми, / плоди́ прине́сл єси́ - виногра́д возлю́бленний, / Ге́рмане преблаже́нне о́тче наш. / Ті́мже і Бог тя просла́ви, я́ко апо́стола преподо́бнаго, / нетлі́нієм моще́й і благода́тію чуде́с, / от них же почерпа́юще благодія́нія, восхваля́єм тя: / сла́ва Да́вшему ті крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Дарова́вшему тя Аме́риці світи́ло Правосла́вія."]},{"h":"Інший тропар, глас 7","ps":["Звіздо́ пресві́тлая Це́ркве Христо́ви, / на сі́вері просія́вшая, / вся к Ца́рствію Небе́сному путеводя́щая, / учи́телю і апо́столе і́стинния ві́ри, / предста́телю і засту́пниче гони́мих, / украше́ніє ізя́щноє Святи́я Це́ркве во Аме́риці, / преподо́бне о́тче Ге́рмане Аля́скинский, / моли́ся ко Го́споду Спа́су на́шему, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Взбра́нному Воєво́ді сво́їнствовався, / в брань вступи́л єси́ на ду́ха зло́би в по́лі преподо́бія і апо́стольства. / І, пожа́в побі́ди обою́дния, / воздвиза́єши нас вопи́ти тебі́: // ра́дуйся, свя́те Ге́рмане, апо́столе преподо́бний."]},{"h":"Інший кондак, глас 8","ps":["Валаа́ма постри́женик, честни́й, / возлю́бленник Бо́жия Ма́тере би́вий, / ревни́тель по́двигов дре́вніх подви́жник но́вий, / моли́тву, я́ко копіє́ і щит, приє́мий, / стра́шен де́моном і тьмі язи́честій ста́вий, // Ге́рмане преподо́бне, моли́ Христа́ Бо́га спасти́ ду́ші на́ша."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Ге́рмане, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Макарію, Жовтоводському і Унженському чудотворцю","e":"Akathist to our Venerable Father Macarius of Zheltovody and Unzha, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от Воєво́ди сил небе́сних і Го́спода Ісу́са Христа́, преподо́бне о́тче наш Мака́ріє, я́ко імеяяй ве́ліє дерзнове́ніє к Бо́гу, моли́ся ви́ну о спасе́нії душ на́ших і ізбавле́нії нас от вся́ких бід і напа́стей, да зове́м ті:","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгела на землі́ яви́ тя Творе́ць небесе́ і землі́, вся бо земна́я вміни́л єси́ за уме́ти, да приобретеши єди́наго Христа́; ті́мже всі, зря́ще твоє́ христоподобноє на землі́ житіє́, вопіє́м ті:","Ра́дуйся, от утро́би ма́тернія предуготованний в чи́стоє і непоро́чноє жили́ще Пресвяти́я Тро́йці; Ра́дуйся, Бо́гом Отце́м предизбранний.","Ра́дуйся, Бо́гом Сино́м іскупленний;","Ра́дуйся, Бо́гом Ду́хом Святи́м освяще́нний.","Ра́дуйся, Го́спода па́че всего́ возлюби́вий;","Ра́дуйся, отця́ і ма́тер ра́ди Христа́ оста́вивий.","Ра́дуйся, зва́нію ду́ха благода́ті повинувшийся;","Ра́дуйся, отвергшийся себе́ ра́ди Христа́ Ісу́са.","Ра́дуйся, крест Христо́в на себі́ взе́мшій;","Ра́дуйся, вслід Христа́ последовавший.","Ра́дуйся, до конця́ жи́зні твоєя́ в терпі́нії і по́двизіх неосла́бно преби́вий;","Ра́дуйся, я́ко претерпіва́я му́жественно вре́менная і настоя́щая весели́лся єси́ бу́дущими і ві́чними.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Преподо́бне о́тче Мака́ріє, ти, сий єще́ младе́нець, єгда́ бива́ше звон церко́вний, пла́ча і ді́тськи крича, я́ко сми́сляй, із'являл єси́ жела́ніє, да в це́рков несе́н бу́деши. Соверша́ющуся же церковному в хра́мі Бо́жиєм пі́нію ра́довался і весели́лся єси́. Сего́ ра́ди благові́рнії роди́теліє твої́ ноша́ху тя на ка́ждоє церко́вноє пі́ніє і прославля́ху о тебі́ Го́спода Бо́га, вопію́ще: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум, неразумеваємий мудрствующим плотська́я, стяжа́л єси́, і все се́рдце твоє́ впери́л єси́ в небе́сная, сего́ ра́ди вопіє́м ті:","Ра́дуйся, я́ко по вся дні в це́рков Бо́жию ходи́л єси́;","Ра́дуйся, я́ко в сла́дость церко́внаго чте́нія і пі́нія послу́шал єси́.","Ра́дуйся, от ю́ности нави́кший богоуго́дному добронравію;","Ра́дуйся, возлюбивший красоту́ до́ма Бо́жия і мі́сто селе́нія сла́ви Госпо́дні.","Ра́дуйся, ізво́ливий примета́тися в до́му Бо́жії па́че, не́же жи́ти в селе́ніїх грі́шничих;","Ра́дуйся, во дні і в нощі́ непреста́нно моли́тви к Бо́гу возноси́вий.","Ра́дуйся, в чи́сту же́ртву Бо́гові не то́чію ті́ло, но і ду́шу всю принеси́й;","Ра́дуйся, всего́ себе́ на служе́ніє Бо́гу преда́вий.","Ра́дуйся, я́ко преви́ше све́рстник твої́х в разумі́нії сло́ва Бо́жия би́ша па́че ме́да і со́та усто́м твої́м;","Ра́дуйся, я́ко ма́слина в до́му Бо́жії насажде́нная.","Ра́дуйся, блаже́нне, я́ко уподо́бился єси́ дре́ву, насажденному при ісхо́дищих вод, принося́щему плоди́;","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Согревающу Ду́ху Свято́му се́рдце твоє́, проподобне о́тче, возжела́л єси́ вельми́ іночеського чи́на, возлюби́в Отця́ Небе́снаго па́че земни́х роди́телей твої́х, і ізше́л єси́ о́тай із до́му роди́телей в і́ночеськую оби́тель; обрі́т же на путі́ ни́ща, ху́ду оде́жду нося́ща, іспроси́л єси́ ту себі́, дав єму́ своє́ до́броє одія́ніє ра́ди Го́спода Бо́га Ісу́са Христа́, нас ра́ди обнища́вшаго, да ми нището́ю Єго́ обогаті́мся і вопіє́м Єму́ ви́ну: Аллилу́я."]},{"h":"Ікос 3","ps":["Прише́д во святу́ю оби́тель, преподо́бне о́тче наш Мака́ріє, моли́л єси́ свята́го Діони́сія Архімандрі́та, да принять бу́деши в чин і́ночеський, сказу́я себі́ безродна, сиротствующа, ни́ща, жела́юща рабо́тати Бо́гу. Архимандри́т же проразуме в тебі́ іму́ща би́ти сосу́д ізбра́нний Свято́му Ду́ху, прия́ і облече́ тя в а́нгельський о́браз. Ти же вся доброді́телі, подобающия і́ноком, ісполня́л і во всем угожда́л єси́ Бо́гу і наста́внику твоєму́, я́коже самому́ Христу́, та́кожде і бра́тіям, і показа́лся єси́ в новоначалії своє́м соверше́н би́ти і́нок і до́брий подви́жник. Ті́мже досто́йно вопіє́м ті:","Ра́дуйся, от рук свята́го Діони́сія і́ночество любе́зні прия́вий;","Ра́дуйся, сожи́тельство і собеседничество с преподо́бними ізбра́вий.","Ра́дуйся, і́ночеськаго житія́ ско́рби і тісноту́ возлюби́вий па́че утіше́ній і сла́достей ми́ра;","Ра́дуйся, поревнова́вий житію́ і по́двигом дре́вніх преподо́бних оте́ць.","Ра́дуйся, і́стиннаго послуша́нія настоя́телю і всей во Христі́ бра́тії о́браз показа́вий;","Ра́дуйся, вся́коє послуша́ніє со смире́нієм і кро́тостію соверши́вий.","Ра́дуйся, чистоти́ душе́вния і тіле́сния крі́пкий ревни́телю і храни́телю;","Ра́дуйся, бді́нієм, посто́м і коленопреклоненіями плоть свою́ умертви́вий.","Ра́дуйся, безмо́лвію і богоми́слію от ю́ности научи́вийся;","Ра́дуйся, ви́ну молча́ніє с незло́бієм храни́вий.","Ра́дуйся, сло́вом Бо́жиїм, а́ки мече́м, сопроти́вния си́ли побеждавий;","Ра́дуйся, по́стничеством і доброді́тельми превозше́дий би́вших с тобо́ю і́ноков.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́ря помисло́в смуща́ше роди́телі твоя́, о́тче наш Мака́ріє, єгда́ внеза́пу оста́вил єси́ о́тай дом їх; чрез три же лі́та обрі́тше тя во святі́й оби́телі, ра́довахуся і сла́в'яху Бо́га, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше, преподо́бне о́тче Мака́ріє, бли́жнії і да́льнії, я́же о по́стничеськом житії́ твоє́м, удивля́хуся і прославля́ху тя всю́ду, ти же, я́ко і́щущий сла́ви єди́наго Бо́га, бі́гал єси́ сла́ви, я́же от челові́к, скрива́яся в пусти́нях. Вся же на по́льзу стро́яй, Бог просла́ви тебе́, раба́ Своєго́, не то́чію в христия́ніх, но і в агаряніх. Ті́мже ми вопіє́м ті:","Ра́дуйся, гра́де верху́ стоя́й, не моги́й укри́тися;","Ра́дуйся, світи́льниче, вся озаря́ющий чудеси́ і по́двиги твої́ми.","Ра́дуйся, звіздо́, показу́ющая со́лнце пра́вди;","Ра́дуйся, заре́ Боже́ственнаго Сві́та.","Ра́дуйся, до́брими ді́ли твої́ми всіх, зря́щих тя, подвиза́яй к прославле́нію Отця́, І́же на небесі́х;","Ра́дуйся, я́ко потща́лся єси́ пре́жде сам сотвори́ти Во́лю Бо́жию і после научи́ти други́х.","Ра́дуйся, тве́рдий сто́лпе і́ночества;","Ра́дуйся, я́ко мудр вождь, приведи́й мно́гих к ві́чному спасе́нію.","Ра́дуйся, по́стничества, терпі́нія, жа́жди і а́лчби, і наготи́ о́бразе преди́вний;","Ра́дуйся, благо́є і́го і ле́гкоє бре́м'я Христо́во із мла́да возлюби́вий.","Ра́дуйся, на землі́ а́нгельськи пожи́вий;","Ра́дуйся, земни́й А́нгеле і небе́сний челові́че.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ всея́ страни́ яви́лся єси́, преподо́бне о́тче Мака́ріє, всім бив о́браз сло́вом, житіє́м, любо́вію, ду́хом, ві́рою, чистото́ю, воспіва́я Го́споду Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Госпо́дь Бог, очища́яй скорбми́ і напа́стьми ізбра́нния Своя́, я́ко зла́то і сребро́, попусти́ разори́тися созда́нній тобо́ю оби́телі, на ню́же внеза́пу напа́дше, ага́ряне всіх, в ней би́вших, ме́чним посіче́нієм, а́ки кла́си на ни́ві, пожа́ша, тебі́ же, преподо́бне о́тче наш, жива́ приведо́ша к воєво́ді своєму́. Сей же, узрі́в ангелоподо́бноє лице́ твоє́ і уві́дав, я́ко ти нікому́же зло соді́лал єси́, но всім єди́но добро́ твори́л єси́. Бо́гу жесто́коє се́рдце єго́ ум'ягчающу, даде́ свобо́ду тебі́ і єще́ же тебе́ ра́ди свободи́ про́чія плі́нния до чети́редесяти муже́й, ра́зві жен і діте́й. Ті́мже вопіє́м ті сицева́я:","Ра́дуйся, кро́тостію і бла́гостію своє́ю се́рдця неві́рних побіди́вий;","Ра́дуйся, зло́бу на жа́лость преложиви́й.","Ра́дуйся, благочести́вия лю́ди от плі́на ага́рянськаго свободи́вий;","Ра́дуйся, мно́гія от тя́жких напа́стей і скорбе́й ізба́вивий.","Ра́дуйся, я́ко честно́му погребе́нію пре́дал єси́ бра́тію оби́телі, срацинами ізбієнную, я́коже о́ния дре́вле преподо́бния отці́, і́же в Синає і Раїфе;","Ра́дуйся, я́ко єди́ною уме́рий ми́рові не о себі́, а о бли́жніх печалился єси́.","Ра́дуйся, я́ко лю́ди, с тобо́ю отпущенния із плі́на, тщаливе охранял єси́, да не па́ки в ага́рянськия руки́ впаду́ть;","Ра́дуйся, я́ко научи́л єси́ ізведенния тобо́ю лю́ди возложи́ти всю наде́жду на єди́наго Бо́га.","Ра́дуйся, я́ко бил єси́ їм в путі́ і вождь, і учи́тель, і уті́шитель;","Ра́дуйся, я́ко с моли́твою ізше́л єси́ в страну́ Га́личеськую.","Ра́дуйся, я́ко, ше́ствуя путе́м, положи́л єси́ основа́ніє Свіяжськия оби́телі;","Ра́дуйся, я́ко ре́вностію поревнова́л єси́ о спасе́нії душ, іску́пленних Ісу́сом Христо́м.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Все житіє́ твоє́, преподо́бне о́тче Мака́ріє, єсть немо́лчноє пропові́даніє ві́ри, наде́жди і любве́, я́же к Бо́гу і к бли́жнім, вліянния в ду́шу твою́ Святи́м Ду́хом, Єму́же вопіє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Но́ваго Мойсе́я показа́ тя, преподо́бне о́тче наш Мака́ріє, Госпо́дь Бог, єгда́ лю́ди, свободившіяся от плі́на, безбі́дно прове́л єси́ непроходимими лесами і блатами і ізнемога́ющия от гла́да ди́вно препита́л єси́. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, я́ко гладним лю́дем возбрани́л єси́ разори́ти пост, от Святи́я Це́ркве уста́вленний;","Ра́дуйся, я́ко уті́шил єси́ о́ния словеси́ богодухнове́нними, укріпля́я в терпі́нії.","Ра́дуйся, я́ко от ю́ности нави́кший поще́нію, небре́гл єси́ о себі́;","Ра́дуйся, я́ко о наро́ді гладнем істаєва́я печа́лію, твої́ми словеси́ і моли́твами укріпи́л єси́ єго́ в ізнеможе́нії от неяде́нія.","Ра́дуйся, я́ко гладнії лю́діє пи́щею духо́вною, а́ки хлі́бом, укріпля́ємі, мужествоваху;","Ра́дуйся, я́ко у Бо́га іспроси́л єси́ скота́, і́же бисть на дово́льную пи́щу алчущим.","Ра́дуйся, я́ко вся лю́ди приве́л єси́ безбі́дно в преді́ли Галическиє страни́, во град Унжу;","Ра́дуйся, я́ко благові́рнії лю́діє сріто́ша тебі́ че́стне, прия́та любе́зні, я́ко А́нгела Бо́жия.","Ра́дуйся, я́ко ві́домия тобо́ю лю́ди іспові́даша пред всі́ми на себі́ ми́лость Бо́жию;","Ра́дуйся, я́ко сли́шащії, ка́ко Госпо́дь Бог свободи́ благові́рния лю́ди от пліне́нія і гла́дния наси́ти, просла́виша Бо́га і тебі́, Єго́ уго́дника.","Ра́дуйся, я́ко Га́личеськую страну́ чудеси́ твої́ми озари́л єси́;","Ра́дуйся, я́ко світи́льник горя́й і світя́й яви́лся єси́.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Почита́нія і сла́ви, я́же от челові́к, во гра́ді не терп'я́, па́ки пустинннаго безмо́лвія возжела́л єси́, преподо́бне о́тче, і, обрі́т пусти́нноє мі́сто, возлюби́л є, водрузи́л єси́ крест, водвори́лся єси́ в созданной тобо́ю ке́ллії, да поє́ши ви́ну Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["В пусти́ні, в ню́же всели́лся єси́, преподо́бне о́тче Мака́ріє, по ма́лом вре́мені оби́тель і́ноком в пребива́нії устройся Бо́жиїм ізволе́нієм, і я́коже оби́кл єси́, в преподо́бії і в пра́вді дні і нощі́ рабо́тал єси́ Бо́гові. Ми же, прославля́юще о тебі́ Го́спода Бо́га, вопіє́м ті:","Ра́дуйся, єди́ноє на потре́бу всегда́ іска́вий;","Ра́дуйся, і́щущему до́брий би́сер уподо́бивийся і ра́ди сего́ вся земна́я оста́вивий.","Ра́дуйся, о́чі ума́ і се́рдця своєго́ на висоту́ небе́сную впери́вий;","Ра́дуйся, труди́ і по́двиги свої́ми А́нгелов і челові́ков удиви́вий.","Ра́дуйся, нището́ю тіле́сною і духо́вною Ца́рствіє Бо́жиє обріти́й;","Ра́дуйся, умиле́нія і сокруше́нія слеза́ми на небесі́х ві́чноє утіше́ніє прия́вий.","Ра́дуйся, я́ко ра́ди а́лчби і жа́жди на землі́ насища́єшися блаже́нством на небесі́;","Ра́дуйся, я́ко кро́тостію твоє́ю і незло́бієм твої́м наслі́довал єси́ ві́чную зе́млю.","Ра́дуйся, я́ко мир Бо́жий і сам тщился імі́ти со всі́ми, і водворял єси́ среди́ вражду́ющих, і сего́ ра́ди вчине́н єси́ в лик сино́в Бо́жиїх;","Ра́дуйся, і́мене ра́ди Христо́ва мно́гі ско́рбі, болі́зні, всено́щная бді́нія, колінопреклоне́нія, по́двиги і труди́ понеси́й.","Ра́дуйся і весели́ся, я́ко мзда твоя́ мно́га на небесі́х;","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Ди́вний во святи́х Госпо́дь Бог ди́вно прославля́ється в тебі́, преподо́бне о́тче Мака́ріє; облече́ бо тя си́лою сви́ше ціли́ти неду́ги і болі́зні душе́вния і тіле́сния і подава́ти поле́зная всім, с ві́рою і любо́вію вопію́щим к Нему́ о тебі́: Аллилу́я."]},{"h":"Ікос 8","ps":["Благода́ть Бо́жию, су́щую в тебі́, преподо́бне о́тче Мака́ріє, неоску́дно подава́я тре́бующим, отрокови́цю ні́кую бесну і слі́пу крестним зна́менієм с моли́твою ісціли́л єси́. Див'я́щеся си́лі Бо́жієй, обита́ющей в тебі́, взива́єм ті:","Ра́дуйся, благода́тний істо́чниче ісціле́ній;","Ра́дуйся, ту́не прия́вий благода́ть от Го́спода Бо́га, ту́не і подава́яй.","Ра́дуйся, імі́яй ве́ліє дерзнове́ніє ко Го́споду Бо́гу;","Ра́дуйся, я́ко нікто́же с ві́рою прося́й тощ отхо́дить от тебе́.","Ра́дуйся, я́ко всено́щними моли́твами всю бісо́вськую пре́лесть посрами́вий;","Ра́дуйся, сліпи́м зрі́ніє і всім боля́щим ісціле́ніє подава́яй.","Ра́дуйся, сокро́вище дарова́ній боже́ственних;","Ра́дуйся, я́ко хода́тайством твої́м даро́в Ду́ха Святого, укрепляющих в бра́ні проти́во враго́в спасе́нія, сподобля́ємся.","Ра́дуйся, я́ко крин неув'яда́ємий, в пусти́ні яви́лся єси́;","Ра́дуйся, цві́те, благоуха́нієм свої́м вся ісполня́яй.","Ра́дуйся, ріки́ води́ живи́я істоча́яй;","Ра́дуйся, ві́рних Го́спода рабо́в благу́ю часть ізбра́вий.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Єгда́ преста́вился єси́ от землі́ к небе́сним оби́телем, ли́ки А́нгелов і ізбра́нних Бо́жиїх ра́достно сріто́ша тебі́, с ни́ми же ти ви́ну вопіє́ши к Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Єгда́ прибли́жися вре́м'я преставле́нія твоєго́ по Бо́жию смотре́нію, ти, преподо́бне, прише́л єси́ в град Унжеск, іді́же іспо́лнь дній і богоугожде́нія, святу́ю ду́шу твою́ пре́дал єси́ в ру́ці Бо́жії. А́біє іспо́лнися чу́днаго благоуха́нія весь град, і окре́стнії лю́діє обоняху благоуха́ніє ди́вноє, а́ки от фимія́ма і сми́рни ісходя́щеє. Всі удивля́ющеся, я́ко а́ще Госпо́дь Бог почти́л єсть преставле́ніє тебі́, уго́дника Своєго́, прославля́ху Го́спода Бо́га. Стече́ся к нетлі́нному і благоухающему ті́лу твоєму́ мно́жество наро́да, і со свіщми́ і со псалми́ несо́ша є в пусти́нную оби́тель, іді́же погребо́ша че́стно і вопія́ху ті:","Ра́дуйся, Го́споду до конця́ послужи́вий;","Ра́дуйся, кончи́ну свою́ предуві́дівий.","Ра́дуйся, к со́нму ізбра́нних Бо́жиїх сопричтенний;","Ра́дуйся, воздая́ніє от Бо́га по пра́вим ді́лом твої́м восприя́вий.","Ра́дуйся, с проро́ки водворивийся;","Ра́дуйся, со апо́столи всели́вийся.","Ра́дуйся, вінце́м нетлі́нним увінча́нний;","Ра́дуйся, я́ко Го́спода Бо́га со всі́ми святи́ми о нас грі́шних умоля́єши.","Ра́дуйся, на бра́ці Небе́снаго Жениха́ би́ти досто́їн я́вльшийся;","Ра́дуйся, тлі́нную жизнь на нетлі́нную преміни́вий.","Ра́дуйся, уго́дниче Христо́в, блаже́нству тезоимени́тий;","Ра́дуйся, в ра́дость Го́спода твоєго́ вше́дий.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й вся, Госпо́дь Бог ісполня́єть Свої́ми вели́кими дарованіями ізбра́нних рабо́в Свої́х, да їх чудеса́ми, моли́твами і равноа́нгельним житіє́м ми возбужда́ємся от жи́зні гріхо́вния к жи́зні святі́й, воспіва́я ви́ну Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і помо́щник яви́лся єси́, блаже́нно Мака́ріє, всім прибегающим к тебі́; ті́мже і нам, призива́ющим тя, бу́ди засту́пник, избавля́я ни от іскуше́ній, скорбе́й і напа́стей, да восхваля́єм тя, зову́ще:","Ра́дуйся, я́ко твої́ми моли́твами от гріхо́в, паде́ній, страсте́й і злих оби́чаєв воздвигаєши нас грі́шних;","Ра́дуйся, я́ко при́сно возбужда́єши нас к подража́нію твоєму́ свято́му житію́.","Ра́дуйся, і́стиннаго покая́нія наста́вниче;","Ра́дуйся, обличи́телю немо́лчний нерадящим о ві́чном спасе́нії.","Ра́дуйся, о всіх ві́рних, притека́ющих к тебі́, предста́телю;","Ра́дуйся, на неви́димая і ви́димая враги́ побо́рниче.","Ра́дуйся, в біда́х, напа́стіх і ну́ждах душе́вних і тіле́сних утіше́ніє і по́мощ подава́яй;","Ра́дуйся, от смертоно́сния я́зви ізбавля́яй.","Ра́дуйся, наше́ствіє сопроти́вних отгоня́яй;","Ра́дуйся, пла́мень, губ'ящий град, погаша́яй.","Ра́дуйся, ум і смисл враго́в помрача́яй;","Ра́дуйся, люб'ящия Оте́чество і благочести́вия цари́ на побі́ду умудря́яй.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє Го́споду Бо́гу, в Тро́йці покланя́ємому і сла́вимому, прино́сим, я́ко дарова́л нам в тебі́, преподо́бне о́тче Мака́ріє, те́плаго моли́твенника, ско́раго помо́щника і ди́внаго чудотво́рця, воспіва́юще Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоприємна світи́льника яви́ тя Госпо́дь Бог, преподо́бне Мака́ріє, єгда́ обрі́тени би́ша честни́я мо́щі твоя́, благослове́нния нетлі́нієм, благоуха́ніє іспущающия і чудеса́ми окре́стния страни́ озаря́ющия; ті́мже всі ра́дующеся, вопіє́м ті:","Ра́дуйся, я́ко і по сме́рті жив пребивавши, явля́я в себі́ си́ли боже́ственния;","Ра́дуйся, чудеси́ твої́ми зе́млю наполня́я.","Ра́дуйся, я́ко благочести́вую жену́ от плі́на ага́рянськаго свободи́л єси́;","Ра́дуйся, я́ко німо́му уста́ отве́рзл єси́.","Ра́дуйся, я́ко пока́явшемуся во грехах зрі́ніє возврати́л єси́;","Ра́дуйся, я́ко разсла́бленному здра́віє дарова́л єси́.","Ра́дуйся, я́ко мно́гі сліпи́я і немощству́ющия ісціли́л єси́;","Ра́дуйся, я́ко ві́рния лю́ди от нападе́нія ля́хов ізба́вил єси́.","Ра́дуйся, я́ко моли́твами твої́ми вразі́, напа́дшії с ору́жієм на оби́тель твою́, сліпото́ю пораже́ні і стра́хом см'яте́ни би́ша, і мно́зі в ріці́ потопоша;","Ра́дуйся, ограждаяй ви́ну оби́тель твою́ от бід і зол.","Ра́дуйся, отча́янних наде́ждо і по́моще;","Ра́дуйся, от Бо́га проси́мая тобо́ю приє́мляй.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 12","ps":["По пліне́нії і опустошенії Желтоводськия оби́телі от ага́рян лі́том мно́гим прешедшим трикра́ти яви́лся єси́ ні́коєму і́ноку богоуго́дну Авра́мію, повеліва́я, да і́деть в Желтоводськую пусти́ню і всели́ться на мі́сті, іді́же бі оби́тель. І́нок Авра́мій водвори́ся ту і ходи́ в оби́тель Унжеськую, іді́же іко́ну твою́ списа́в, принесе́ ю на благослове́ніє, і нача́ша бива́ти чудеса́ от сея́ честни́я іко́ни. Ті́мже ми вопіє́м просла́вльшему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще зна́менія і чудеса́, я́же твори́ши живу́щею в тебі́ благода́тію Бо́жиєю, блаже́нне Мака́ріє, восхваля́єм тя си́це:","Ра́дуйся, я́ко і по преставле́нії твоє́м возста́вил єси́ запусті́вшую оби́тель твою́;","Ра́дуйся, я́ко па́ки собра́л єси́ і́щущих спасе́нія і обнови́л єси́ боже́ственную хвалу́.","Ра́дуйся, я́ко свято́є мі́сто, тобо́ю любе́зні ізбра́нноє, не оставля́ти запові́дал єси́ Авра́мію;","Ра́дуйся, я́ко тобо́ю мона́хов мно́жество в по́двизіх і ско́рбіх свої́х укріпле́ніє приє́млють.","Ра́дуйся, я́ко оби́телі, тобо́ю созда́нния, моли́твами твої́ми, а́ки покро́вом, покрива́ються;","Ра́дуйся, страні́ сей і Оте́честву на́шему украше́ніє.","Ра́дуйся, наде́ждо і прибі́жище в мо́рі житія́ сего́ пла́вающих;","Ра́дуйся, тве́рдоє огражде́ніє усе́рдно рабо́тающих Го́споду Бо́гу.","Ра́дуйся, царе́м благочести́вим по́моще;","Ра́дуйся, патріа́рхов і святи́телей утіше́ніє.","Ра́дуйся, всіх, усе́рдно притека́ющих к тебі́, от іскуше́ній і бід ско́роє ізбавле́ніє;","Ра́дуйся, я́ко хода́тайством твої́м ві́рнії жизнь ві́чную получа́ють.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О преподо́бне і богоно́сне о́тче наш Мака́ріє! Прийми́ сіє́ ма́лоє моли́твенноє приноше́ніє на́ше і со Пресвято́ю Влади́чицею Богоро́дицею і всі́ми святи́ми принеси́ моли́тву ко Го́споду Бо́гу, да ізба́вить нас от враг ви́димих і неви́димих, от вся́ких скорбе́й і бід, от напра́сния сме́рти і от бу́дущих мук, і сподо́бит Своєго́ Небе́снаго Ца́рствія, іді́же всі, при́сно веселя́щеся і торжеству́юще, немо́лчно вопію́ть к Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела на землі́ яви́ тя Творе́ць небесе́ і землі́, вся бо земна́я вміни́л єси́ за уме́ти, да приобретеши єди́наго Христа́; ті́мже всі, зря́ще твоє́ христоподобноє на землі́ житіє́, вопіє́м ті:","Ра́дуйся, от утро́би ма́тернія предуготованний в чи́стоє і непоро́чноє жили́ще Пресвяти́я Тро́йці;","Ра́дуйся, Бо́гом Отце́м предизбранний.","Ра́дуйся, Бо́гом Сино́м іскупленний;","Ра́дуйся, Бо́гом Ду́хом Святи́м освяще́нний.","Ра́дуйся, Го́спода па́че всего́ возлюби́вий;","Ра́дуйся, отця́ і ма́тер ра́ди Христа́ оста́вивий.","Ра́дуйся, зва́нію ду́ха благода́ті повинувшийся;","Ра́дуйся, отвергшийся себе́ ра́ди Христа́ Ісу́са.","Ра́дуйся, крест Христо́в на себі́ взе́мшій;","Ра́дуйся, вслід Христа́ последовавший.","Ра́дуйся, до конця́ жи́зні твоєя́ в терпі́нії і по́двизіх неосла́бно преби́вий;","Ра́дуйся, я́ко претерпіва́я му́жественно вре́менная і настоя́щая весели́лся єси́ бу́дущими і ві́чними.","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний от Воєво́ди сил небе́сних і Го́спода Ісу́са Христа́, преподо́бне о́тче наш Мака́ріє, я́ко імеяяй ве́ліє дерзнове́ніє к Бо́гу, моли́ся ви́ну о спасе́нії душ на́ших і ізбавле́нії нас от вся́ких бід і напа́стей, да зове́м ті:","Ра́дуйся, Мака́ріє, преди́вний чудотво́рче."]},{"h":"Молитва","ps":["О преподо́бне і Богоно́сне о́тче наш Мака́ріє! Ві́руєм, я́ко ти, предстоя́ престо́лу Пресвяти́я Тро́йці, ве́ліє і́маши дерзнове́ніє в моли́твах ко Всемилостивому́ Го́споду Бо́гу, і́же всегда́ послу́шаєть тебі́, ві́рнаго раба́ і уго́дника Своєго́. Сего́ ра́ди со умиле́нієм смире́нно припа́даєм к тебі́, свя́тче Бо́жий, не премолчи́ о нас моли́тися ко Го́споду Бо́гу, в Тро́йці покланя́ємому і сла́вимому, да ми́лостиво призрі́в на ни, не попу́стить нам поги́бнути во грісі́х на́ших, но да возста́вить па́дших, да пода́сть ісправле́ніє зло́му і окая́нному на́шему житію́, от гряду́щих гріхопаде́ній восхища́я, і да прости́ть нам вся, єли́ка са́мі собо́ю іли́ чрез други́х кого́, согріши́хом ми́слію, сло́вом і ді́лом, от рожде́нія до сего́ часа́. Ти, подви́жниче доброді́телей, о́тче наш Мака́ріє, ві́си не́мощ єстества́ на́шего і тя́жесть і скорб, време́н настоя́щих, моли́ у́бо ви́ну Го́спода Бо́га, да ніколи́же нас оставля́єть Єго́ неізрече́нноє милосе́рдіє, но да храни́ть нас от мирськи́х іскуше́ній, от дия́вольських сіте́й і от плотськи́х по́хотей, да при́ймем от Го́спода Бо́га тобо́ю і вся потре́бная к жи́зні вре́менній, освобожде́ніє от бід і напа́стей, а среди́ їх неосла́бноє терпі́ніє до конця́. Іспроси́ нам у Го́спода Бо́га в ми́рі і покая́нії сконча́ти живо́т наш і невозбра́нно прейти́ от землі́ на Не́бо, мита́рств же і бісо́во возду́шних і ві́чния муки́ ізба́витися і сподо́битися Ца́рства Небе́снаго, с тобо́ю і со всі́ми святи́ми, угоди́вшими Го́споду Бо́гу і Спаси́телю на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і с Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в.Амі́нь."]},{"h":"Тропар, глас 5","ps":["Днесь град твой Га́лич тобо́ю хва́литься, / в конці́х бо єго́ пресві́тло, / я́ко ве́ліє со́лнце, возсія́л єси́ / і чудеси́ твої́ми, преподо́бне Мака́ріє, вся озари́л єси́. / І ни́ні моли́ся Го́сподеві / ізба́витися душа́м на́шим от пре́лести вра́жия // і спасти́ся гра́ду твоєму́ от пога́нськаго на́йтія."]},{"h":"Інший тропар, глас 4","ps":["Богому́дрий Желтово́дськия оби́телі первозда́телю, / Бо́гом поста́вленний мона́шеськаго житія́ сто́лпе, / благопи́санний досточу́днаго по́стничества о́бразе, / Богозда́нний Ду́ха Свята́го сосу́де, / златоза́рноє Ру́ськия землі́ світи́ло всесві́тлоє, / мо́лим тя, о́тче Мака́ріє, // світоза́рною моли́тв твої́х луче́ю разріша́й мра́чних страсте́й на́ших о́блак."]},{"h":"Кондак, глас 2","ps":["Втори́й Мойсе́й яви́лся єси́, преподо́бне: / он бо жезло́м мо́ре разділи́, / ти же стра́сті, я́ко Амали́ка, побіди́л єси́ / і непрохо́дную пусти́ню нем'яте́жним умо́м проше́л єси́, / в не́йже моли́твами твої́ми ве́ліє чу́до сотвори́л єси́: / гла́дния лю́ди до ізоби́лія прекорми́л єси́. / І ни́ні моли́ся Го́сподеві / пода́ти всім печа́льним утіше́ніє, / Мака́ріє, о́тче приснопа́м'ятне, / і́же Га́личестій страні́ і всей Украї́нській землі́ // похвала́ і утвержде́ніє."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче наш Мака́ріє, і чтим святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святим Царственним страстотерпцям","e":"Akathist to the Holy Royal Passion-Bearers","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії ца́рственнії страстоте́рпці, єди́на дома́шняя це́рков Христо́ва, Нико́лає, Алекса́ндро, Алексі́є, О́льго, Татіа́но, Марі́є і Анастасі́є, ви, сою́зом любве́ связу́ємі, я́ко а́гнці, Христу́ Бо́гу ві́рою послі́довали єсте́ і, в страда́ніїх смерть претерпі́вше, Ца́рствія Небе́снаго наслі́дници яви́лися єсте́. Ни́ні же, дерзнове́ніє ко Го́споду іму́ще, молі́теся о земні́м оте́честві ва́шем, да прославля́єм вас си́це:","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Ікос 1","ps":["А́нгельськими си́лами укріпля́ємі во і́стиннім путі́, седьмочи́сленнії страстоте́рпці, о житії́ пра́веднім і богоуго́днім ревнова́ли єсте́, да я́віте наро́ду ру́ському о́браз благочести́вих царе́й. Сего́ ра́ди прославля́єм вас си́це:","Ра́дуйтеся, страх Бо́жий в се́рдці, я́ко основа́ніє, положи́вшії;","ра́дуйтеся, прему́дрость Бо́жию і́стинне возлюби́вшії.","Ра́дуйтеся, все упова́ніє на Бо́га возложи́вшії;","ра́дуйтеся, оте́честву ва́шему ві́рно послужи́вшії.","Ра́дуйтеся, христия́нськаго благоче́стія тве́рдоє пра́вило;","ра́дуйтеся, ца́рственнаго ро́да Украї́нськаго похвало́.","Ра́дуйтеся, Правосла́вния ві́ри крі́пкоє іспові́даніє;","ра́дуйтеся, стра́ждущаго наро́да на́шего утіше́ніє.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь покая́ніє наро́да на́шего, єгда́ сму́тная времена́ наста́ша, умилосе́рдися і яви́ ми́лость Свою́ во ізбра́нії Михаї́ла царя́, єго́же іко́ною Пречи́стия Богоро́диці, Фео́доровськая імену́ємою, чрез роди́тельницю благослови́, да бу́деть іко́на сія́ покро́в і защище́ніє єму́ і всему́ новоізбра́нному ца́рському ро́ду і во утвержде́ніє держа́ви Украї́нськия. Сего́ ра́ди благода́рні вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ша лю́діє Украї́нськії, я́ко ізбра́нієм на ца́рство но́ваго ро́да благочести́ваго, утиши́ Госпо́дь нестроє́нія і сму́ти в Землі́ на́шей, принесо́ша обі́т ві́рнаго служе́нія ро́ду сему́. Ми же, любві́ і ре́вности тіх подража́юще, к вам, ца́рственнії страстоте́рпці, я́ко наслі́дником сего́ ізбра́нія со умиле́нієм вопіє́м:","Ра́дуйтеся, віне́ць і похвало́ ро́да ца́рськаго і свяще́ннаго;","ра́дуйтеся, ко́рене благочести́ваго пресла́вния о́траслі.","Ра́дуйтеся, Патріа́рха Украї́нськаго Філаре́та свято́є прозябе́ніє;","ра́дуйтеся, попече́нію єго́ о Це́ркві і оте́честві подража́вшії.","Ра́дуйтеся, вели́кия ста́риці і́нокини Ма́рфи благослове́нноє наслі́діє;","ра́дуйтеся, поко́рность во́лі Бо́жієй от нея́ восприї́мшії.","Ра́дуйтеся, пред іко́ною Бо́жия Ма́тере Фео́доровськия моли́тви при́сно возноси́вшії;","ра́дуйтеся, все упова́ніє на по́мощ Богоро́диці с ві́рою возлага́вшії.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 3","ps":["Си́ла Бо́жия і промишле́ніє Всеви́шняго яви́ся в рожде́нії твоє́м, ца́рственний страстоте́рпче Нико́лає, вели́каго бо святи́теля і́м'я восприє́м, засту́пник Украї́нськия Землі́ показа́лся єси́. Мно́гія же ско́рби і болі́зні, подо́бні І́ову пра́ведному, в житії́ претерпі́в, ни́ні с ли́ки страстоте́рпцев наслажда́єшися ра́йськаго блаже́нства, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я сугу́бия засту́пники і покрови́телі в рожде́нії твоє́м І́ова многострада́льнаго і Никола́я чудотво́рця, держа́вний страстоте́рпче, доброді́телем тіх послі́довал єси́. Ми же, див'я́щеся промишле́нію Творця́, во святи́х сих о́браз благоче́стія указа́вшаго ті, благогові́йні воспіва́єм си́це:","Ра́дуйся, в моли́твах святи́теля Мир Ликі́йських при́сно призива́яй;","ра́дуйся, по́мощію того́ Украї́нськую Держа́ву пра́ведно окормля́яй.","Ра́дуйся, о́бразом кро́тости тому́ уподо́бивийся;","ра́дуйся, милосе́рдіє мно́гоє, я́коже о́ний, яви́вий.","Ра́дуйся, терпі́ніє І́овле в се́рдці твоє́м імі́вий.","Ра́дуйся, ві́рность Бо́гу в житії́ твоє́м до конця́ сохрани́вий.","Ра́дуйся, в тя́жких біда́х, я́коже о́ний, благодаре́ніє Бо́гу приноси́вий;","ра́дуйся, вся находя́щая на тя со смире́нієм приє́мий.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 4","ps":["Бу́рю смуще́нія, воздвиза́ємую от челові́к безбо́жних в страні́ на́шей, ви́дя, страстоте́рпче Нико́лає, не смути́лся єси́ в се́рдці твоє́м і, все упова́ніє на Бо́га возложи́в, не возропта́л єси́, єгда́ отверго́ша тя лю́ди твоя́; оба́че с ві́рою воспі́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша о м'яте́жіх, болі́зніх і междоусо́бних бра́ніх, наше́дших на зе́млю Ру́ськую, во у́зах сий, страстоте́рпче царю́ Нико́лає, моле́ніє о лю́діх єя́ непреста́нні приноси́л єси́, милосе́рдіє Бо́жиє к ним призива́я. Сего́ ра́ди ми воспіва́єм тебі́ та́ко:","Ра́дуйся, от ю́ности оте́чество і наро́д твой возлюби́вий;","ра́дуйся, я́ко і во отверже́нії любо́в сію́ сохрани́вий.","Ра́дуйся, пома́заніє на ца́рство с благогові́нієм приє́мий;","ра́дуйся, о́браз благочести́ваго царя́ ми́ру яви́вий.","Ра́дуйся, ца́рський віне́ць со смире́нієм на ся возложи́вий;","ра́дуйся, вінця́ страда́ній от Го́спода удосто́єнний.","Ра́дуйся, ца́рськоє служе́ніє, я́ко послуша́ніє Бо́гу, разуме́вий;","ра́дуйся, поноше́нія, я́ко крест, взе́мий і с терпі́нієм понеси́й.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 5","ps":["Богосві́тлий світи́льник во мра́ці скорбе́й благові́рній супру́жнице твоє́й яви́лся єси́, ца́рственний страстоте́рпче Нико́лає, указу́я і возглавля́я путь єя́, я́коже повелі́ Госпо́дь. Ми же, прославля́юще ваш благослове́нний сою́з во Христі́, хвалу́ Бо́гу воздає́м, пою́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя ца́рственний страстоте́рпець ю́ницю Алекса́ндру, я́ко голуби́цю чи́сту, ізбра́ ю себі́ в благові́рную супру́жницю, Правосла́вную цари́цю і ма́тер наро́да Украї́нськаго. Ми же, ві́дуще усе́рдноє служе́ніє єя́, воспіва́єм си́це:","Ра́дуйся, імени́таго ро́да благочести́воє прозябе́ніє;","ра́дуйся, от лю́терськия ві́ри к Правосла́вію о́бразе спаси́тельнаго прехожде́нія.","Ра́дуйся, всім се́рдцем моли́тву возлюби́вшая;","ра́дуйся, о слу́жбі Бо́жієй серде́чно ревнова́вшая.","Ра́дуйся, сло́вом Бо́жиїм і писа́нієм святи́х оте́ць себі́ назда́вшая;","ра́дуйся, уста́ви церко́вния благогові́йно соблюда́вшая.","Ра́дуйся, ру́ськоє благоче́стіє досто́йні восприє́мшая;","ра́дуйся, і́стинния жи́зні во Христі́ приобщи́вшаяся.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 6","ps":["Пропові́дуєть житіє́ ва́ше бра́ка свята́го чистоту́, благові́рнії Нико́лає і Алекса́ндро. Ви бо, благода́ть сего́ вели́каго та́їнства досто́йно восприє́мше, да́же до му́ченичеськия кончи́ни ві́рность Христу́ і любо́в друг ко дру́гу сохрани́ли єсте́, при́сно воспіва́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в страні́ Украї́нській, я́ко прекра́сная світи́ла, благові́рная ца́рственная чета́ Никола́й і Алекса́ндра, супру́зі, сою́зом любве́ Христо́ви связу́ємії. Ми же, прославля́юще о́браз їх цілому́дреннаго і добронра́внаго житія́ в ми́рі сем, со благогові́нієм воспіва́єм си́це:","Ра́дуйтеся, всім се́рдцем Бо́га взиска́вшії;","ра́дуйтеся, в путеіх Госпо́дніх непоро́чно ходи́вшії.","Ра́дуйтеся, дво́їце честна́я, сви́ше ізбра́нная;","ра́дуйтеся, дво́їце свята́я, сла́вою і че́стію от Бо́га вінча́нная.","Ра́дуйтеся, целому́дріє супру́жеськоє многоча́дієм просла́вившії;","ра́дуйтеся, ча́да ва́ша, я́ко новосажде́нія ма́сличная, о́крест трапе́зи Небе́сния собра́вшії.","Ра́дуйтеся, супру́ги во благоче́стії і любві́ жи́ти науча́ющії;","ра́дуйтеся, мир Христо́в о́ним ми́лостивно низпосила́ющії.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 7","ps":["Хотя́ще ваш дом благоче́стно устро́їти, любо́в, я́ко основа́ніє, положи́ли єсте́ і брак че́стен до́брі соблюли́ єсте́, благові́рнії супру́зі Нико́лає і Алекса́ндро. Ті́мже, і дще́рі ва́ша, я́ко му́дрия єва́нгельськия ді́ви, воспита́вше, в неві́сти Христу́ угото́вали єсте́. С ни́миже ни́ні вку́пі воспіва́єте Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую ми́лость дарова́ Госпо́дь наро́ду ру́ському, цілому́дренния дще́ри ца́рственния чети́ О́льгу, Татія́ну, Марі́ю і Анастасі́ю. Ти́я бо, жена́м мироно́сицям подража́ющия, єле́єм милосе́рдія боля́щим і стра́ждущим послужи́ша і, смерть за Христа́ приє́мша, ни́ні Престо́лу Бо́жию предстоя́ть. Сего́ ра́ди прославля́єм їх си́це:","Ра́дуйтеся, дще́ри царе́ви, обітова́ній Бо́жиїх сподо́бльшияся;","ра́дуйтеся, за́повідь Бо́жию о почита́нії роди́телей соблю́дшия.","Ра́дуйтеся, досто́їнство ца́рственноє свя́то сохра́ньшия;","ра́дуйтеся, стихі́ями ми́ра сего́ не порабоще́нния.","Ра́дуйтеся, лю́дем, су́щим в біда́х і ско́рбіх, я́ко Христу́, послужи́вшия;","ра́дуйтеся, за враго́в свої́х усе́рдно моли́вшияся.","Ра́дуйтеся, а́гници непоро́чния, в же́ртву Бо́гу себі́ прине́сшия;","ра́дуйтеся, неві́сти Христо́ви, в черто́зіх Жениха́ Небе́снаго пребива́ющия.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 8","ps":["Стра́нно і чу́дно бисть рожде́ніє твоє́, святи́й царе́вичу Алексі́є. Плод бо благосла́вен моли́тв Саро́вськаго чудотво́рця і ча́ємий наслі́дник ца́рственних роди́телей бив, сла́ва, наде́жда і упова́ніє яви́лся єси́ всім конце́м Землі́ на́шея. Сего́ ра́ди лю́діє Украї́нськії с ра́достію благода́рственно воспі́ша Бо́гу:Аллилу́я."]},{"h":"Ікос 8","ps":["К ви́шнім душе́ю чи́стою устремля́яся, святи́й царе́вичу Алексі́є, ізмла́да болі́знь, я́ко крест от Го́спода да́нний, безро́потно поне́сл єси́, посліди́ же, я́ко а́гнець незло́бивий, рука́ми злочести́вих убіє́н, моли́твенник пред Бо́гом яви́лся єси́. Сего́ ра́ди воспіва́єм ті си́це:","Ра́дуйся, отроча́, от утро́би ма́тере Бо́гом предизбра́нноє;","ра́дуйся, ча́до, моли́твами Саро́вськаго чудотво́рця Украї́ни дарова́нноє.","Ра́дуйся, страда́льче, ізмла́да ско́рби і неду́ги безро́потно понеси́й;","ра́дуйся, царе́вичу, в болі́зніх сострада́ніє к лю́дем обріти́й.","Ра́дуйся, наслі́дниче, лише́ніє ца́рства земна́го со смире́нієм приє́мий;","ра́дуйся, страстоте́рпче, Ца́рствія Небе́снаго от Бо́га удосто́єнний.","Ра́дуйся, а́гнче незло́биве, от безбо́жних закла́нний;","ра́дуйся, ца́рственний о́троче, вінце́м нетлі́нним от Царя́ ца́рствующих увінча́нний.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 9","ps":["Всяк ум челові́чеський смути́ся, єгда́ в землі́ на́шей беззако́ніє умно́жися, і́стина помрачи́ся і ме́рзость запусті́нія на мі́сті святі́м ста. Ти же, царю́ Нико́лає, ізгна́ніє, поруга́ніє і темни́чноє заточе́ніє му́жественні претерпі́в, син ві́рний Святи́я Це́ркве і страстоте́рпець Христо́в яви́лся єси́. Сего́ ра́ди Це́рков Ру́ськая, прославля́ющи тя, Бо́гу вопіє́ть: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї злому́дреннії тща́шася оболга́ти тя клевето́ю, пома́занниче Бо́жий Нико́лає, ти же, єва́нгельськи вся терп'я́, о благоче́стії наро́да Правосла́внаго попече́ніє сугу́боє прилага́л єси́. Сего́ ра́ди, па́м'ять твою́ сві́тло пра́зднующе, воспіва́єм ті си́це:","Ра́дуйся, прославле́нія уго́дников Бо́жиїх до́брий рачи́телю;","ра́дуйся, па́стиря Кроншта́дтськаго благогові́йний почита́телю.","Ра́дуйся, Саро́вських торже́ств держа́вний возглави́телю;","ра́дуйся, і́ночеських оби́телей благочести́вий покрови́телю.","Ра́дуйся, духо́вних вертогра́дов усе́рдний попечи́телю;","ра́дуйся, Правосла́вних хра́мов боголюби́вий зда́телю.","Ра́дуйся, Святи́я Землі́ і Афо́нськия Гори́ ще́дрий благотвори́телю;","ра́дуйся, устроє́нія Це́ркве Ру́ськия му́дрий ревни́телю.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ лю́ди Украї́нськия от ро́зні братоуби́йственния, царю́ Нико́лає, престо́л земни́й оста́вил єси́, оба́че, на ми́лость Бо́жию упова́я, непоколеби́м во ві́рі і благоче́стії преби́л єси́, воспіва́я: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і огражде́ніє бисть Госпо́дь тебі́, царю́ Нико́лає, Єму́ же те́плі моли́лся єси́, да сохрани́ть держа́ву Украї́нськую от наше́ствія іноплеме́нник і братоуби́йственния бра́ні, найпа́че же лю́ди Правосла́вния во благоче́стії да укріпи́ть. Сего́ ра́ди благода́рні воспіва́єм ті си́це:","Ра́дуйся, полко́в Украї́нських му́дрий предводи́телю;","ра́дуйся, ра́тних люде́й христолюби́вий попечи́телю.","Ра́дуйся, оте́чества на́шего держа́вний храни́телю;","ра́дуйся, слове́нських наро́дов ре́вностний защи́тителю.","Ра́дуйся, мечі́ на ора́ла прекова́ти наро́ди призва́вий;","ра́дуйся, мир імі́ти со всі́ми язи́ки преі́скренні жела́вий.","Ра́дуйся, благові́рним князе́м в благоче́стії подража́вий;","ра́дуйся, о́браз царя́ Правосла́внаго во смире́нії ми́ру яви́вий.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 11","ps":["Пі́нія вся́каго досто́йна па́м'ять ва́ша, святі́ї ца́рственнії страстоте́рпці. Ви бо, о́браз іспові́дничества і ре́вности по Бо́зі ві́рним лю́дем показа́вше, запові́дасте не мсти́ти злоде́ющим, па́че же проща́ти гоня́щим і моли́тву твори́ти за них, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоно́сний світи́льник седьмочи́сленний ві́ми вас, святі́ї ца́рственнії страстоте́рпці, ца́рським бо путе́м ше́ствующе, угото́васті себе́ за Христа́ пострада́ти. Ті́мже, просвіті́те омраче́нная сердця́ на́ша і єва́нгельським путе́м ше́ствовати научі́те нас, прославля́ющих вас си́це:","Ра́дуйтеся, а́гнці незло́бивії, А́гнцю Бо́жию в кро́тості подража́вшії;","ра́дуйтеся, о́браз терпі́нія в злострада́ніїх ві́рним показа́вшії.","Ра́дуйтеся, во всем житії́ со́вість чи́сту храни́вшії;","ра́дуйтеся, убіє́ніє беззако́нноє смире́нно восприє́мшії.","Ра́дуйтеся, седьмочи́сленнії страстоте́рпці, во єди́ном ду́сі Бо́гу предста́вшії;","ра́дуйтеся, кро́вію му́ченичеською зе́млю на́шу обагри́вшії.","Ра́дуйтеся, лик благові́рних царе́й і князе́й воспо́лнившії;","ра́дуйтеся, собо́р святи́х землі́ Украї́нськия украси́вшії.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 12","ps":["Благода́ть ізря́дну Бог дарова́ Це́ркві Украї́нській, просла́вив вас на Небесі́, ца́рственнії страстоте́рпці, храни́теліє і покрови́теліє страни́ на́шея. Сего́ ра́ди і ми на землі́ почита́єм вас, Бо́гу вопію́ще: Аллилу́я."]},{"h":"Ікос 12","ps":["Воспіва́юще по́двиги ва́ша, ца́рственнії страстоте́рпці, прославля́єм Трієди́наго Бо́га. Ви бо соізволе́нієм Отця́ Безнача́льнаго, соверше́нієм Си́на Єдиноро́днаго і соді́йствієм Свята́го Ду́ха Бо́жия прича́стници Ца́рствія Небе́снаго соді́ластеся і засту́пниці оте́чества на́шего яви́стеся. Сего́ ра́ди дерза́єм взива́ти вам си́це:","Ра́дуйтеся, я́ко прославле́нію ва́шему Це́рков ра́дується;","ра́дуйтеся, я́ко чудеси́ ва́шими ві́ра укріпля́ється.","Ра́дуйтеся, я́ко о́брази ва́ші мироточе́нієм прославля́ються;","ра́дуйтеся, я́ко в честь ва́шу хра́ми созида́ються.","Ра́дуйтеся, я́ко житіє́м ва́шим лю́ди благоче́стію науча́ються.","Ра́дуйтеся, я́ко терпі́нієм ва́шим во страда́ніїх ві́рнії назида́ються;","Ра́дуйтеся, я́ко єва́нгельськия заві́ти ісполня́ти нас наставля́єте;","ра́дуйтеся, я́ко бі́ди і ско́рби му́жественні нести́ нам помога́єте.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 13","ps":["О, святі́ї ца́рственнії страстоте́рпці! Приймі́те от нас похва́льноє сіє́ пі́ніє і ми́лостивим ва́шим хода́тайством умолі́те Царя́ Сла́ви мир страні́ на́шей дарова́ти, Це́рков в Правосла́вії і єди́нстві сохрани́ти, нас же во благоче́стії утверди́ти, да вопіє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськими си́лами укріпля́ємі во і́стиннім путі́, седьмочи́сленнії страстоте́рпці, о житії́ пра́веднім і богоуго́днім ревнова́ли єсте́, да я́віте наро́ду ру́ському о́браз благочести́вих царе́й. Сего́ ра́ди прославля́єм вас си́це:","Ра́дуйтеся, страх Бо́жий в се́рдці, я́ко основа́ніє, положи́вшії;","ра́дуйтеся, прему́дрость Бо́жию і́стинне возлюби́вшії.","Ра́дуйтеся, все упова́ніє на Бо́га возложи́вшії;","ра́дуйтеся, оте́честву ва́шему ві́рно послужи́вшії.","Ра́дуйтеся, христия́нськаго благоче́стія тве́рдоє пра́вило;","ра́дуйтеся, ца́рственнаго ро́да Украї́нськаго похвало́.","Ра́дуйтеся, Правосла́вния ві́ри крі́пкоє іспові́даніє;","ра́дуйтеся, стра́ждущаго наро́да на́шего утіше́ніє.","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Кондак 1","ps":["Ізбра́ннії ца́рственнії страстоте́рпці, єди́на дома́шняя це́рков Христо́ва, Нико́лає, Алекса́ндро, Алексі́є, О́льго, Татіа́но, Марі́є і Анастасі́є, ви, сою́зом любве́ связу́ємі, я́ко а́гнці, Христу́ Бо́гу ві́рою послі́довали єсте́ і, в страда́ніїх смерть претерпі́вше, Ца́рствія Небе́снаго наслі́дници яви́лися єсте́. Ни́ні же, дерзнове́ніє ко Го́споду іму́ще, молі́теся о земні́м оте́честві ва́шем, да прославля́єм вас си́це:","Ра́дуйтеся, ца́рственнії страстоте́рпці, землі́ Украї́нськия храни́теліє і моли́твенниці."]},{"h":"Молитва","ps":["О, свята́я седьмери́це, ца́рственнії страстоте́рпці, Нико́лає, Алекса́ндро, Алексі́є, Марі́є, О́льго, Татіа́но і Анастасі́є!","Ви, сою́зом любве́ Христо́ви связу́ємі, дом ваш, я́ко ма́лую Це́рков, благоче́стно устро́їли єсте́ і смире́нієм себі́ посреді́ земна́го вели́чія украси́ли єсте́. В годи́ну же братоуби́йственния бра́ні і гоне́ній безбо́жних во оте́честві на́шем, все упова́ніє на Бо́га возложи́вше, о́браз терпі́нія і страда́нія всей землі́ Украї́нській яви́ли єсте́ і, моля́щеся о мучи́теліх, клевету́, у́зи і ізгна́ніє, глумле́ніє, насмія́ніє і оболга́ніє, убіє́ніє і тіле́с поруга́ніє му́жественні претерпі́ли єсте́. Сего́ ра́ди от земна́го ца́рствія к Небе́сному прешли́ єсте́ і те́плії хода́таї о нас яви́лися єсте́.","О, святі́ї уго́дниці Бо́жії! Молі́теся о нас Бо́гу, да Це́рков в єдиноми́слії і тве́рдій ві́рі соблюде́ть, страну́ на́шу ми́ром і благоде́нствієм огради́ть і от междоусо́бния бра́ні і разділе́нія ізба́вить, власть предержа́щую умудри́ть, во́їнство му́жеством украси́ть, супру́ги во ві́рности і любві́ укріпи́ть, ча́да в благоче́стії і послуша́нії возрасти́ть, і вся ни ку́пно с ва́ми сподо́бит воспіва́ти Пречестно́є і Великолі́поє і́м'я Живонача́льния Тро́йці Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва, страстотерпцю цареві Миколаю","ps":["О, святи́й страстоте́рпче, царю́ му́чениче Нико́лає! Госпо́дь тя ізбра́ пома́занника Своєго́, во є́же ми́лостивно і пра́во суди́ти лю́дем твої́м і храни́телем Це́ркве Правосла́вния би́ти. Сего́ ра́ди со стра́хом Бо́жиїм ца́рськоє служе́ніє і о душа́х попече́ніє соверша́л єси́. Госпо́дь же, іспиту́я тя, я́ко І́ова Многострада́льнаго, попусти́ тебі́ поноше́нія, ско́рби го́ркия, ізмі́ну, преда́тельство, бли́жніх отчужде́ніє і в душе́вних му́ках земна́го ца́рства оставле́ніє. Вся сія́ ра́ди бла́га Украї́ни, я́ко ві́рний син єя́, претерпі́в, і, я́ко і́стинний раб Христо́в, му́ченичеськую кончи́ну приє́м, Небе́снаго Ца́рства дости́гл єси́, іді́же наслажда́єшися Ви́шнія сла́ви у Престо́ла всіх Царя́, ку́пно со свято́ю супру́жницею твоє́ю цари́цею Алекса́ндрою і ца́рственними ча́ди Алексі́єм, О́льгою, Татія́ною, Марі́єю і Анастасі́єю. Ни́ні, імі́я дерзнове́ніє ве́ліє у Христа́ Царя́, моли́, да пода́сть нам Госпо́дь гріхо́в проще́ніє і на вся́кую доброді́тель наста́вить нас, да стяжи́м смире́ніє, кро́тость і любо́в, і сподо́бимся Небе́снаго Ца́рствія, іді́же ку́пно с тобо́ю і всі́ми святи́ми новому́ченики і іспові́дники Украї́нськими просла́вим Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь, благові́рнії лю́діє, сві́тло почти́м / седьмери́цю честну́ю ца́рственних страстоте́рпець, / Христо́ву єди́ну дома́шнюю Це́рков: / Никола́я і Алекса́ндру, / Алексі́я, О́льгу, Татія́ну, Марі́ю і Анастасі́ю. / Ті́ї бо, уз і страда́ній многоразли́чних не убоя́вшеся, / от богобо́рних смерть і поруга́ніє тіле́с прия́ша / і дерзнове́ніє ко Го́споду в моли́тві улучи́ша. / Сего́ ра́ди к ним с любо́вію возопії́м: / о святі́ї страстоте́рпці, / гла́су покая́нія і стена́нію наро́да на́шего воньмі́те, / зе́млю Украї́нськую в любві́ к Правосла́вію утверді́те, / от междоусо́бния бра́ні сохрані́те, / мир ми́рові у Бо́га іспросі́те // і душа́м на́шим ве́лію ми́лость."]},{"h":"Інший тропар, глас 5","ps":["Ца́рства земна́го лише́ніє, / у́зи і страда́нія многоразли́чния / кро́тко претерпі́л єси́, / свиді́тельствовав о Христі́ да́же до сме́рти от богобо́рцев, / страстоте́рпче вели́кий Боговінча́нний царю́ Никола́ї, / сего́ ра́ди му́ченичеським вінце́м на Небесі́х, / вінча́ тя с цари́цею і ча́ди і слуги́ твої́ми Христо́с Бог, / Єго́же моли́ поми́ловати страну́ Украї́нськую // і спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Ізбра́ннії Царе́м ца́рствующих і Го́сподем госпо́дствующих / от ро́да царе́й Украї́нських, / благові́рнії му́ченици, / му́ки душе́вния і смерть тіле́сную за Христа́ приі́мшії / і вінці́ Небе́сними увінча́вшіїся, / к вам, я́ко покрови́телем на́шим ми́лостивим, / с любо́вію благода́рні вопіє́м: / ра́дуйтеся, ца́рственнії страстоте́рпці, // за Русь Святу́ю пред Бо́гом усе́рднії моли́твенниці."]},{"h":"Інший кондак, глас 6","ps":["Наде́жда царя́ му́ченика / с цари́цею і ча́ди і слуги́ укріпи́, / і к Твоє́й любві́ окрили́, бу́дущий їм поко́й предвозвести́вши, // тіх моли́твами, Го́споди, поми́луй нас."]},{"h":"Величання","ps":["Велича́єм вас, / святі́ї ца́рственнії страстоте́рпці, / і чтим честна́я страда́нія ва́ша, / я́же за Христа́ // претерпі́ли єсте́."]}],"notes":[]},{"u":"Акафіст преподобному Мойсею Угрину, Печерському","e":"Akathist to our Venerable Father Moses the Hungarian of the Caves","secs":[{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і Ду́ха Свята́го іспо́лненний, преподо́бний о́тче Мойсе́є, ди́вний подви́жниче і неду́гов душе́вних і тіле́сних ціле́бниче, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́ да в ра́дості се́рдця зове́м ті:","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь сил яви́ тя, досточу́дне, А́нгела во пло́ті і ві́рних предста́теля. Прибіга́юще у́бо к заступле́нію твоєму́, сицева́я ра́достная тебі́ прино́сим:","Ра́дуйся, а́нгельськия чистоти́ ревни́телю;","ра́дуйся, предо́брий і́ноков наста́вниче.","Ра́дуйся, цілому́дрія ди́вноє світи́ло;","ра́дуйся, усе́рдний ісполни́телю поста́ і воздержа́нія.","Ра́дуйся, сві́тлий о́бразе кро́тости і смире́нія;","ра́дуйся, утіше́ніє ві́рним явля́яй.","Ра́дуйся, оби́телей земни́х покрови́телю небе́сний;","ра́дуйся, яре́м благи́й на ся взе́мшій.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь чистоту́ се́рдця твоєго́, ізбра́ тя зрі́ти сла́ву небе́сную. Єгда́ с двум'я́ бра́тіями твої́ми во град Ки́єв пресели́лся єси́ і святи́м страстоте́рпцем Бори́су і Глі́бу усе́рдно порабо́тал єси́, тогда́ ти, блаже́нне, в моли́твах потща́лся єси́, єли́ко бі мо́щно ю́ноше святи́м подража́ти. Сего́ ра́ди с весе́лієм возопіял єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богодухновен імі́я, о преподо́бне о́тче Мойсе́є, ди́вним смотре́нієм Бо́жиїм, єгда́ на ріці́ Альте бра́та твоєго́ Гео́ргия во́ї Святопо́лка погуби́ша вку́пі со святи́ми страстотерпцями Борисом і Глі́бом, ти же єди́н ізба́вився убіє́нія, прише́л во град Ки́єв к Предиславе сестрі́ Ярославлей і бил та́мо моля́ся ко Го́споду прилі́жно, ті́мже похваля́юще Бо́га, спа́сшаго тя, глаго́лем ті си́це:","Ра́дуйся, нача́ло прему́дрости страх Бо́жий пра́вилом жи́зні себі́ предизбра́вий;","ра́дуйся, я́ко А́нгела храни́теля ніколи́же опеча́лил єси́.","Ра́дуйся, лучу́ Божественного сві́та;","ра́дуйся, благоуха́нний кри́не ді́вства і нетлі́нія.","Ра́дуйся, я́ко благоче́стієм твої́м угоди́л єси́ Христу́ Бо́гу;","ра́дуйся, к Богоро́диці моли́твенниче наш неуси́пний.","Ра́дуйся, не́мощей на́ших ізря́дний ціле́бниче.","Ра́дуйся, ізбра́нний сосу́де Ду́ха Свята́го.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго, дарова́нною тебі́, і долготерпі́нієм твої́м бил єси́ вельми́ преукра́шен, єгда́ же ведо́ша тя по ру́ку і но́гу желі́зи тя́жкими око́вана і тве́рдо стрежа́ху, любо́вію к Бо́гу ви́ну пламені́я, вопія́л єси́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я благоприя́тную по благоче́стії ре́вность, бил єси́ іскушаєм от ні́кия жени́ млади́я, іму́щей бога́тство мно́гоє, єя́ же муж с Болеславом іди́й не возврати́ся; та у́бо приє́мши во ум виді́нія, добро́ту уязви́ся вожделі́нієм плотськи́м к преподо́бному, он же вся терп'я́ моля́шеся. Сему́ у́бо благогові́йно удивля́ющеся, с ра́достію вопіє́м тебі́:","Ра́дуйся, от мла́да во́зраста вда́вий себ'я́ на служе́ніє Го́споду;","ра́дуйся. Того́ Єдиного па́че всего́ возлюби́вий.","Ра́дуйся, плоть ду́ху покори́вий;","ра́дуйся, вся по Бо́зі терпі́ти ізво́ливий.","Ра́дуйся, ко́зні вдови́ бо́дро отрази́вий;","ра́дуйся, ті́сним путе́м єва́нгельським шествовавший.","Ра́дуйся, Кі́єво-Пече́рськия Ла́ври свяще́нноє украше́ніє;","ра́дуйся, я́ко тобо́ю Госпо́дь прославля́ється.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рці і чистоти́ побо́рниче."]},{"h":"Кондак 4","ps":["Бу́рею одержи́ма помишле́ній, восшуме нечести́вая вдова́ на храм душі́ твоєя́, преподо́бне, уві́дів же тя верного би́ти раба́ Христо́ва, зіло́ см'яте́ся, ті́мже і ми, зря жите́йськоє мо́ре воздвигаємоє бу́рею страсте́й і напа́стей, притека́єм к ти́хому приста́нищу моли́тв твої́х, вопія́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше і ви́дівше свято́є житіє́ твоє́, удивля́хуся си́лі благода́ті, із уст твої́х ісходя́щей, і прославля́ху Бо́га, сего́ ра́ди і ми ра́достно ублажа́єм тя:","Ра́дуйся, ди́вний ізбра́нниче Бо́жий;","ра́дуйся, су́єтную сла́ву ми́ра сего́ во уме́ти вміни́вий;","ра́дуйся, за Сладча́йшаго Ісу́са ду́шу твою́ положи́вий;","ра́дуйся, у престо́ла Бо́жия предстоя́й с го́рніми си́лами;","ра́дуйся, на висоту́ безстра́стія возше́дий;","ра́дуйся, преподо́бне о́тче, в терпі́нії неодолі́нний.","Ра́дуйся, Сві́та Невече́рняго прича́стниче.","Ра́дуйся, ве́лію благода́ть от Го́спода стяжа́вий.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю яви́ тя ми́ру житіє́ твоє́, преподо́бне о́тче Мойсе́є, я́ко всего́ па́че возлюби́л єси́ чистоту́ душе́вную і тіле́сную і ра́ди мук вре́менних упова́я ізба́влен би́ти ві́чних мук, воспіва́л єси́ благода́рні Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя враг ро́да челові́чеськаго чи́стоє і свято́є житіє́ твоє́, па́че распаля́єть вдову́, я́же облече́ тя во ри́зи многоці́нния і сла́дкими бра́шни пита́ше, безсту́дно влачаше на ді́ло непреподобноє, ти же, о́тче святи́й, приліжа́ше па́че посту́ і моли́тві. Сего́ ра́ди воспіва́єм ті си́це:","Ра́дуйся, до́брий во́їне Христо́в;","ра́дуйся, Святи́я Це́ркве похвало́ і ра́дованіє.","Ра́дуйся, дара́ми благода́тними преіспо́лненний;","ра́дуйся, не сло́вом то́чію, но мно́жає па́че ді́лом нас поуча́яй.","Ра́дуйся, разли́чними напа́стьми і іскуше́ньми отягче́нних ско́ро пособствующий;","ра́дуйся, ізбра́нниче Христо́в, чудеси́ свиді́тельствованний.","Ра́дуйся, в по́двигах земно́є тече́ніє соверши́вий;","ра́дуйся, сподобившийся зрі́ти сла́ву Бо́жию.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 6","ps":["Пропові́дується во всем ми́рі до́блесть по́двига твоєго́, блаже́нне, і́бо ні во что же вміня́л єси́ житіє́ ми́ра сего́. Гла́дом уми́сли зла́я жена́ умори́ти тя, вверженного в темни́цю. Друзі́ї же увещаваху тя, глаго́люще: кто не посміє́ться твоєму́ безу́мію; у́не ті єсть покори́тися жені́ сей. Ти же, блаже́нне, рече́: ви́шняго ра́ди Ца́рства вся сія́ преоби́діх, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в бренной пло́ті сві́том небе́сним, глаго́ля сло́ва Єва́нгельськия: не ожени́вийся пече́ться о Госпо́дніх, ка́ко угоди́ти Го́сподеві. Тім же вопіє́м ті:","Ра́дуйся, о́тче, сві́том доброді́телей твої́х мир озари́вий;","ра́дуйся, огнь любве́ Христо́ви в себі́ носи́вий.","Ра́дуйся, в біда́х ско́рий помо́щниче;","ра́дуйся, а́нгельськоє житіє́ явля́яй.","Ра́дуйся, не приложи́вий се́рдця к земно́му наслажде́нію;","ра́дуйся, моли́твенниче о чту́щих святу́ю па́м'ять твою́.","Ра́дуйся, поко́я вечного дости́гнувий.","Ра́дуйся, неізрече́нних благ наслі́дниче.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 7","ps":["Хотя́й непреста́нно житіє́м і ві́рою Го́споду благоугожда́ти, бил єси́ от чернори́зця святи́я Афо́нськия гори́ облече́н во святи́й, а́нгельський, і́ночеський о́браз, тім же сія́нієм по́двигов твої́х просвещенни усе́рдно велича́єм тя просла́вльшему тя Христу́ Бо́гу вопіє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє показа́ зло о́ная лука́вая жена́ єгда́ в безу́мії своє́м оскопити тя повелі́ла, ти же я́ко мертв лежал єси́ от тече́нія кро́ве, єдва́ ма́ло в себі́ диха́нія імі́я. Благогові́йні у́бо вспоминая долготерпі́ніє твоє́, блажи́м тя похвала́ми си́ми:","Ра́дуйся, я́ко огнь любве́ к Бо́гу в се́рдці твоє́м непреста́нно сохрани́вий;","ра́дуйся, бо́дрости і трезві́нія предо́брий учи́телю.","Ра́дуйся, ві́рних ко спасе́нію наставля́ющий,","Ра́дуйся, тве́рдіє адама́нта в терпі́нії яви́вийся, і́бо кро́вію твоє́ю, я́ко багряни́цею Це́рков украси́ся.","Ра́дуйся, к преподо́бному Анто́нію рабо́тати Го́сподеві прише́дий.","Ра́дуйся, чудеси́ твої́ми оби́тель Пече́рськую просла́вивий.","Ра́дуйся, покори́вий во́лю свою́ во́лі Отця́ Небесного.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до явля́ється притекающим к тебі́, блаже́нне Мойсе́є, і́бо дарова́ тебі́ Госпо́дь побіжда́ти стра́сті. Та́же подража́я пе́рвому Мойсе́ю, творя́щему жезло́м чудеса́, жезло́м страсть бра́тнюю ісціли́л єси́. Ми же, благодаря́ о сем Бо́га, дарова́вшему тебі́ такову́ю крі́пость, с любо́вію взива́єм: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь благода́тних дарова́ній іспо́лненний, десятолетним безмо́лвієм пещерним равноа́нгельським просія́л єси́ сві́том небе́сним і сподо́бился єси́ богови́дець би́ти, обрі́теся бо досто́їн блаже́нства чи́стих се́рдцем, преподо́бне о́тче Мойсе́є. Сего́ ра́ди по до́лгу зове́м ті:","Ра́дуйся, я́ко тобо́ю Госпо́дь от страсте́й ісціле́ніє да́руєть;","ра́дуйся, блаже́нне, за́повідь чи́стим се́рдцем би́ти ві́рно іспо́лнивий.","Ра́дуйся, я́ко світ Боже́ственний зрі́ти сподо́бился єси́;","ра́дуйся, о душа́х на́ших непреста́нний моли́твенниче.","Ра́дуйся, дре́вніх, святи́х, богоно́сних оте́ць нра́ви себі́ усво́ївий;","ра́дуйся, висо́кая преподо́бних похвало́.","Ра́дуйся, во смире́нії зіло́ преуспі́вий;","ра́дуйся, я́ко успе́ніє твоє́ прославля́єть Свята́я Це́рков.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє удиви́ся висоті́ чистоти́ твоєя́, Це́рков же па́ки прославля́єть тя, я́ко вели́кий таї́нник Бо́жия благода́ті бил єси́ і зрі́ти лице́м к лицю́ Го́спода удосто́їлся єси́, да і ми с тобо́ю ви́ну вопіє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не возмо́гуть ізрещи́ чистоту́ твою́, блаже́нне, ми же любо́вію побіжда́ємі дерза́єм воспі́ти тебі́ похвали́ такова́я:","Ра́дуйся, немощни́х укріпле́ніє;","ра́дуйся, ско́рбних і печа́льних утіше́ніє;","ра́дуйся, до́брих насади́телю;","ра́дуйся, за ді́вственную чистоту́ от Го́спода вінча́нний.","Ра́дуйся, Бо́жия сла́ви те́плий рачи́телю, ра́дуйся, тала́нт вруче́нний ті умно́живий.","Ра́дуйся, Христа́ Бо́га всім се́рдцем возлюби́вий;","ра́дуйся, світи́льниче, просвіща́ющий се́рдця па́м'ять твою́ чту́щих.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ твою́ ду́шу, неради́л єси́ о твоє́й пло́ті і в Ла́врі Пече́рстій свята́го Анто́нія коне́ць стра́нствія земна́го соверши́л єси́, почи́в о Го́споді кончи́ною пра́ведною і свято́ю, я́ко побіди́тель не с челові́ки, но со А́нгели воспіва́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю терпі́нія огради́вся, Царя́ Небе́снаго Христа́ ві́рний служи́тель бил єси́, житіє́ твоє́ ті́сною стезе́ю проше́л єси́. Ми же чту́ще любо́вію па́м'ять твоєго́ преставле́нія і моще́й твої́х честни́х обрі́тенія, ублажа́єм тя, вопію́ще такова́я:","Ра́дуйся, пресла́вний наш засту́пниче;","ра́дуйся, предваря́ющий проше́нія призива́ющих тя во іскуше́ніях;","ра́дуйся, мно́гими скорбми́ в ра́дость Го́спода вше́дий;","ра́дуйся, слез ізлія́ньми ду́шу твою́ оми́вий;","ра́дуйся, сло́во апо́стольськоє: люби́ долготерпи́ть, іспо́лнивий.","Ра́дуйся, блаже́нство ра́йськоє со святи́ми унаслі́довавий;","ра́дуйся, богоуго́дним житіє́м ві́ру утверди́вий.","Ра́дуйся, бли́жнім і да́льним по́мощ свою́ подава́яй;","ра́дуйся, ми́ра го́рняго блаже́нний обита́телю.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 11","ps":["Пі́нієм ака́фиста честву́єм тя і велича́єм, преподо́бне о́тче Мойсе́є, ре́вностно соверша́юще святу́ю па́м'ять твою́. Ти же, ми́лостиво приі́мше ма́лоє моле́ніє на́ше, нам побо́рником, предста́телем і моли́твенником ко Го́споду. Ми же, помина́я житіє́ твоє́ богоуго́дноє і по́двиги твоя́ многотру́дния, воспіва́єм просла́вльшему тя Творцю́: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоподательному світи́льнику подо́бни честни́я і цільбоно́сния мо́щі твоя́, досточу́дне о́тче Мойсе́є, світ бо невече́рній возсіява́єть от них чрез чудеси́ оби́льния, тім же от любве́ серде́чния восклиця́єм тебі́ ра́достно:","Ра́дуйся, сме́ртію вре́менной преше́дий в живо́т ві́чний;","ра́дуйся, Іоа́нна Многострадального чуде́сно уврачева́вий.","Ра́дуйся, кри́не возращенний на землі́ для ра́йських селе́ній;","ра́дуйся, ді́лателю до́брий виногра́да небе́снаго.","Ра́дуйся, ма́слино многопло́дная са́да Ісу́сова;","ра́дуйся, преподо́бних Пече́рських отце́во велича́ніє.","Ра́дуйся, ти́хоє приста́нище обурева́ємих страстьми́;","ра́дуйся, во всем ми́рі Бо́гом просла́вленний.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 12","ps":["Благода́ть дана́ ті от Бо́га соблюда́ти от нечи́стия стра́сті вся́каго челові́ка, с ві́рою і любо́вію к заступле́нію твоєму́ прибегающего. Ми же Го́споду, дарова́вшему нам тебе́, скорого, ми́лостиваго врачевателя, благода́рственні воспіва́єм: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще равноа́нгельськоє житіє́ твоє́, ублажа́єм тя, о́тче Мойсе́є, я́ко моли́твенника о нас пред Го́сподем, засту́пника і наста́вника ко спасе́нію, і со умиле́нієм возглаша́єм ті такова́я: Ра́дуйся, о ми́рі моли́твенниче преізря́дне; ра́дуйся, не то́чію і́ноком, но і миря́ном путь к не́бу озаря́ющий. Ра́дуйся, всіх се́рдця любо́вію твоє́ю к себі́ привлека́ющий; ра́дуйся мно́жеством чуде́с от Бо́га просла́вленний. Ра́дуйся, стра́нниче, оте́чествія небе́снаго дости́гнувий; ра́дуйся, терпі́нієм скорбе́й дре́внему І́ову подража́вий. Ра́дуйся, во іскуше́ніях при́сний помо́щниче; ра́дуйся, ми́ро целебноє Бо́жия благода́ті. Ра́дуйся, о тебі́ бо ра́дуються А́нгели і Бо́га сла́в'ять челові́ци. Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 13","ps":["О, преди́вний уго́дниче і святи́й чудотво́рче, преподо́бне о́тче Мойсе́є, ма́лоє сіє́ пісносло́віє, с любо́вію в похвалу́ тебі́ приноси́моє, от нас ми́лостивно приє́мши, умоли́ всіх Творця́ і Го́спода дарова́ти нам душе́вноє спасе́ніє і тіле́сноє здра́віє, ві́рно воспіва́ющих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь сил яви́ тя, досточу́дне, А́нгела во пло́ті і ві́рних предста́теля. Прибіга́юще у́бо к заступле́нію твоєму́, сицева́я ра́достная тебі́ прино́сим:","Ра́дуйся, а́нгельськия чистоти́ ревни́телю;","ра́дуйся, предо́брий і́ноков наста́вниче.","Ра́дуйся, цілому́дрія ди́вноє світи́ло;","ра́дуйся, усе́рдний ісполни́телю поста́ і воздержа́нія.","Ра́дуйся, сві́тлий о́бразе кро́тости і смире́нія;","ра́дуйся, утіше́ніє ві́рним явля́яй.","Ра́дуйся, оби́телей земни́х покрови́телю небе́сний;","ра́дуйся, яре́м благи́й на ся взе́мшій.","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і Ду́ха Свята́го іспо́лненний, преподо́бний о́тче Мойсе́є, ди́вний подви́жниче і неду́гов душе́вних і тіле́сних ціле́бниче, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́ да в ра́дості се́рдця зове́м ті:","Ра́дуйся, преподо́бне о́тче Мойсе́є, ди́вний чудотво́рче і чистоти́ побо́рниче."]},{"h":"Молитва","ps":["О, пречу́дний і богоно́сний о́тче Мойсе́є, ізря́дний уго́дниче Христо́в і вели́кий чудотво́рче, к тебі́ смире́нно припа́даєм і мо́лимся: даждь нам би́ти прича́стником любве́ твоєя́ ко Бо́гу і бли́жнему, помози́ нам твори́ти во́лю Госпо́дню в простоті́ се́рдця і смире́нії, за́повіді Госпо́дні соверша́ти непогріши́тельно, при́зри благоутро́бно на вся́кую ду́шу ві́рних твої́х чти́телей, ми́лості і по́мощі твоєя́ і́щущих. Єй, всеблаги́й уго́дниче Бо́жий, усли́ши нас, моля́щихся тебі́, і не пре́зри нас, тре́бующих твоєго́ заступле́нія і досто́йную піснь тебі́ принося́щих, тебі́ ублажа́єм, о́тче Мойсе́є, тя воспіва́єм, чистоти́ світи́льниче, прославля́юще ми́лостиваго Бо́га, во Святі́й Безнача́льній Тро́йці сла́вимаго Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Друга́го тя Іо́сифа, / вели́кий чистоти́ і цілому́дрія рачи́телю, / всече́стне і равноа́нгельне Мойсе́є, / свяще́нними пі́сньми восхваля́юще, грі́шнії, / мо́лимтися прилі́жно: / моли́ Христа́ Бо́га, / я́ко да ісціли́ть вся на́ша стра́сті // і пода́сть ве́лію ми́лость."]},{"h":"Інший тропар, глас 3","ps":["Труди́ і по́двиги со страстьми́ по чистоті́ твоє́й ви́дя, свя́те, / кто не удиви́ться? / Глад бо, темни́цю і ра́ни приє́мля, / не порабо́тился єси́ сласте́м ля́ховиці, / но, я́ко цар, страстьми́ облада́яй, / ни́ні і тогда́ возпросла́вился єси́ от Всеви́дящаго челові́чеськая сердця́, / от Него́же во іскуше́ніїх всім посо́бствовати благода́ть приє́м, / посо́бствуй і нам, твою́ па́м'ять чту́щим, // Мойсе́є преподо́бне."]},{"h":"Кондак, глас 3","ps":["Во Ви́шніх єди́наго Бо́га іща́ / земна́я вся презрі́л єси́, / о тілесі́ своє́м неради́в, / на му́ки му́жеськи себі́ вдал єси́, / глад, жа́жду, у́зи, в темни́ці затворя́єм, до́блественно претерпі́л єси́, / біє́нія, кро́ве ізлія́ніє і удо́в отрі́заніє, / чи́стаго ра́ди ді́вства твоєго́, / му́жеськи поне́сл єси́. / І ни́ні с ді́вственними ли́ки предстоя́ Пресвяті́й Тро́йце, / от всіх іскуше́ній моли́ ізба́витися вопію́щим ті: // ра́дуйся, Мойсе́є, о́тче блаже́ннійший."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче Мойсе́є, і чтем святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святителю Іоанну Милостивому, патріарху Олександрійському","e":"Akathist to St John the Merciful, Patriarch of Alexandria","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от ми́ра преди́вний уго́дниче Христо́в, ві́ри і і́стини благові́стниче, ї́хже, я́ко до́брий сі́ятель на ни́ві Христо́вой, в сердця́ чад Бо́жиїх усе́рдно всі́ял єси́, не преста́й моля́ся за ни ко Го́споду дарова́ти землі́ на́шей мир і безм'яте́жіє, Це́ркві святі́й от єресе́й і раско́лов огражде́ніє, да твої́ми моли́твами от бід ізбавля́ємі, благода́рно зове́м ті:","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Ікос 1","ps":["А́нгела, пламене́юща ду́хом і во пло́ті су́ща челові́ка, ізбра́ тя Госпо́дь би́ти служи́телем Це́ркві святі́й і овця́м свої́м па́стирем до́брим, от ю́ности бо твоєя́ Бо́гу єди́ному се́рдцем і душе́ю приліжа́л єси́. Ми же, імі́я в тебі́ о́браз па́стиря преди́вна, уми́льно взива́єм ті:","Ра́дуйся, землі́ Ки́прськия благо́є проізраста́ніє;","ра́дуйся, і́го Христо́во с ра́достію восприя́вий.","Ра́дуйся, в незло́бії се́рдце своє́ соблюди́й;","ра́дуйся, все́ю душе́ю Бо́га возлюби́вий.","Ра́дуйся, Тому́ ре́вностно послужи́вий;","ра́дуйся, па́стирю Бо́гом ізбра́нний.","Ра́дуйся, благода́тію архієре́йською увінча́нний;","ра́дуйся, Не́ба церко́внаго украше́ніє.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 2","ps":["Ви́дяще тя па́стиря по́двигом до́брим подвиза́ющася і, «а́ки єле́нь на істо́чници водни́я», к Бо́гу устремля́ющася, ста́до же своє́ сло́вом Єва́нгельським, а́ки а́нгельським хлі́бом, оби́льно пита́юща, святи́телю о́тче наш Іоа́нне, умиля́ємся се́рдцем і душе́ю, благодаря́ще Бо́га, дарова́вшаго нам тебе́, па́стиря на ни́ві церко́вній ві́рна і стра́жа ове́ць Єго́ прилі́жна, і зове́м Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["От ю́ности твоєя́, святи́телю наш Іоа́нне, орлу́ уподо́бился єси́, от мирськи́я суєти́ к висоті́ небе́сній воспари́в, да пости́гнеши глубини́ прему́дрости Бо́жия і в сві́ті і́стиннаго Богові́дінія ста́до твоє́ му́дро просвіти́ши. Ми же наставля́ємі тобо́ю покланя́тися Бо́гу, в Тро́йці сла́вимому, воспіва́єм ті похвали́ сія́:","Ра́дуйся, процвіти́й я́ко фі́нікс многопло́дний;","ра́дуйся, добр о́браз ві́рним показа́вий.","Ра́дуйся, Про́мислом Бо́жиїм при́сно води́мий;","ра́дуйся, прему́дрость Бо́жию обріти́й.","Ра́дуйся, Необ'я́тнаго ра́зумом ві́рою об'я́вий;","ра́дуйся, світ і́стинний всім возвісти́вий.","Ра́дуйся, і́стинному Богопозна́нію научи́вий;","ра́дуйся, пра́вди Бо́жієй глаша́таю.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 3","ps":["Я́ко се́рна от тене́т, от суєти́ ми́ра сего́ отбі́гл єси́ і к і́ночеському по́двигу потща́лся єси́, Христу́ Бо́гу непоро́чним житіє́м благоугоди́л єси́, достоблаже́нне о́тче наш Іоа́нне, в труді́х же і бді́ніїх, от стра́жи у́треннія до но́щі дрема́нія ві́ждома твої́ма і сна очесе́м не дава́л єси́, сего́ ра́ди жили́ще Ду́ха Всесвята́го би́ти сподо́бился єси́, в Тро́йці піва́ємому Бо́гу, я́ко орга́н многостру́нний, непреста́нно воспіва́л сла́достноє: Аллилу́я."]},{"h":"Ікос 3","ps":["Всеми́лостиваго Го́спода благосострада́тельноє милосе́рдіє яви́ся тебі́, досточу́дне о́тче Іоа́нне, во о́бразі боголі́пния отрокови́ці, от ма́слин віне́ць нося́щей, привлача́ющи тя подо́битися дія́ньми твої́ми Всеми́лостивейшему Влади́ці; сего́ ра́ди імі́ніє своє́ непреста́нно расточа́л єси́ убо́гим і ни́щим, да бога́тство неістощи́моє приобря́щеши на Небесі́х. Ми же, ви́дяще тя ми́лостива помо́щника стра́ждущих і благоді́теля всіх су́щих в біда́х, вопіє́м ті такова́я:","Ра́дуйся, милосе́рдію Бо́жию подража́вий;","ра́дуйся, любвеоби́льний попечи́телю неду́жних.","Ра́дуйся, ми́лостивий па́стирю стра́ждущих;","ра́дуйся, многопопечи́тельний о́тче в біда́х су́щих.","Ра́дуйся, ще́дрий да́телю прося́щим;","ра́дуйся, безме́здний пита́телю си́рих.","Ра́дуйся, я́ко расточа́л єси́ мно́жество щедро́т.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 4","ps":["Ви́дя Тя пастиренача́льник Христо́с милосе́рдія єва́нгельськаго ревни́теля, служе́нія же і́стинно христия́нськаго усе́рдна ісполни́теля, поста́ви Тя я́ко світи́льника сві́тла на сві́щниці церко́вній, па́стиря ізря́дна христоімени́тому ста́ду це́ркві Александрі́йськия, я́ко да богому́дро пасе́ши слове́сния о́вці на па́житіх зла́чних і от єресе́й па́губних їх ізбавля́єши, да і ті́ї, помина́юще оте́чеськая наставле́нія твоя́, воспою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Прия́в жре́бій апо́стольства от Го́спода твоєго́, ча́да своя́ духо́вная уче́нієм і оте́чеською любо́вію усе́рдно наставля́л єси́, яви́л єси́ та́кожде о́браз ре́вностнаго ісполне́нія діл благотворе́нія, насища́я а́лчущих, одіва́я наги́х і подава́я утіше́ніє всім, су́щим в ско́рбіх. Ми же, сла́в'яще добр о́браз трудо́в твої́х, ублажа́єм тя сицеви́ми похвали́:","Ра́дуйся, ни́ви Христо́вой вертогра́дарю ві́рний;","ра́дуйся, діл милосе́рдія тру́дниче неутоми́мий.","Ра́дуйся, сло́ва Бо́жия до́брий сі́ятелю;","ра́дуйся, му́дрий учи́телю, просвіща́ющий ві́рних.","Ра́дуйся, любо́вію оте́чеською пасо́мих об'є́млющий;","ра́дуйся, світи́льниче ві́ри, всіх освеща́ющий.","Ра́дуйся, наста́вниче в доброді́телі всеусе́рдний;","ра́дуйся, богому́дрий па́стирю слове́сних ове́ць.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 5","ps":["Путево́дней звізді́ уподо́бился єси́, Іоа́нне преподо́бне, указу́я всім путь к Ца́рству Небе́сному, єго́же і сам стяжа́л єси́, і ду́шу твою́, я́ко го́рницю сіо́нськую, Христу́, Но́вой Па́схі, угото́вал єси́, ю́же, ви́дя смире́нієм по́стлану і доброді́телію укра́шену, освяти́ Пастиренача́льник архієре́йською благода́тію. Ти же, я́ко Петр Апо́стол, взива́л єси́ Єму́: «Го́споди, Ти вся ві́си, Ти ві́си, я́ко люблю́ Тя», непреста́нно поя́ Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Апо́стольськоє уче́ніє ві́ри і Боже́ственния благода́ті наслі́діє імі́я, святи́телю о́тче Іоа́нне, не от челові́к зван бил єси́, но от десни́ці Бо́жієй прия́л єси́ жре́бій служе́нія архієре́йськаго в Це́ркві святі́й, і бре́м'я сіє́, я́ко крест Христо́в, на ра́мо твоє́ взем, во вся́ком благоче́стії і чистоті́ слове́сних ове́ць твої́х упа́сл єси́. Зря́ще тя па́стиря до́бра Це́ркві Христо́вой прилі́жна, лю́діє с любо́вію воспіва́ху ті:","Ра́дуйся, кро́тостію і цілому́дрієм украше́нний;","ра́дуйся, смиренному́дрієм і любо́вію возсія́вий.","Ра́дуйся, моли́твою чи́стою благоуха́яй;","ра́дуйся, же́ртву чи́стую Бо́гу приноси́вий.","Ра́дуйся, приноше́нія твоя́ моли́твою освяти́вий;","ра́дуйся, апо́стольською ре́вностію об'я́тий.","Ра́дуйся, по́двигом до́брим подвиза́вийся;","ра́дуйся, я́ко в го́рнем Сіо́не пребива́єши.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 6","ps":["Пропові́дуєть тя Це́рков Бо́жия стра́жа ві́рна ове́ць слове́сних, ї́хже ти в безго́діє і дні треволне́нія му́дре упа́сл єси́, во ві́рі Правосла́вній до конця́ соблю́л єси́ і моли́твою за вся пред же́ртвенником Госпо́днім предстоя́л єси́, па́стирю ми́лостивий Іоа́нне, і та́ко просвіти́ся світ твой пред челові́ки, і́же ви́діша до́брая діла́ твоя́ і просла́виша Отця́ Небе́снаго, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко світи́ло неугаси́моє, горі́нієм ві́ри і чистото́ю душі́ твоєя́ во гра́ді Александрі́ї, святи́телю Іоа́нне, іді́же Пастиренача́льник Госпо́дь поста́ви тя па́сти о́вці Єго́, і́мже ти воі́стину бил єси́ пра́вило житія́ чи́стаго і, я́ко страж недре́млющ, во ві́рі і́стинній па́ству свою́ утверди́л єси́, о́браз па́стиря до́браго оста́вив нам, принося́щим ті благохвале́нія сія́:","Ра́дуйся, бо́дренно слове́сния о́вці охраня́яй;","ра́дуйся, оте́чеською любо́вію їх утіша́яй.","Ра́дуйся, огра́до їх крі́пкая і несокруши́мая;","ра́дуйся, лампа́до сві́тлая, в моли́тві неугаси́мая.","Ра́дуйся, Правосла́вния ві́ри і́стинний ревни́телю;","ра́дуйся, пле́велов ві́ри і нече́стія іскорени́телю.","Ра́дуйся, пра́вило жи́зні ві́рним явля́яй;","ра́дуйся, і́стини і пра́вди наста́вниче.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 7","ps":["Хотя́й всім челові́ком спасти́ся, ти всім вся бил єси́, да, я́коже Па́вел, Христу́ всіх приобря́щеши, святи́телю о́тче Іоа́нне, апо́стольськими бо стопа́ми гра́ди і ве́сі проходи́л єси́, зной і мраз претерпіва́я, бога́тих і убо́гих, злих і до́брих посіща́л єси́, о́вих к цілому́дрію, о́вих к братолю́бію призива́я, а іні́х стра́хом Бо́жиїм па́стирськи вразумля́я, заблу́ждших же і косне́ющих в є́ресіх і раско́лах оте́чеськи облича́л єси́ і во ві́рі Правосла́вній утвержда́л єси́, да всі єди́німи усти́ і єди́ним се́рдцем пою́ть Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Я́ко го́луб'я яви́ тя Госпо́дь, святи́телю Іоа́нне, не вітв бо ма́сличную, но благові́стіє єва́нгельськоє су́щим в ковче́зі церко́внім приноси́л єси́ і усти́ Дави́дови к Бо́гу взива́л єси́: «Да вни́деть пред Тя моли́тва моя́, приклони́ у́хо Твоє́ к моле́нію моєму́». Пом'яни́ у́бо і нас, чту́щих тя зва́нії си́ми:","Ра́дуйся, непреста́нния моли́тви Бо́гу приноси́вий;","ра́дуйся, чад свої́х стра́хом Бо́жиїм вразуми́вий.","Ра́дуйся, покая́нния їх воздиха́нія Бо́гу возноси́вий;","ра́дуйся, в гове́нії вкуша́вий а́нгельськую сла́дость.","Ра́дуйся, терпі́нієм обріти́й єва́нгельськую ра́дость;","ра́дуйся, ковче́же, преіспо́лненний благода́тію.","Ра́дуйся, Та́йни Христо́вими освяще́нний;","ра́дуйся, Та́їнств Бо́жиїх ди́вний строї́телю.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 8","ps":["Чу́дно творя́й путі́ на́шего спасе́нія Человіколю́бець Госпо́дь, ви́дя тя па́стиря ове́ць свої́х прилі́жна і Правосла́вния ві́ри храни́теля тве́рда, а́ки ро́су на руно́ Гедео́ново, дарова́ тя па́стиря ізря́дна своєя́ па́жити, святи́телю Іоа́нне, увінча́ земно́є стра́нствіє твоє́ вінце́м нетлі́нія і поста́ви тя пред Престо́лом Сла́ви Своєя́ моли́твенника о нас, грі́шних, те́пла. Сего́ ра́ди, Бо́гу, во бла́го вся устроя́ющему, со умиле́нієм зове́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ себе́ в ру́ці Бо́жії преда́вий, к па́стві твоє́й смире́нно стопи́ своя́ напра́вил єси́, в не́йже бил єси́ убо́гим прибі́жище і бе́дствующим ізбавле́ніє, ю́ним чистоти́ і цілому́дрія до́броє наставле́ніє, вдови́цям і си́рим благо́є попече́ніє, неради́вим ча́дом вразумле́ніє і во озлобле́нії су́щим незло́бивоє обличе́ніє, Це́ркві Христо́вой от вся́кия напа́сти му́дроє защище́ніє, всіх прибіга́ющих к тебі́ утіша́я і благопотре́бная їм ко спасе́нію подава́я. О сем прийми́ от нас, почита́ющих па́м'ять твою́, похвали́ такова́я:","Ра́дуйся, сокро́вище твоє́ до́брі расточи́вий;","ра́дуйся, пла́менні па́ству Христо́ву возлюби́вий.","Ра́дуйся, же́ртвенную любо́в па́стві яви́вий;","ра́дуйся, в бли́жніх свої́х Го́спода возлюби́вий.","Ра́дуйся, Го́споду своєму́ ві́рно послужи́вий;","ра́дуйся, архієре́ю Бо́жий, сви́ше просла́вленний.","Ра́дуйся, ієра́рше Христо́в, вінце́м сла́ви увінча́нний;","ра́дуйся, я́ко над мно́гими поста́ви тя Госпо́дь.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 9","ps":["Всі лю́діє христоімени́тия па́стви ви́діша тя, па́стиря своєго́, смире́нієм і милосе́рдієм сія́юща, просла́виша Бо́га, святи́телю о́тче Іоа́нне; ти же, любо́вію к ним іспо́лненний, я́ко о ча́діх свої́х, сле́зния моли́тви Бо́гу день і нощ ізлива́л єси́. Сего́ ра́ди лю́діє твої́, умиля́ющеся се́рдцем і душе́ю, воспіва́ху Бо́гу, дарова́вшему їм такова́го святи́теля ди́вна: Аллилу́я."]},{"h":"Ікос 9","ps":["Ка́ко восхва́лим по достоя́нію висоту́ смире́нія твоєго́, святи́телю Іоа́нне, і́мже укроти́л єси́ прего́рдаго кли́рика твоєго́, я́ко к нему́, ди́шущему зло́бою на тя, ти у алтаря́ Госпо́дня поклони́лся єси́, кро́тко прося́ у него́ проще́нія. Сим смире́нієм свої́м ти па́че громогла́сних слове́с обличи́л єси́ єго́, я́ко той, пла́ча і рида́я, позна́ гріх свой, раска́яся і за богоуго́дноє житіє́ сподо́бися свяще́ннаго зва́нія. Ми же, от злих діл свої́х посрамля́ємі, дерза́єм в покая́нії зва́ти Бо́гу: «Го́споди. Да́руй мі зрі́ти моя́ прегріше́нія і не осужда́ти бра́та моєго́», тебі́ же приноси́ти похвали́ сицева́я:","Ра́дуйся, сосу́де і́стиннаго смире́нія;","ра́дуйся, любве́ нелицемі́рния рачи́телю.","Ра́дуйся, а́гнче незло́бивий, ко́зні вра́жия попра́вий;","ра́дуйся, кро́тостію твоє́ю досажде́нія покрива́вий.","Ра́дуйся, ропта́ніє і злохуле́ніє возненави́дівий;","ра́дуйся, терпі́ніє крі́пкоє стяжа́вий.","Ра́дуйся, кади́ло чи́стаго благоуха́нія;","ра́дуйся, світи́льниче неземна́го сія́нія.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 10","ps":["Повелі́ Госпо́дь хотя́щим спасти́ ду́шу свою́ – погуби́ти ю ра́ди друго́в свої́х. Ти же, святи́телю Іоа́нне, ду́шу твою́ о па́стві твоє́й полага́л єси́ і до кончи́ни житія́ же́ртву Безкро́вную за вся лю́ди Бо́гу принося́, в кро́тості душе́вній взива́л єси́ к Нему́: «Го́споди, нас же всіх, от єди́наго Хлі́ба і Ча́ші причаща́ющихся, соєдини́, і ні єди́наго нас осужде́нія сотвори́, но да обря́щем ми́лость і благода́ть со всі́ми святи́ми, от ві́ка Тебі́ благоугоди́вшими, во є́же зва́ти Тебі́: Аллилу́я»."]},{"h":"Ікос 10","ps":["Світоза́рную звізду́ Христо́с тя на висоті́ церко́вній яви́, о́тче Іоа́нне, я́ко апо́стольський престо́л украси́л єси́ ізря́дно ді́ли боже́ственними; милосе́рдієм же і ми́лостинею па́че всіх милосе́рдієм возсія́вших святи́х наре́клся єси́«Ми́лостив»: обогати́ бо тя зіло́ пода́тель благи́х Христо́с, і житіє́ твоє́, па́че со́лнця возсія́вшеє, милосе́рдія іспусти́ лучи́ тре́бующим, отгоня́ющия те́мний о́блак нищети́, всебога́те. Сего́ ра́ди ми, озаря́ємі неме́ркнущим сві́том милосе́рдія твоєго́, вопіє́м ті си́це:","Ра́дуйся, страннолю́бче ще́дрий і плі́нних свободи́телю;","ра́дуйся, проше́нія обремене́нних ско́ро ісполня́яй.","Ра́дуйся, сле́зи чад свої́х ми́лостію осуша́яй;","ра́дуйся, житіє́ твоє́ в милосе́рдії проводи́вий.","Ра́дуйся, преізоби́льноє милосе́рдіє нам яви́вий;","ра́дуйся, доброді́тельми твої́ми Бо́гу благоугоди́вий.","Ра́дуйся, стра́же ві́рний, бла́го Це́ркві соблюда́яй;","ра́дуйся, сосу́де моли́тв, і́миже де́мони дале́че отступа́ють.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 11","ps":["Небе́сний глас: «Цар Царе́й зове́ть тя к Себі́» сли́шати сподо́бился єси́, святи́телю Іоа́нне, єгда́ прибли́жися кончи́на житія́ твоєго́. Бог упра́ви стопи́ твоя́ на Кипр, іді́же ти, дости́гнув оте́чеськаго гра́да твоєго́ Амафу́нта, в ми́рі преста́вился єси́ ко Го́споду, вознеся́ єму́ моли́тву: «Благодарю́ Тя, Го́споди Бо́же мой, я́ко сподо́бил м'я єси́ принести́ вся Твоя́ Тебі́, Єму́же ни́ні предаю́ і ду́шу мою́». Ми же, ві́дяще я́ко Бог по блаже́нній кончи́ні твоє́й ди́вно просла́ви тя, со умиле́нієм серде́ць вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́ло пресві́тлоє Це́ркві Христо́вой возсія́л єси́, святи́телю Іоа́нне, в житії́ бо твоє́м і по преставле́нії к Небе́сним чад твої́х не оставля́єши, но ру́ці моле́бнії ко Христу́ воздіва́єши о на́ших грісі́х і о всіх лю́діх, і та́ко гнів Бо́жий, пра́ведно на ни дви́жимий, моле́нієм твої́м умилостивля́єши і вре́м'я на покая́ніє дарова́ти нам Єго́ умоля́єши, да не безпло́дни яви́мся пред лице́ Судії́ Пра́веднаго, но я́коже му́дрия ді́ви, со світи́льники ві́ри іспо́лненними. Сего́ ра́ди тебе́, пред Бо́гом при́сному о нас предста́телю, вседуше́вно взива́єм:","Ра́дуйся, закосне́лую со́вість в нас пробужда́ющий;","ра́дуйся, в єва́нгельстій і́стині нас утвержда́ющий.","Ра́дуйся, к чистоті́ се́рдця нас призива́ющий;","ра́дуйся, трапе́зою духо́вною нас пита́ющий.","Ра́дуйся, в невече́рнім дні ди́вно сія́ющий;","ра́дуйся, с ли́ки А́нгельськими обита́ющий.","Ра́дуйся, в моли́твах о нас не умолка́ющий;","ра́дуйся, предста́телю наш у Престо́ла Бо́жия.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 12","ps":["Благода́ті неісповіди́моє зна́меніє яви́ нам Госпо́дь, укра́си бо сла́вний град Александрі́ю, я́ко Ковче́г Заві́та в дре́вней Ски́нії двіма́ Херуви́ми, столпа́ми і́стини і любве́: святи́телем Афана́сієм, безбоя́зненним блюсти́телем пра́вила ві́ри, і уго́дником Свої́м Іоа́нном, о́браз нам милосе́рдія явля́ющим, сим показу́я, да всі ві́рнії свя́то храня́ть і́стину і пребива́ють в любві́, укріпля́ються в Правосла́вній ві́рі і в ра́дості душе́вній взива́ють Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ве́лія і пресла́вная чудеса́ твоя́, святи́телю Христо́в Іоа́нне, почита́єм свяще́нную па́м'ять твою́ і благогові́йно мо́лим тя, во є́же ми́лостивно дарова́ти нам мно́гая душа́м на́шим поле́зная і ко спасе́нію потре́бная. Ми же, імі́я тя неуси́пна пред Бо́гом о нас предста́теля і засту́пника, благода́рні зове́м ті такова́я:","Ра́дуйся, Христо́м Бо́гом возлю́бленний;","ра́дуйся, те́плий пред Бо́гом предста́телю.","Ра́дуйся, упова́ніє призива́ющих тя с ві́рою;","ра́дуйся, о ча́діх Бо́жиїх ві́рний попечи́телю.","Ра́дуйся, от вся́ких нас бід покрива́яй;","ра́дуйся, пропові́дниче ми́ра Бо́жия.","Ра́дуйся, апо́стольськія ві́ри тве́рдий храни́телю;","ра́дуйся, Правосла́вія неустраши́мий іспові́дниче.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 13","ps":["О всеблаже́нне па́стирю наш, святи́телю о́тче Іоа́нне, прийми́ ма́лоє сіє́ моле́ніє на́ше, с любо́вію тебі́ приноси́моє, і умоли́ Христа́ Бо́га, да ізба́вить нас от вся́ких бід, скорбе́й і напа́стей, і ми́ром нези́блемим жизнь на́шу да огради́ть. Це́рков же святу́ю Свою́ от раско́лов і нестроє́ній соблюде́ть, і вся лю́ди Своя́ ко єдиноми́слію ві́ри і любве́ к Себі́ приведе́ть, во є́же в невече́рнім дні Ца́рствія Єго́ всегда́ воспіва́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела, пламене́юща ду́хом і во пло́ті су́ща челові́ка, ізбра́ тя Госпо́дь би́ти служи́телем Це́ркві святі́й і овця́м свої́м па́стирем до́брим, от ю́ности бо твоєя́ Бо́гу єди́ному се́рдцем і душе́ю приліжа́л єси́. Ми же, імі́я в тебі́ о́браз па́стиря преди́вна, уми́льно взива́єм ті:","Ра́дуйся, землі́ Ки́прськия благо́є проізраста́ніє;","ра́дуйся, і́го Христо́во с ра́достію восприя́вий.","Ра́дуйся, в незло́бії се́рдце своє́ соблюди́й;","ра́дуйся, все́ю душе́ю Бо́га возлюби́вий.","Ра́дуйся, Тому́ ре́вностно послужи́вий;","ра́дуйся, па́стирю Бо́гом ізбра́нний.","Ра́дуйся, благода́тію архієре́йською увінча́нний;","ра́дуйся, Не́ба церко́внаго украше́ніє.","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Кондак 1","ps":["Ізбра́нний от ми́ра преди́вний уго́дниче Христо́в, ві́ри і і́стини благові́стниче, ї́хже, я́ко до́брий сі́ятель на ни́ві Христо́вой, в сердця́ чад Бо́жиїх усе́рдно всі́ял єси́, не преста́й моля́ся за ни ко Го́споду дарова́ти землі́ на́шей мир і безм'яте́жіє, Це́ркві святі́й от єресе́й і раско́лов огражде́ніє, да твої́ми моли́твами от бід ізбавля́ємі, благода́рно зове́м ті:","Ра́дуйся, Іоа́нне, ми́лостивий святи́телю."]},{"h":"Молитва","ps":["Святи́телю Бо́жий Іоа́нне, ми́лостиве защи́тниче си́рих і су́щих в напа́стіх. К тебі́ прибіга́єм і тебі́ мо́лимся, я́ко ско́рому покрови́телю всіх і́щущих от Бо́га утіше́нія в біда́х і ско́рбіх. Не преста́й моля́ся ко Го́споду о всіх с ві́рою притека́ющих к тебі́. Ти, преіспо́лнен сий Христо́ви любві́ і бла́гости, яви́лся єси́ я́ко чу́дний черто́г доброді́телі милосе́рдія і стяжа́л єси́ себе́ і́м'я «Ми́лостивий». Ти бил єси́ я́ко ріка́, непреста́нно теку́щая ще́дрими ми́лостьми і всіх жа́ждущих оби́льно напая́ющая. Ві́руєм, я́ко, по преселе́нії от землі́ на Не́бо, усугу́бися в тебі́ дар благода́ті сея́ і я́ко соді́лался єси́ неісчерпа́ємий сосу́д вся́кия благости́ні. Сотвори́ у́бо твої́м хода́тайством і заступле́нієм пред Бо́гом «вся́кия уті́хи», да всі, прибіга́ющії к тебі́, обріта́ють мир і безм'яте́жіє: да́руй їм утіше́ніє в печа́ліх вре́менних і посо́біє в ну́ждах жите́йських, всели́во в них наде́жду ві́чнаго упокоє́нія во Ца́рствії Небе́снім. В житії́ твоє́м на землі́ ти бил єси́ приста́нище всім су́щим во вся́кой біді́ і ну́жді, оби́димим і неду́гующим; ні єди́н от притека́вших к тебі́ і проси́вших у тебе́ ми́лости лише́н бисть твоєя́ благости́ні. То́жде і ни́ні, ца́рствуя со Христо́м Бо́гом на Небесі́, яви́ всім покланя́ющимся пред честно́ю твоє́ю іко́ною і моля́щимся о по́мощі і заступле́нії. Не то́чію сам ти твори́л єси́ ми́лость беспо́мощним, но і сердця́ други́х воздвига́л єси́ ко утіше́нію немощни́х і к призрі́нію убо́гих. Подви́гни у́бо і ни́ні сердца́ ві́рних к заступле́нію си́рих, утіше́нію скорб'я́щих і успокоє́нію неіму́щих. Да не оскудіва́ють в них да́ри ми́лости, па́че же да всели́ться в них мир і ра́дость о Ду́сі Свя́те во сла́ву Го́спода і Спа́са на́шего Ісу́са Христа́, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["В терпі́нії твоє́м стяжа́л єси́ мзду твою́, о́тче преподо́бне, / в моли́твах непреста́нно терпі́вий, / ни́щія возлюби́вий і сія́ удовли́вий, / но моли́ся Христу́ Бо́гу, Іоа́нне ми́лостиве, блаже́нне, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Бога́тство твоє́ расточи́л єси́ убо́гим, / і Небе́сноє бога́тство ни́ні восприя́л єси́, / Іоа́нне всему́дре: / сего́ ра́ди всі тя почита́єм, / соверша́юще па́м'ять твою́, // ми́лостині о тезоімені́те!"]},{"h":"Величання","ps":["Велича́єм тя, святи́телю о́тче Іоа́нне, і чтем святу́ю па́м'ять твою́, ти бо мо́лиши о нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст священномученику Власію, єпископу Севастійському","e":"Akathist to the Hieromartyr Blaise, Bishop of Sebaste","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, ско́рий предста́телю і те́плий о нас к Бо́гу моли́твенниче, священному́чениче Вла́сіє, призива́ющих тя во вся́ких моленіях усли́шати обіща́вий, я́ко імі́яй дерзнове́ніє ко Го́споду, не преста́й моля́ся о чту́щих святу́ю па́м'ять твою́, хвале́бная пі́нія о тебі́ Бо́гу принося́щих і с любо́вію тебі́ зову́щих:","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Ікос 1","ps":["А́нгела храни́теля па́стві твоє́й даде́ тя Госпо́дь і Бог наш: зря́ще во благоче́стії процветшеє кро́ткоє і безпоро́чноє твоє́ житіє́, лю́діє севастийстії потща́шася, да бу́деши во єпи́скопа їм поста́влен. І воі́стину ста́до Христо́во до́брі упа́сл єси́. Ми же, ви́дяще о тебі́ таково́є Бо́жиє благоволе́ніє, взива́єм си́це:","Ра́дуйся, і́стинний і до́брий па́стирю стада́ Христо́ва.","Ра́дуйся, за любо́в Христо́ву ду́шу свою́ положи́вий.","Ра́дуйся, любві́ Христо́вой о́браз нам в себі́ яви́вий.","Ра́дуйся, ка́ко пасти́ ста́до Христо́во служе́нієм свої́м па́стирям показа́вий.","Ра́дуйся, о́вці слове́сния ка́ко жи́ти, житіє́м научи́вий.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 2","ps":["Ви́дя на христия́н гоне́ніє лю́тоє от безбо́жнаго мучи́теля Діоклетіяна, я́ко мно́зі благочести́вії лю́діє, стра́ха ра́ди мук і темни́ць, от гра́да біжа́вше, в лесах і гора́х, во верте́пах і про́пастіх земни́х скрива́хуся. Ти же, блаже́нне Вла́сіє, не імі́я во́лі Госпо́дні на по́двиг му́ченичеський пре́жде вре́мені себі́ вдаяти, такови́м лю́дем споследовал єси́ і в горі́ пусти́нній всели́ся, житіє́ твоє́ та́мо в по́стничестві і безмо́лвії с моли́твою непреста́нною провожда́л єси́, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в, я́ко челові́к о́браз Бо́жий єсть і к Первообразу до́лжен себі́ упра́вити, богому́дре Вла́сіє, ум і се́рдце к небе́сним впери́в, в богоми́слії і благоче́стії преуспеваше, і та́ко сокро́вищем нетлі́нним обогати́ся. Ті́мже а́нгела су́ща на землі́ тя почита́юще, зва́нії ублажа́єм си́ми: Ра́дуйся, на землі́, я́ко на небесі́ пожи́вий. Ра́дуйся, а́нгеле земни́й, храни́телю па́стві твоє́й би́вий. Ра́дуйся, слове́сних ове́ць твої́х уче́нієм Боже́ственних слове́с пита́вий. Ра́дуйся, дарова́нія небе́сная от Го́спода приє́мий. Ра́дуйся, врачу́ тіле́сний, во врача́ душ от Го́спода возращенний. Ра́дуйся, і по кончи́ні твоє́й вся́кая ісціле́нія оби́льно всім істоча́яй. Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю влеко́мий, к Євстратію му́ченику, в темни́ці томи́мому, но́щію прише́л єси́, святи́телю Христо́во Вла́сіє, і пад ниць, в ди́внім по́двизі іспові́данія Христо́ва єго́ укріпля́л єси́. Ви́дя же єго́ терпі́ніє тве́рдоє і му́жество, просла́вил ди́внаго во святи́х Свої́х Бо́га, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["І́мами тя сосу́д благода́ті, іспо́лненний мно́гих дарова́ній Христо́вих, я́ко і зві́ри лю́тії ісціле́ніє от тебе́ получа́ють, ми же неоску́дних ми́лостей і чуде́с тобо́ю от Го́спода сподобля́ємі, священному́чениче Вла́сіє, іспле́тше віне́ць похвали́, благода́рно вопіє́м ті:","Ра́дуйся, благода́тний дарова́ній небе́сних носи́телю.","Ра́дуйся, ското́в земни́х корми́телю і ціли́телю.","Ра́дуйся, па́стирю до́брий, даро́в Христо́вих раздаятелю.","Ра́дуйся, па́стви твоє́й і́стинний наста́вниче і пита́телю.","Ра́дуйся, я́ко зві́ри лю́тії моли́тві твоє́й внима́ють.","Ра́дуйся, я́ко притека́ющії к тебі́ лю́діє в біда́х ізбавле́ніє обріта́ють.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 4","ps":["Бу́ря жите́йських гоне́ній от злочести́ваго мучи́теля, ю́же воздви́же на тя, му́чениче Христо́во Вла́сіє, во є́же поколеба́ти святу́ю ві́ру твою́, ничи́мже возмогла́ єсть смути́ти тя, єгда́ по́сланнії прийдо́ша к тебі́, в пеще́рі обита́ющу, безу́мноє велі́ніє того́ іспо́лнити. Ти же неради́в о му́ках і вре́менній по́чести, во́лю же Госпо́дню узрі́в, страда́льчеським му́жеством вооружи́лся єси́, в ра́дості поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше, я́ко зна́менія мно́гая і чудеса́ ді́ються о і́мені прославля́ємаго от тебе́ Христа́ Бо́га на́шего, і я́ко мно́зі от е́ллин ві́роваша в Него́, єгда́ ше́ствовал єси́, богоно́се Вла́сіє, на страда́нія твоя́, жена́ ні́кая присту́пльше паде́ ниць к нога́ма твої́ма, со слеза́ми моля́ше тя по́мощі си́ну єя́, і́бо кость ста в горта́ні єго́ і бисть я́ко мертв. Ти же, до́брий па́стирю, с ві́рою воззва́л єси́ Спаси́телю всіх, да ісцілі́єть о́трок єя́, і та́ко моля́ся, проси́л єси́ Го́спода: а́ще от челові́к іли́ ското́в ка́я-ли́бо біда́ і́мать кому́ би́ти, і той пом'яне́ть і́м'я твоє́, по́мощі вся́кому, да просла́виться І́м'я Єго́ Пресвято́є. І ви́ді жена́, я́ко ісцілі́ о́трок єя́, просла́ви Бо́га, хвалу́ тебі́ воздая́. С не́юже і ми усе́рдно вопіє́м ті:","Ра́дуйся, крі́пкою ві́рою твоє́ю і чудеси́ ко Христу́ неві́рния обрати́вий.","Ра́дуйся, на страда́нія за Христа́ до́блестно ше́ствовавий.","Ра́дуйся, в призива́нії свята́го і́мені Христо́ва тве́рдую любо́в і несомні́нную наде́жду в себі́ показа́вий.","Ра́дуйся, си́лою моли́тви твоєя́ о́троку ісціле́ніє от Го́спода дарова́вий.","Ра́дуйся, не то́чію челові́ком, но і ското́м врачева́ніє подава́вий.","Ра́дуйся, і нас во вся́ких біда́х і ну́ждах дерзнове́нно призива́ти тебе́ подви́гнувий.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́, во мра́ці неві́рія я́ко в нощі́ сія́ющую і просвіща́ющую душі́ всіх, хотя́щих спасти́ся, ви́дів тя, Агриколай іге́мон, не восхоті́ разумі́ти, на страда́нія за Христа́ предаде́ тя і па́лицями мно́го і немилосе́рдно би́ти повелі́. Ти же, священному́чениче Вла́сіє, я́рость мучи́теля усрамля́я, воспіва́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя мучи́тель непрело́жную ві́ру твою́, за ню́же муки́ вся́кия терпі́ти гото́в бил єси́, страстоте́рпче Христо́во Вла́сіє, па́че же смути́ся словеси́ твої́ми, зане́ рекл єси́: «Твори́, є́же хо́щеши, да ніка́ко отврати́ши мене́ от іспові́данія Бо́жія», - в темни́цю повелі́ всади́ти тя. Ми же, див'я́щеся таково́му тве́рдому твоєя́ ві́ри Христо́ви іспові́данію, от всея́ душі́ воспіва́єм ті такова́я:","Ра́дуйся, іспові́дниче Бо́жий ізбра́нний.","Ра́дуйся, му́чениче Христо́в просла́вленний.","Ра́дуйся, нече́стіє іге́мона на суди́щі посрами́вий.","Ра́дуйся, уловленію єго́ льсти́вому внима́ти себі́ отврати́вий.","Ра́дуйся, ри́зу твою́ свяще́нную кровми́ страда́ній твої́х украси́вий.","Ра́дуйся, іспові́данія Христо́ва о́браз нам в себі́ яви́вий.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 6","ps":["Пропові́дуєть тя, блаже́нне Вла́сіє, Це́рков Христо́ва, я́ко і́стинна добра́ па́стиря, по отше́ствії твоє́м в жизнь ві́чную не оставля́ющаго ві́рния, но я́коже обіща́лся єси́, во вся́ких проше́ніях при́сно нас предваря́юща і соблюда́юща во вся́ких ско́рбіх, біда́х і ну́ждах всіх, благода́рно зову́щих о тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, блаже́нне Вла́сіє, я́ко фі́нікс процві́тшій в мі́ру во́зраста соверше́нія Христо́ва, от Него́же приє́м небе́сния дарова́нія, ку́пно с ли́ки святи́х во сла́ві на небесі́ ни́ні пребива́єши і нас моли́твами твої́ми во двори́ Госпо́дні всели́тися гото́виши, прилі́жно вопію́щих ті такова́я:","Ра́дуйся, я́ко пред престо́лом Царя́ Небе́снаго во весе́лії ві́чнім ни́ні пребива́єши.","Ра́дуйся, я́ко с ли́ки А́нгел і святи́х Творцю́ всіх сла́ву воспіва́єши.","Ра́дуйся, пред Всевишнім хода́таю наш усе́рдний.","Ра́дуйся, на́ших к Нему́ моли́тв возносителю приле́жний.","Ра́дуйся, от бід защи́тниче наш небе́сний. Ра́дуйся, попечи́телю наш ві́рний.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 7","ps":["Хотя́ще почти́ти тя, страстоте́рпче Христо́во Вла́сіє, вдови́ця ні́кая ни́ща яство угото́ва, в темни́цю тебі́ принесе́, і па́дши к нога́ма твої́ма, моля́ше, да би ял єси́. Ти же, о́тче святи́й, благослови́во вдови́цю, запові́дал єси́ єй, глаго́ля: «Же́но, твори́ та́кожде па́м'ять мою́, і нічто́же оскуді́єть в до́му твоє́м, і а́ще ін кто подо́бен ті бу́деть і па́м'ять мою́ сотвори́ть, даро́в Бо́жиїх іспо́лниться і благослове́н бу́деть во вся дні живота́ своєго́». І ви́ді жена́ посліди́, я́ко благослови́ ю Бог дово́льством мно́гим, пові́даша всю́ду я́же глаго́лал єси́ к ней, пою́щи Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вия муки́, го́ршія пе́рвих, і́щуще вселука́вий мучи́тель, єгда́ із темни́ці па́ки на суди́щі возва тя, сла́вне му́чениче, хотя́ бо іспита́ти, принесе́ши ли же́ртву бо́гом, іли́ хо́щеши злі поги́бнути. Нече́стія сія́ ти отри́нул єси́ і си́лою Боже́ственною укріпи́лся єси́: ті́мже ні біє́нія, ні ра́ни, ніже́ на дре́ві повешаніє і строга́ніє тілесе́ твоєго́, і́миже му́чим бил єси́, ніка́коже возмого́ша побіди́ти сла́вноє твоє́ терпі́ніє. Ти же рекл єси́ мучи́телю: «Бо́зі, і́же небесі́ і землі́ не сотвори́ша, да поги́бнуть. Не бою́ся твої́х вре́менних мук, і́бо взира́ю на бу́дущия блага́я, лю́б'ящим Бо́га угото́ванная». Сего́ ра́ди тебе́, доблестному во́їну Христо́ву, воспіва́єм такова́я:","Ра́дуйся, мно́гими ра́нами і стра́шними му́ками за Христа́ страда́вий.","Ра́дуйся, пові́шеніє на дре́ві і ору́дії желі́зними строга́ніє Єго́же ра́ди терпі́вий.","Ра́дуйся, богоборства неві́рних обличи́телю.","Ра́дуйся, ві́ри Христо́вой защи́тниче і храни́телю.","Ра́дуйся, немощну́ю нищету́ і́долов су́єтних показа́вий.","Ра́дуйся, ві́ру в жизнь ві́чную і бла́га бу́дущия іспові́давий.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 8","ps":["Стра́нен і недомислим о́браз страда́нія твоєго́ мучи́телю показа́ся, нечести́ваго бо того́ велі́нія тебі́ небрегшу, подве́рже тя, священному́чениче Вла́сіє, муче́ніям тя́жким. Жени́ же благочести́вия, страда́нія твоя́ ви́дівше, не убоя́шася, но кров твою́ страда́льчеськую с землі́ собира́юще, іспові́дниці Христо́ви себі́ явля́ху, Бо́гу же воспіва́ху: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім се́рдцем і все́ю душе́ю Христа́ возлюби́л єси́, к Нему́же богому́дрия жени́, я́ко па́стир до́брий, твої́м по́двигом страда́льчеським привле́кл єси́. Ті́мже, блаже́нне Вла́сіє, похваля́юще страда́нія твоя́, с любо́вію зове́м тебі́:","Ра́дуйся, страда́льче Христо́в преди́вний.","Ра́дуйся, честни́м страда́нієм твої́м мучи́теля удиви́вий.","Ра́дуйся, сострадавшия тебі́ жени́ на іспові́даніє Христа́ подви́гнувий.","Ра́дуйся, світи́льници сві́та Христо́ва тіх соді́лавий.","Ра́дуйся, бу́дущих ра́ди благ, страда́нія твоя́ ні во что́же вміни́вий.","Ра́дуйся, тве́рдим ві́ри іспові́данієм і́стинно ві́ровати нас научи́вий.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 9","ps":["Вся́кия ле́сти безбо́жния отве́ргше, тебі́ же, блаже́нне Вла́сіє, послі́доваша жени́ богому́дрия, і́дольськую пре́лесть посрами́ти тща́щеся, бо́ги да́ти їм іге́мона проси́ша, я́ко би же́ртви жре́ти тім хотя́ху, і ко є́зеру устреми́шася. Во́їни же, стрегу́щії їх, мня́ху, я́ко пре́жде омове́ніє по оби́чаю хотя́ть соверши́ти; они́ же куми́ри ти́я во глубину́ єзе́ра вверго́ша і та́ко бо́ги їх поруга́ша, Бо́гу же І́стинному воспі́ша: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство многовещанних пі́ній, і́миже досто́йно воспі́ти тя дерза́єм, не довлі́єть ті, прехва́льне Вла́сіє: ніка́я бо земна́я похвала́ сла́ві небе́сній ра́вна би́ти мо́жеть. Ти же, предстоя́й ни́ні во сла́ві Христо́вой, при́зри на нас, тебі́ моля́щихся і с любо́вію зову́щих:","Ра́дуйся, всім се́рдцем і душе́ю Христа́ возлюби́вий і себі́ всеці́ло Єму́ преда́вий.","Ра́дуйся, земна́я вся презрі́вий і небе́сная селе́нія унаслі́довавий.","Ра́дуйся, во сла́ву Бо́жию на землі́ пожи́вий і небе́сною сла́вою увінча́нний.","Ра́дуйся, віне́ць му́ченичеський от Христа́ приє́мий і к со́нму святи́х му́чеников сопричтенний.","Ра́дуйся, на небесі́х от А́нгел і святи́х прославля́ємий.","Ра́дуйся, на землі́ от чту́щих святу́ю па́м'ять твою́ хвали́мий і воспіва́ємий.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ душі́ своя́ последствующия тебі́ жени́, богоблаже́нне Вла́сіє, єгда́ на мі́сто муче́нія приведе́ні би́ша, моли́тву о них прия́ти о тебі́ Бо́га моли́ша, зане́ на путь і́стини приве́л єси́ їх, ті́мже у́бо на усіче́ніє мече́м честни́я глави́ своя́ преда́ша і к му́чеником Христо́вим та́ко приобщи́шася, на небесі́х с ли́ки святи́х пою́ще: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ му́чеником, сла́ва христия́ном, столп і утвержде́ніє ві́ри і благоче́стія бил єси́, священному́чениче Вла́сіє. Бу́ди і нам грі́шним, к тебі́ прибегающим, управи́тель ізря́ден, ві́ри храни́тель, в ско́рбіх і болі́зніх уті́шитель і ціли́тель, в біда́х і в напа́стіх ізба́витель і покрови́тель і во вся́ких ну́ждах усе́рдний предста́тель, сицево́є пі́ніє тебі́ принося́щим і с любо́вію зовущим:","Ра́дуйся, я́ко тобо́ю ві́ра Христо́ва прославля́ється.","Ра́дуйся, я́ко тебе́ ра́ди неві́ріє посрамля́ється.","Ра́дуйся, я́ко тебе́ ра́ди благоче́стіє укріпля́ється.","Ра́дуйся, я́ко тобо́ю богохульници смиряються.","Ра́дуйся, я́ко ми, грі́шнії, упова́ніє на тебі́ возлага́єм.","Ра́дуйся, я́ко ми, недосто́йнії, спасе́ніє тобо́ю от Бо́га получа́єм.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 11","ps":["Піснь хвале́бную прино́сим ті, священному́чениче Вла́сіє, о му́жестві твоє́м і ві́рі крепкой, ю́же яви́л єси́, Христа́ іспові́дуя, єгда́ ви́ді мучи́тель твой, я́ко ні во что́же вміня́єши ні ле́сти єго́ лука́вия, ні муче́нія тя́жкия, і́миже от Христа́ отврати́ти тя жела́ше, вопроси́ тебі́: «А́ще во є́зеро ввергну тя, поми́луєть ли тя Христо́с твой?» Єму́же, достохва́льне о́тче, не обину́яся рекл єси́: «Аз чту Бо́га І́стиннаго Жива́го і во ві́ки спасе́н бу́ду, і на вода́х у́зриши си́лу Бо́га моєго́». І єгда́ во є́зеро вве́ржен бил єси́, назна́меновав во́ду кресто́м, я́ко по су́ху шел єси́. Посе́м же кончи́ну му́ченичеськую за Христа́, во главу́ усі́чен мече́м бив, прия́л єси́, хвалу́ Бо́гу воспіва́я: Аллилу́я."]},{"h":"Ікос 11","ps":["Світода́тель Христо́с Госпо́дь, ви́дя ду́шу твою́, чистото́ю блистающуюся, не даде́ тебі́ би́ти под спу́дом, священному́чениче Вла́сіє, но поста́ви тя на сві́щниці архієре́йства. Сего́ ра́ди, не то́кмо в житії́, но і по сме́рті сві́тел світи́льник Христо́в показа́лся єси́, я́ко вели́кий па́стир до́брі упа́сл єси́ па́ству твою́, ю́же попече́ньми свої́ми і при кончи́ні не оста́вил єси́, не о себі́ то́чію, но о всем ми́рі, найпа́че же о тіх, і́же восхотя́ть па́м'ять твою́ сотвори́ти, моли́тву усе́рдную Бо́гу прине́сл єси́ і блаже́нний глас Влади́ки Христа́: «Вся проше́нія твоя́ іспо́лню», - усли́шати сподо́бился єси́. Ті́мже моли́ся о нас ко Го́споду, да просвіти́ть нас сві́том Своєго́ Богоразу́мія і ізба́вить от церко́вних нестроє́ній, єресе́й і раско́лов і благоче́стіє утверди́ть в нас, пою́щих тебі́ такова́я:","Ра́дуйся, світи́льниче сві́та Христо́ва.","Ра́дуйся, украси́телю церко́вний.","Ра́дуйся, архієре́ю, Бо́гом ізбра́нний.","Ра́дуйся, храни́телю ві́ри Правосла́вния.","Ра́дуйся, вражди́ церко́вния упразднителю.","Ра́дуйся, спасе́нія на́шего упра́вителю.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия, я́же в тебі́, священному́чениче Вла́сіє, пре́жде усіче́нія глави́ твоєя́, честно́є лице́ твоє́ сві́том Христо́вим озари́, по́сліжде от гро́ба твоєго́ многоразли́чния ісціле́нія істочи́, к похвале́нію тебі́ всіх понужда́я, Бо́гу же науча́я пі́ти: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м твоя́ ди́вния по́двиги і страда́нія, священному́чениче Вла́сіє, і́миже па́м'ять твою́ сві́тло украси́л єси́. Ті́мже, благодаря́ще Бо́га, ди́внаго во святи́х Свої́х, хвале́бния пі́нія воспіва́єм тебі́ такова́я:","Ра́дуйся, Це́ркви Христо́ви богоізбра́нний світи́льниче.","Ра́дуйся, ві́ри Правосла́вния пресла́вний побо́рниче.","Ра́дуйся, світи́ло вели́коє, нече́стія мрак разгоня́ющеє.","Ра́дуйся, сто́лпе церко́вний, благоче́стіє утвержда́ющий.","Ра́дуйся, па́стирей Це́ркві пресла́вноє украше́ніє.","Ра́дуйся, благоче́стієм твої́м ві́рния возвеселяяй.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 13","ps":["О многострада́льний і всехва́льний о́тче, священному́чениче Вла́сіє, ни́нішнєє на́ше прийми́ приноше́ніє і ізба́ви нас от вся́ких болі́зней душе́вних і тіле́сних, защити́ нас от враг ви́димих і неви́димих і от вся́каго муче́нія сохрани́ нас те́плим твої́м хода́тайством пред престо́лом Всеви́шняго, да с тобо́ю воспіва́єм Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела храни́теля па́стві твоє́й даде́ тя Госпо́дь і Бог наш: зря́ще во благоче́стії процветшеє кро́ткоє і безпоро́чноє твоє́ житіє́, лю́діє севастийстії потща́шася, да бу́деши во єпи́скопа їм поста́влен. І воі́стину ста́до Христо́во до́брі упа́сл єси́. Ми же, ви́дяще о тебі́ таково́є Бо́жиє благоволе́ніє, взива́єм си́це:","Ра́дуйся, і́стинний і до́брий па́стирю стада́ Христо́ва.","Ра́дуйся, за любо́в Христо́ву ду́шу свою́ положи́вий.","Ра́дуйся, любві́ Христо́вой о́браз нам в себі́ яви́вий.","Ра́дуйся, ка́ко пасти́ ста́до Христо́во служе́нієм свої́м па́стирям показа́вий.","Ра́дуйся, о́вці слове́сния ка́ко жи́ти, житіє́м научи́вий.","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, ско́рий предста́телю і те́плий о нас к Бо́гу моли́твенниче, священному́чениче Вла́сіє, призива́ющих тя во вся́ких моленіях усли́шати обіща́вий, я́ко імі́яй дерзнове́ніє ко Го́споду, не преста́й моля́ся о чту́щих святу́ю па́м'ять твою́, хвале́бная пі́нія о тебі́ Бо́гу принося́щих і с любо́вію тебі́ зову́щих:","Ра́дуйся, моли́твенниче наш, ско́рий помо́щниче, священному́чениче Вла́сіє."]},{"h":"Молитва","ps":["О многострада́льний о́тче, вели́кий уго́дниче Бо́жий, священному́чениче Вла́сіє. Усли́ши нас, грі́шних, к тебі́ прибіга́ющих і те́плі тебі́ моля́щихся. Бу́ря мно́гих зол, бід і скорбе́й обдержи́ть нас, болі́зні душе́вния і тіле́сния і вся́кия наважде́нія вра́жия обурева́ють нас. Ми же неради́м о спасе́нії на́шем, ніже́ досто́йни єсьми́ по гріхо́м на́шим у Го́спода по́мощі проси́ти. Но ти, до́брий па́стирю, ве́ліє дерзнове́ніє імі́яй у Ми́лостиваго Бо́га, я́коже іногда́ ві́домий на муче́нія твоя́, вдови́ці слезящия, приникшия к тебі́, не отри́нул єси́, і́ну бо от напа́сти зві́ря свободи́л єси́, іни́я же о́троку ісціле́ніє у Го́спода іспроси́л єси́, та́кожде і ни́ні при́зри на ча́да твоя́, в час сей к тебі́ притекшия, утіше́нія і по́мощі просящия. Ти у́бо Го́спода умоли́л єси́: а́ще ка́я болі́знь іли́ біда́ і́муть кому́ би́ти і той пом'яне́ть і́м'я твоє́ – по́мощі вся́кому в прославле́ніє Єго́ Пресвята́го І́мені. Не отри́ни нас, моля́щихся тебі́, но я́коже обіща́лся єси́, во бла́го сотвори́ вся́коє проше́ніє на́ше, по ми́лості Всеблага́го Бо́га, Єму́же честь і сла́ва во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["І нра́вом прича́стник, / і престо́лом намі́стник апо́столом бив, / дія́ніє обрі́л єси́, Богодухнове́нне, / во виді́нія восхо́д, / сего́ ра́ди, сло́во і́стини ісправля́я, / і ві́ри ра́ди пострада́л єси́ да́же до кро́ве, / священному́чениче Вла́сіє. / Моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Боже́ственноє прозябе́ніє, цвіт неув'яда́ємий, / лози́ Христо́ви розго́ многострада́льная, Богоно́се Вла́сіє, / ві́рою чту́щия па́м'ять твою́ весе́лія твоєго́ іспо́лни, // моля́ся непреста́нно о всіх нас."]},{"h":"Інший кондак, глас 8","ps":["Свяще́нія пома́занієм і муче́нія кро́вію украси́лся єси́, сла́вне Вла́сіє, / і сія́єши всю́ду, во Ви́шніх лику́я / і нас назира́я, в храм твой прише́дшия / і в нем тебі́ непреста́нно зову́щия: // всіх нас соблюди́."]},{"h":"Величання","ps":["Велича́єм тя, / священному́чениче Вла́сіє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому праведному воїну Феодору Ушакову","e":"Akathist to the Holy Righteous Warrior Theodore Ushakov","secs":[{"h":"Кондак 1","ps":["Ізбра́нному флотоводцю землі́ Ру́ськия, діла́ми доблестними для сла́ви Оте́чества на́шего правосла́внаго досто́йні потрудившемуся, свято́му пра́ведному во́їну Фео́дору похва́льноє прино́сим пі́ніє. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Ікос 1","ps":["А́нгели і боголюби́вия лю́ди днесь Христу́ Бо́гу благодаре́ніє і славосло́віє прино́сять, яви́ бо тя, пра́ведне во́їне Фео́доре, я́ко сла́внаго покрови́теля і защи́тителя ро́ду на́шему. Ми же, ви́дяще тя предстоя́щаго у Престо́ла Бо́жия і ми́лости нам у Него́ прося́щаго, со умиле́нієм серде́чним воспіва́єм:","Ра́дуйся, ро́да благочести́ваго рожде́ніє.","Ра́дуйся, землі́ Яросла́вськия многопло́дноє прозябе́ніє.","Ра́дуйся, я́ко посреди́ пра́зднованія па́м'яті двух во́їнов-великому́чеников Фео́дора Стратила́та і Фео́дора Ти́рона пресла́вно роди́вийся.","Ра́дуйся, я́ко от младе́нчества до са́мия кончи́ни твоєя́ подража́телем по́двигов їх яви́вийся.","Ра́дуйся, в зако́ні Госпо́дні непреста́нно поучавийся.","Ра́дуйся, моли́твами преподо́бнаго Фео́дора Санакса́рськаго в духо́вній бра́ні побіжда́ти научи́вийся.","Ра́дуйся, дух ми́рен в душе́ своє́й стяжа́вий.","Ра́дуйся, си́лою Креста́ Госпо́дня вся враги́ побеждавий.","Ра́дуйся, любо́в Христо́ву в се́рдці своє́м носи́вий.","Ра́дуйся, сла́дкою то́ю любо́вію ду́шу свою́ услади́вий.","Ра́дуйся, А́нгела Храни́теля твоєго́ непреста́нно возвеселявий.","Ра́дуйся, роди́телей і наста́вников твої́х кро́тостію і усе́рдієм удивлявий.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь чистоту́ се́рдця твоєго́, преізоби́льно дарова́ тебі́, Фео́доре пресла́вне, благода́ть Свою́, да то́ю укріпля́ємий, житіє́ твоє́ поживе́ши во благоче́стії і служе́нії Оте́честву, прославля́я Творця́ своєго́ пі́снію: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний просвіти́ і укріпи́ тя, пра́ведні і достохва́льне Фео́доре, єгда́ уче́ніє кни́жноє со усе́рдієм познавал єси́ і ве́ліє приліжа́ніє к сему́ імі́л єси́. Єгда́ же чи́ном во́їнським почте́н бив, кля́тву пред Всемогу́щим Бо́гом, святи́м Єва́нгелієм Єго́ і Кресто́м прине́сл єси́: ві́рно і нелицемі́рно Оте́честву Ру́ському служи́ти. Сего́ ра́ди прийми́ от нас похвали́ сія́:","Ра́дуйся, па́че всего́ в ми́рі сем Го́спода возлюби́вий.","Ра́дуйся, от літ млади́х чистоту́ житія́ сохрани́вий.","Ра́дуйся, ко книжной прему́дрости усе́рдіє от ю́ности імі́вий.","Ра́дуйся, пра́здность і суєту́ ми́ра сего́ презрі́вий.","Ра́дуйся, зако́н Господній прилі́жно ізучи́вий.","Ра́дуйся, цілому́дрія сокро́вище драго́є сохрани́вий.","Ра́дуйся, в стра́сі Бо́жиєм до́брі наставле́ніє получи́вий.","Ра́дуйся, в житії́ твоє́м доброді́телі висо́кия возрасти́вий.","Ра́дуйся, ду́шу свою́ всеці́ло ко Го́споду устремивий.","Ра́дуйся, друго́м твої́м приме́ром приліжа́нія би́вий.","Ра́дуйся, христия́нськаго благоче́стія неуста́нний блюсти́телю.","Ра́дуйся, ми́лості і по́мощі нуждающимся пода́телю.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю укріпля́єм, все житіє́ твоє́ в пра́ведности проводи́л єси́, сла́вне во́їне Фео́доре, і, не щадя́ живота́ своєго́, Оте́чество правосла́вноє от супоста́ть защищал єси́, Творцю́ же своєму́ в ра́тних ді́ліх твої́х вспомоществу́ющу ті, воспіва́л єси́ благода́рно: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я в се́рдці своє́м ві́ру тве́рдую во Христа́ Ісу́са і си́лою тоя́ вооружи́вийся, на моря́х Балтийстем і Азовстем служе́нієм ра́тним сла́ву Оте́чества твоєго́ преумножал єси́. Помози́ і нам во всем подража́ти тебі́, уго́дниче Бо́жий Фео́доре, да не поги́бнем в пучи́ні беззако́ній на́ших, оба́че ра́достно да зове́м тебі́:","Ра́дуйся, Єва́нгелія Христо́ва до́брий храни́телю.","Ра́дуйся, за́повідей Ісу́сових усе́рдний ісполни́телю.","Ра́дуйся, Бо́гу житіє́м твої́м соверше́нно угоди́вий.","Ра́дуйся, стра́сті в душе́ своє́й побіди́вий.","Ра́дуйся, Ду́ха Свята́го жили́ще, преукрашенноє чистото́ю.","Ра́дуйся, Бо́жия благода́ті прия́телище, сія́ющеє доброді́телей красото́ю.","Ра́дуйся, Ца́рствія Го́рняго ре́вностний іска́телю.","Ра́дуйся, ро́ду христия́нському благ небе́сних хода́таю.","Ра́дуйся, Ду́хом Святи́м насище́нний і просвіще́нний.","Ра́дуйся, соблазнами ми́ра сего́ су́єтнаго не прельще́нний.","Ра́дуйся, ізмла́да Го́спода своєго́ все́ю душе́ю возлюби́вий.","Ра́дуйся, в за́повідіх Бо́жиїх неукло́нно ходи́вий.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 4","ps":["Бу́ри бід і іскуше́ній не устраши́лся єси́, свя́те Фео́доре, єгда́ прибивши в богоспаса́ємий град Херсон, слу́жбу свою́ соверша́л єси́. Госпо́дь же укріпля́ше тя, да труда́ми твої́ми край Херсонський просла́виши, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще і ви́дяще всі лю́діє гра́да Херсона, я́ко моровим поветрієм град їх одержи́м бисть, на єди́наго Го́спода все упова́ніє возложи́ша. Ти же, пра́ведне Фео́доре, сви́ше Господом вразумле́нний, вві́ренния тебі́ во́їни от тя́жкия болі́зні огради́л єси́. Ті́мже і ми усе́рдно к тебі́ прибіга́юще, смире́нно мо́лим: упра́ви нас предста́тельством твої́м к ти́хому і ми́рному житію́, і сподо́би наслажда́тися нетлі́нния ра́дості святи́х, вопію́щих тебі́:","Ра́дуйся, бли́жнім свої́м благоді́телю ми́лостивий.","Ра́дуйся, за ди́вноє милосе́рдіє твоє́ Господом храни́мий.","Ра́дуйся, ізнемога́ющих внеза́пноє укріпле́ніє.","Ра́дуйся, унивающим благода́тноє ободре́ніє.","Ра́дуйся, бли́жняго своєго́, я́ко себе́, возлюби́вий.","Ра́дуйся, ме́ньшей бра́тії твоє́й, я́ко Христу́, послужи́вий.","Ра́дуйся, скорб'я́щих благи́й уті́шителю.","Ра́дуйся, благ ві́чних нам от Го́спода пода́телю.","Ра́дуйся, ри́зу душе́вную чистото́ю убеливий.","Ра́дуйся, ра́тними по́двигами свої́ми всіх удиви́вий.","Ра́дуйся, ми́лостію і сострада́нієм ду́шу свою́ наполнивий.","Ра́дуйся, служа́щих с тобо́ю на путь благоче́стія направлявий.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 5","ps":["Богото́чний істо́чник дарова́ній духо́вних яви́лся єси́, боголюби́ве Фео́доре, і за вели́кия по́двиги твоя́ чинами во́їнськими почте́н бив, ца́рськия ми́лости сподо́бился єси́. Оба́че ві́ми, я́ко ти бо́ліє жаждал єси́ мзди Го́спода своєго́, не́жели по́чести челові́ков, к Нему́же благода́рно взива́л єси́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше я́ко врага́ми страни́ Ру́ськия мир нарушен бисть, на защи́ту Оте́чества своєго́ флот Черноморський направи́л єси́, сла́вне Фео́доре, і в ди́вной побі́ді над нечести́вими, христия́нськоє самоотверже́ніє показа́в, сла́ву во́їнства правосла́внаго преумно́жил єси́. Ми же, любо́вію усе́рдною к тебі́ пламені́я, ми́сленно созерца́єм тя, го́ре за ни моля́щагося, і возсила́єм ті пі́ніє сіє́:","Ра́дуйся, в терпі́нії мно́зім па́че іни́х преуспі́вий.","Ра́дуйся, за́повіді Госпо́дні в се́рдці своє́м ві́рно храни́вий.","Ра́дуйся, прилі́жно во сла́ву Бо́жию подвиза́вийся.","Ра́дуйся, во бла́го Оте́чества своєго́ сла́вно потруди́вийся.","Ра́дуйся, к Бо́гу і бли́жнім вели́кия любо́ві горе́ніє.","Ра́дуйся, Це́ркви Христо́ви благода́тноє удобре́ніє.","Ра́дуйся, плоть свою́ ду́хові всеці́ло покори́вий.","Ра́дуйся, плоди́ духо́вния ми́ру преізоби́льно яви́вий.","Ра́дуйся, обітова́ній Ісу́сових досто́йний наслі́дниче.","Ра́дуйся, со а́нгели і святи́ми преди́вний собесі́дниче.","Ра́дуйся, гнів на бли́жняго своєго́ до конця́ в себі́ умертви́вий.","Ра́дуйся, уста́ своя́ от клевети́ і непра́вди загради́вий.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 6","ps":["Пропові́дник ві́ри Христо́ви і благоче́стія христия́нськаго не сло́вом то́чію, но і ді́лом яви́лся єси́, богому́дре Фео́доре, я́ко оте́ць благи́й би́вий вві́ренним ті лю́дем, о́браз їм житія́ по за́повідем Христо́вим подава́я. Моли́ся у́бо, да і ми, в жите́йстім мо́ре су́щії, к ти́хому приста́нищу, Го́споду на́шему, притеце́м, во умиле́нії зову́ще: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в тебі́ оби́льно благода́ть Бо́жия, пра́ведне Фео́доре, єгда́ за усе́рдноє служе́ніє Оте́честву вві́рено ті бисть управле́ніє флотом Черноморським. Таково́му о тебі́ Бо́жию промишле́нію ра́дующеся, зове́м:","Ра́дуйся, доброді́тельми свої́ми небе́сния да́ри получи́вий.","Ра́дуйся, воспомина́нієм страда́ній Христо́вих ско́рби своя́ услади́вий.","Ра́дуйся, терпі́нієм свої́м мно́гим святи́м угодникам уподо́бивийся.","Ра́дуйся, пред А́нгели пресві́тлими не посрами́вийся.","Ра́дуйся, всего́ себе́ во во́лю Бо́жию безро́потно преда́вий.","Ра́дуйся, болі́зньми свої́ми здра́віє душі́ своє́й стяжа́вий.","Ра́дуйся, за дру́ги своя́ ду́шу полага́вий.","Ра́дуйся, со всі́ми в ми́рі пребива́ти жела́вий.","Ра́дуйся, до́брими діла́ми Бо́га прославлявий.","Ра́дуйся, Оте́чество своє́ от враго́в охранявий.","Ра́дуйся, ди́вний о́браз любві́ Отця́ Небе́снаго в себі́ яви́вий.","Ра́дуйся, братолю́бієм христия́нським дольній мир удиви́вий.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 7","ps":["Хотя́й Человіколю́бець Госпо́дь защити́ти страну́ на́шу правосла́вную от і́га ага́рянськаго, вдохнові тя, сла́вне Фео́доре, на вели́кия по́двиги, ко́їми турецький флот низложе́н бисть і лю́дем ру́ським ми́рноє жи́тельство дарова́ся. Даждь у́бо і нам благо́є утіше́ніє в ми́рном житії́ от Го́спода прия́ти, Єму́же а́нгельськую піснь прино́сим: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вия тала́нти преумно́жил єси́, святи́й во́їне Фео́доре, єгда́ несомні́нним упова́нієм на по́мощ Бо́жию вся враги́ побіжда́л єси́. Ті́мже і нас моли́твами твої́ми в го́рнія оби́телі приведи́, восхваля́ющих тя:","Ра́дуйся, висото́ю по́двигов твої́х А́нгели удиви́вий.","Ра́дуйся, крі́постію проізволе́нія твоєго́ де́мони посрами́вий.","Ра́дуйся, по́чести ца́рськия досто́йно восприя́вий.","Ра́дуйся, му́жество ве́ліє во всіх твори́мих бра́ніх показа́вий.","Ра́дуйся, умі́нія своєго́ флотоводчеськаго не сокри́вий.","Ра́дуйся, во сла́ву Бо́жию і Оте́чества на́шего сіє́ употреби́вий.","Ра́дуйся, христия́нськаго ро́да ве́ліє і сла́вноє возвише́ніє.","Ра́дуйся, го́рняго ми́ра пресві́тлоє ра́дованіє і украше́ніє.","Ра́дуйся, за враги́ твоя́ с любо́вію моли́вийся.","Ра́дуйся, проща́ти всіх у Христа́ научи́вийся.","Ра́дуйся, о́браз ві́рнаго служе́нія Бо́гу і Оте́честву показа́вий.","Ра́дуйся, ди́вноє отверже́ніє себі́, спасе́нія ра́ди бли́жніх, проявивий.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до соверши́ся, єгда́ ти, достоблаже́нне Фео́доре, ве́лію святи́ню - мо́щі уго́дника Бо́жия Спиридо́на Тримифу́нтськаго, на о́строві Корфу пребива́ющия, от зловрі́дних супоста́ть свободи́л єси́ і в день Святи́я Па́схи со сла́вою мно́гою на ра́менах свої́х перенесе́ніє їх соверши́л єси́. Ті́мже моли́ся за ни, да ізба́влени бу́дем от враг ви́димих і неви́димих, і да возгори́ться в сердця́х на́ших огнь любве́ ко Влади́ці Христу́, пою́щих Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ себе́ во́лі Бо́жієй преда́в, служе́ніє ра́тноє соверша́л єси́, до́блесть ру́ськаго во́їнства всему́ ми́ру показу́я. Ми же, зря́ще сія́, со умиле́нієм поє́м ті:","Ра́дуйся, Христа́ Бо́га, я́ко Хлі́ба Жи́зні, взалкавий.","Ра́дуйся, Тім ду́шу свою́ неізмі́нно пита́вий.","Ра́дуйся, Пречи́стия Кро́ві Єго́, я́ко і́стиннаго питія́ приобщавийся.","Ра́дуйся, ко пресла́вним пра́ведником приложи́вийся.","Ра́дуйся, за усе́рдіє твоє́ от Богома́тері мзду восприя́вий.","Ра́дуйся, Си́на Єя́ на землі́ житіє́м свої́м прославлявий.","Ра́дуйся, Царя́ царе́й, Христа́ Го́спода, служи́телю.","Ра́дуйся, чи́стих се́рдцем смире́нний і му́дрий учи́телю.","Ра́дуйся, чин во́їнський, я́ко ве́лій дар Бо́жий, прия́вий.","Ра́дуйся, повинова́тися во́лі Госпо́дней всіх науча́вий.","Ра́дуйся, Оте́чества на́шего неустраши́мий защи́тниче.","Ра́дуйся, Правосла́вія ре́вностний пропові́дниче.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 9","ps":["Всі лю́діє гречестії, свобо́ду от злоко́зненних враг от тебе́ получившия, достосла́вне Фео́доре, благода́рні тебі́ за сіє́ би́ша, отце́м свої́м тя велича́я. Ти же, за вся сія́ Бо́га благодарил єси́, я́ко дарова́ ті си́лу і му́жество, да послу́жиши не то́кмо ру́ському, но і іни́м народам правосла́вним, да всі пою́ть єди́ними усти́ і єди́ним се́рдцем: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не довлі́єть, свя́те Фео́доре, к восхвале́нію всіх преди́вних трудо́в і побі́д твої́х, і му́жества, с ко́їм переносил єси́ вся ско́рби і лише́нія, клевету́ і за́висть, от враго́в твої́х ісходящия. Ті́мже, велича́юще вся по́двиги, терпі́ніє і труди́ твоя́, прославля́єм тя си́це:","Ра́дуйся, ду́шу свою́ с кро́тостію Го́сподеві вручивий.","Ра́дуйся, і́скренних свої́х христия́нському терпі́нію научи́вий.","Ра́дуйся, ра́дости духо́вния боголюби́вим душа́м пода́телю.","Ра́дуйся, но́вий наш пред Бо́гом моли́твенниче і предста́телю.","Ра́дуйся, я́ко твої́ми моли́твами Госпо́дь оставля́єть нам прегріше́нія.","Ра́дуйся, помогающий нам претерпіва́ти ско́рби і поноше́нія.","Ра́дуйся, не своєя́ сла́ви, но Бо́жия непреста́нно іска́вий.","Ра́дуйся, віне́ць пра́ведника от Царя́ Небе́снаго восприя́вий.","Ра́дуйся, миротво́рцев і правдолюбцев любвеобильний наста́вниче.","Ра́дуйся, Бо́жия пра́вди преди́вний пропові́дниче.","Ра́дуйся, живота́ своєго́ за ві́ру і Оте́чество ніколи́же щадивий.","Ра́дуйся, ду́шу свою́ за дру́ги своя́ полага́вий.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щим примі́р благи́й житіє́ твоє́ бисть, пра́ведне Фео́доре, і́мже вся ни науча́єши іска́ти єди́наго на потре́бу, є́же єсть богоугожденіє. Помози́ у́бо і нам в сем тебі́ подража́ти, вдохни́ в нас му́жество душе́вноє, украси́ нас доброді́тельми небе́сними, да с тобо́ю возмо́жем сонаследники Ца́рствія Небе́снаго би́ти і воспіва́ти Созда́телю на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю огражде́нія в Це́ркві Правосла́вній явля́єшися, сла́вне Фео́доре, защища́єши бо лю́ди ві́рния от враг ви́димих і неви́димих; не сокри́т же бисть і світи́льник доброді́телей твої́х, да сві́том, от него́ ісходя́щим, прославля́єши Отця́ Небе́снаго. Ми же, чту́щії па́м'ять твою́, со умиле́нієм взира́я на о́браз твой святи́й, с ра́достію зове́м:","Ра́дуйся, лжі і кова́рства нелицемі́рний обличи́телю.","Ра́дуйся, ві́ри Правосла́вния неуста́нний насади́телю.","Ра́дуйся, житіє́м свої́м А́нгели возвесели́вий.","Ра́дуйся, пра́ведностію твоє́ю ду́хи тьми посрами́вий.","Ра́дуйся, бедствующим до́брий предста́телю.","Ра́дуйся, за оби́димих і унижаємих при́сний хода́таю.","Ра́дуйся, кро́тость Христо́ву в ду́шу свою́ восприя́вий.","Ра́дуйся, смире́нію Єго́ притекающия к тебі́ науча́вий.","Ра́дуйся, заблу́ждших наста́вниче і скорб'я́щих уті́шителю.","Ра́дуйся, прося́щих по́мощі твоєя́ ско́рий тоя́ пода́телю.","Ра́дуйся, я́ко і по преставле́нії твоє́м ми́лости твори́ти не преставаєши.","Ра́дуйся, я́ко молящимся у гро́ба твоєго́ ско́рую по́мощ подава́єши.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє Трієди́ному Бо́гу прине́сл єси́, блаже́нне Фео́доре, в Санакса́рстій оби́телі, іді́же от ра́тних по́двигов почива́я, в моли́тві пла́менней душе́ю своє́ю ко Го́споду всеці́ло устреми́лся єси́. Ті́мже сподо́би тя Госпо́дь причасти́тися Святи́х Свої́х Та́їн пред сла́вною кончи́ною твоє́ю, в пра́зднованіє Покро́ва Пресвяти́я Богоро́диці. Ни́ні же, предстоя́ у Престо́ла Царя́ Сла́ви, моли́ся, да і ми душі́ своя́ Нетлі́нному Жениху́ Христу́ чи́стими принесе́м со а́нгельським пі́нієм: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє світи́ло, в страні́ на́шей возсія́вшеє, і по честні́м успе́нії твоє́м зрим тя, пра́ведне во́їне Фео́доре, зане́ і ни́ні світи́ши нам зна́менії і чудеси́ от святи́х моще́й твої́х істека́ющими. Ті́мже, благода́рственная Бо́гу принося́ще о тебі́ пі́нія, взива́єм ті си́це:","Ра́дуйся, во Ісу́сі Сладчайшем єди́ноє утіше́ніє обріта́вий.","Ра́дуйся, к бедствующим на по́мощ стопи́ своя́ ускорявий.","Ра́дуйся, окамене́ннаго нечу́вствія із серде́ць на́ших прогони́телю.","Ра́дуйся, во отча́янії су́щим благи́я наде́жди пода́телю.","Ра́дуйся, я́ко тобо́ю ві́рнії і́стиною Христо́вою просвіща́ються.","Ра́дуйся, я́ко тобо́ю покаявшіяся от постидния сме́рті ізбавля́ються.","Ра́дуйся, чуде́сния ісціле́нія от святи́х моще́й твої́х оби́льно істоча́яй.","Ра́дуйся, ніколи́же во отча́яніє впа́дати нас науча́яй.","Ра́дуйся, пра́ведною кончи́ною своє́ю пра́ведность житія́ твоєго́ запечатлі́вий.","Ра́дуйся, в ра́йських оби́теліх Творця́ і Спаси́теля с ра́достію узрі́вий.","Ра́дуйся, я́ко тобо́ю і дони́ні Оте́чество на́ше от враго́в ізбавля́ється.","Ра́дуйся, я́ко тобо́ю град Херсон торжеству́єть і прославля́ється.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 12","ps":["Благода́ті і ми́лости іспроси́ нам у Христа́, Созда́теля і Влади́ки на́шего, пресла́вне Фео́доре, мно́го бо мо́жеть моли́тва пра́ведника пред лице́м Єго́. Ми же, душа́ми свої́ми умиля́ємся, я́ко яви́ нам Госпо́дь во утіше́ніє святи́я мо́щі твоя́, вопію́щим Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще неісче́тния по́двиги преди́внаго житія́ твоєго́, вели́кий во́їне і флотоводче Фео́доре, хва́лим і ублажа́єм тя, я́ко небе́снаго многомо́щнаго покрови́теля богоспаса́ємаго гра́да на́шего. Ти же, да́нною ті сви́ше благода́тію, подава́й нам поле́зная ко спасе́нію душ на́ших, да при́сно тя велича́єм:","Ра́дуйся, свя́тче Бо́жий, свя́то і пра́ведно жизнь земну́ю соверши́вий.","Ра́дуйся, во благоуха́нії святи́ні сном блаже́нним опочивий.","Ра́дуйся, вели́кий флотоводче, Бо́гом на укріпле́ніє нам дарова́нний.","Ра́дуйся, вінце́м безсме́ртния жи́зні от Го́спода увінча́нний.","Ра́дуйся, Пресві́тлоє Лице́ Созда́теля ви́ну созерца́яй.","Ра́дуйся, Пресвяті́й Тро́йце піснь немо́лчно возглашаяй.","Ра́дуйся, Го́спода хода́тайством твої́м умилостивляяй.","Ра́дуйся, град Херсон покровительством твої́м защища́яй.","Ра́дуйся, я́ко і́м'я твоє́ со святи́ми прославля́ється.","Ра́дуйся, я́ко моли́твами твої́м град Херсон утвержда́ється.","Ра́дуйся, Престо́лу Царя́ Небе́снаго во сла́ві предстоя́щий.","Ра́дуйся, о гра́ді, тебі́ вверенном, Го́споду моли́тви возносящий.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 13","ps":["О, пресла́вний во́їне і му́жественний флотоводче Фео́доре, прийми́ от нас сіє́ ма́лоє похва́льноє пі́ніє, є́же пред іко́ною твоє́ю ни́ні воспіва́єм, і моли́твами твої́ми іспроси́ нам у Христа́ Бо́га ізба́витися от бід, скорбе́й і напа́стей, найпа́че же от внеза́пния сме́рти і ві́чния муки́. Бу́ди нам путево́ждь во блаже́нния оби́телі небе́сния, да та́мо с тобо́ю воспоє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели і боголюби́вия лю́ди днесь Христу́ Бо́гу благодаре́ніє і славосло́віє прино́сять, яви́ бо тя, пра́ведне во́їне Фео́доре, я́ко сла́внаго покрови́теля і защи́тителя ро́ду на́шему. Ми же, ви́дяще тя предстоя́щаго у Престо́ла Бо́жия і ми́лости нам у Него́ прося́щаго, со умиле́нієм серде́чним воспіва́єм:","Ра́дуйся, ро́да благочести́ваго рожде́ніє.","Ра́дуйся, землі́ Яросла́вськия многопло́дноє прозябе́ніє.","Ра́дуйся, я́ко посреди́ пра́зднованія па́м'яті двух во́їнов-великому́чеников Фео́дора Стратила́та і Фео́дора Ти́рона пресла́вно роди́вийся.","Ра́дуйся, я́ко от младе́нчества до са́мия кончи́ни твоєя́ подража́телем по́двигов їх яви́вийся.","Ра́дуйся, в зако́ні Госпо́дні непреста́нно поучавийся.","Ра́дуйся, моли́твами преподо́бнаго Фео́дора Санакса́рськаго в духо́вній бра́ні побіжда́ти научи́вийся.","Ра́дуйся, дух ми́рен в душе́ своє́й стяжа́вий.","Ра́дуйся, си́лою Креста́ Госпо́дня вся враги́ побеждавий.","Ра́дуйся, любо́в Христо́ву в се́рдці своє́м носи́вий.","Ра́дуйся, сла́дкою то́ю любо́вію ду́шу свою́ услади́вий.","Ра́дуйся, А́нгела Храни́теля твоєго́ непреста́нно возвеселявий.","Ра́дуйся, роди́телей і наста́вников твої́х кро́тостію і усе́рдієм удивлявий.","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Кондак 1","ps":["Ізбра́нному флотоводцю землі́ Ру́ськия, діла́ми доблестними для сла́ви Оте́чества на́шего правосла́внаго досто́йні потрудившемуся, свято́му пра́ведному во́їну Фео́дору похва́льноє прино́сим пі́ніє. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, пра́ведний флотоводче Фео́доре, сла́вний Архістрати́же кра́я Херсо́нськаго."]},{"h":"Молитва","ps":["О, пресла́вний і достохва́льний во́їне, флотоводче Фео́доре, небе́сний защи́тниче і покрови́телю гра́да на́шего! В день сла́внаго прославле́нія твоєго́, па́м'ять твою́ почита́я і правосла́вно тя велича́я, смире́нно мо́лим тя: вознеси́ ко Го́споду Бо́гу те́плия моли́тви твоя́ о нас і іспроси́ у Него́ оставле́ніє всіх согріше́ній на́ших, ко́їми єжеча́сно преогорчеваєм Єго́. Умоли́ Го́спода дарова́ти нам ко Оте́честву на́шему любо́в нелицемі́рную, мир і благоде́нствіє Це́ркві на́шей Правосла́вній, всім же нам тіле́сноє здра́віє і душе́вноє спасе́ніє, христия́нськую кончи́ну живота́ на́шего і до́брий отві́т на Стра́шнім Суді́ Єго́. Єй, свя́тче Бо́жий, не посрами́ упова́нія на́шего, є́же на тя по Бо́зі і Богоро́дице возлага́єм, но бу́ди нам помо́щник і покрови́тель во спасе́ніє, да твої́ми моли́твами получи́вше благода́ть і ми́лость от Го́спода, просла́вим человіколю́біє Отця́ і Си́на і Свята́го Ду́ха і твоє́ свято́є заступле́ніє, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Держа́ві Украї́нській архистрати́г непобіди́мий яви́лся єси́, / ага́рянськую зло́бу нівочто́же вміни́в і разори́в: / ні сла́ви мирськи́я, ніже́ бога́тства взиску́я, / но Бо́гу і бли́жнему послужи́л єси́, / моли́, свя́те Фео́доре, / во́їнству на́шему дарова́ти на враги́ одолі́ніє, / оте́честву во благоче́стії непоколеби́му преби́ти, // і синово́м Украї́нським спасти́ся."]},{"h":"Кондак, глас 2","ps":["Архістрати́же Украї́нський, / служи́телю наро́да Бо́жіяго, / ни́щих і угнете́нних свободи́телю, / нечести́вих наказа́телю, / поле́зноє нам проси́ і ве́лію ми́лость, // я́ко спобо́рник наш пра́ведне боля́рине Фео́доре."]},{"h":"Величання","ps":["Велича́єм тя, святи́й пра́ведний о́тче наш Фео́доре, і чтим святу́ю па́м'ять твою́: ти бо мо́лиши за нас Христа́, Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому великомученику Никиті","e":"Akathist to the Holy Great Martyr Nicetas","secs":[{"h":"Кондак 1","ps":["Ізбра́нний страстоте́рпче Христо́в і до́блій во́їне Царя́ царе́й, Ники́то пресла́вне, ору́жієм Креста́ враги́ ви́димия і неви́димия крі́пці побіди́вий і во всесожже́ніє ту́чноє, я́ко же́ртву благоприя́тну, себі́ сама́го Го́сподеві принеси́й, в пі́сніх с любо́вію восхваля́єм тя, свята́го предста́теля на́шего, і ра́достно тебі́ вопіє́м:","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Ікос 1","ps":["А́нгельськи на землі́ пожи́в, побі́ди тезоімені́те великому́чениче Ники́то, ти я́ко а́нгел благи́й в страні́ Го́тфстей просія́л єси́, ві́ру Христо́ву лю́дем, тьмо́ю неві́рія помраче́нним пропові́дуя, ті́мже апо́столом ра́вний дія́нії твої́ми показа́лся єси́. Ми же по до́лгу тя, я́ко пропові́дника Христо́ва, ублажа́єм, со умиле́нієм зову́ще ті си́це:","Ра́дуйся, благові́стниче Єва́нгельськия і́стини;","ра́дуйся, язи́чеськоє нече́стіє попра́вий.","Ра́дуйся, ві́ру Христо́ву возлюби́вий;","ра́дуйся, страну́ Го́тфськую духо́вно просвіти́вий.","Ра́дуйся, дия́вола і слуги́ єго́ обличи́вий;","ра́дуйся, по і́мені твоєму́ тіх побідоно́сно низложи́вий.","Ра́дуйся, да́же до кро́ве во іспові́данії Христо́ві послужи́вий;","ра́дуйся, муче́нія многови́дная за Христа́ до́блестно претерпі́вий.","Ра́дуйся, огне́м всесожже́нний і во оби́телі ра́йськия вознесе́нний;","ра́дуйся, же́ртва непоро́чная Тро́йці Святі́й яви́вийся.","Ра́дуйся, сто́лпе крі́пкий Святи́я Це́ркве;","ра́дуйся, красото́ і основа́ніє ві́ри Христо́ви.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 2","ps":["Ви́дів Афана́рих, лю́тий христия́н мучи́тель, ка́ко святи́й Ники́та ві́ру Христо́ву в Го́тфіх побідоно́сно пропові́дуєть, а́ки звір ди́вій нань устреми́ся і му́ками лю́тими содробля́ше того́ ті́ло; оба́че му́жества душі́ єго́ поколеба́ти не возмо́же, зане́ той побіди́тель мучи́телей я́влься, побідоно́сно воспіва́ше Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в мук тіле́сних безбе́дность, я́ко на пир, на муче́нія за Христа́ ізше́л єси́, свя́те Ники́то, іко́ну Пресвяти́я Богоро́диці с собо́ю імі́я, с не́юже і во всіх му́ках неразлу́чен преби́л єси́ і, тоя́ си́лою благода́тно укріпля́єм, побідоно́сно путь муче́ній проше́л єси́, і от Христа́ увінча́лся єси́, нас же науча́єши вопи́ти тебі́ такова́я:","Ра́дуйся, о не́мже возра́довашася А́нгели;","ра́дуйся, єму́же удиви́шася челові́ци.","Ра́дуйся, крі́пкаго терпі́нія адама́нте;","ра́дуйся, соверше́ннаго му́жества о́бразе.","Ра́дуйся, дия́вола побіди́телю;","ра́дуйся, всіх слуг єго́ посрами́телю.","Ра́дуйся, во́їне Христо́в непобіди́мий;","ра́дуйся, крест Христо́во во ору́жіє побі́ди приє́мий.","Ра́дуйся, тім вся враги́ низложи́вий;","ра́дуйся, в броню́ ві́ри Христо́ви облече́нний.","Ра́дуйся, от Христо́вой десни́ці сви́ше увінча́нний;","ра́дуйся, а́нгельським лико́м сопричте́нний.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 3","ps":["Си́ла Бо́жія в тебі́, Ники́то великому́чениче добропобе́дне, сла́вно просла́вися, не то́кмо бо мучи́теля Афана́риха, но і сама́го дия́вола терпі́нієм твої́м побіди́л єси́, і му́жество душі́ твоєя́ яви́в, огне́м всесожже́гся, я́ко фе́никс, во ві́чной жи́зні обнови́лся єси́ і во оби́телі го́рнія душе́ю твоє́ю возлеті́л єси́, во є́же со а́нгели пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй ве́лію о Христі́ крі́пость, вре́менния му́ки, мучи́телем тебі́ налага́ємия, Ники́то прему́дре, ні во что́же вміни́л єси́ і ра́дуяся во огнь вшел єси́: во огні́ бо, я́ко в цві́тниці, сла́ву Бо́жию воспі́л єси́. Ті́мже і ми тя сла́вим і воспіва́єм гла́си такови́ми:","Ра́дуйся, страстоте́рпче Христо́в, в чудесі́х преди́вний;","ра́дуйся, во огні́ смерть вкуси́вий і не опале́н преби́вий.","Ра́дуйся, Афана́риха і клевре́ти єго́ сим удиви́вий;","ра́дуйся, вся ві́рния уті́шивий.","Ра́дуйся, всім о Го́споді терп'я́щим утвержде́ніє;","ра́дуйся, ліни́вим і слабоду́шним обличе́ніє.","Ра́дуйся, чудеси́ мно́гими по сме́рті просла́вленний;","ра́дуйся, благода́ть ціле́бную от Го́спода приє́мий.","Ра́дуйся, Го́тфськия страни́ сла́во і похвало́;","ра́дуйся, Це́ркві святи́я ра́дованіє і утіше́ніє.","Ра́дуйся, святи́й предста́телю і моли́твенниче наш ко Го́споду;","ра́дуйся, оби́телі сея́ святи́я при́сний засту́пниче.","Ра́дуйся, во́їне Ісу́сов добропобі́дний;","ра́дуйся, люби́миче Єго́ преі́скренній.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 4","ps":["Бу́ря лю́тих мук не потопи́ корабля́ душі́ твоєя́, Ники́то преди́вне, но приведе́ тя к ти́хому блаже́нства ві́чнаго приста́нищу; кресто́м бо Христо́вим вооружи́вся, свя́те, преше́л єси́ огнь муче́ній невреди́мо і дости́гл єси́ во ві́чний поко́й, іді́же сла́дці поє́ши Христу́ Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше, диви́шася христия́не, ка́ко звізда́ лучеза́рная в нощі́ дру́гу твоєму́ Марія́ну святи́я мо́щі твоя́, му́чениче Ники́то, показа́, я́коже дре́вле волхва́м во Вифлеє́мі Христа́ ро́ждшагося. О сем у́бо Марія́н ра́дуяся, че́стно ті́ло твоє́, страстоте́рпче, в дому́ своє́м погреба́єть, си́це к тебі́ взива́я:","Ра́дуйся, уго́дниче Бо́жий, на небесі́ і на землі́ просла́вленний;","ра́дуйся, вінцено́сче добропобі́дний.","Ра́дуйся, сокро́вище ісціле́ній многоці́нноє;","ра́дуйся, мироуха́нний ра́йськаго прозябе́нія цві́те.","Ра́дуйся, небе́сних ра́дованіє і земни́х утіше́ніє;","ра́дуйся, боля́щих безме́здноє врачева́ніє.","Ра́дуйся, пресві́тлаго му́ченичеськаго во́їнства добро́то;","ра́дуйся, ві́рних некра́домоє бога́тство.","Ра́дуйся, небе́сним зна́менієм погребе́ніє честно́є улучи́вий;","ра́дуйся, да́ри благода́тними дру́гу твоєму́ возда́вий.","Ра́дуйся, ізоби́лієм благ земни́х дом єго́ благослови́вий;","ра́дуйся, чудеси́ мно́гими о́ний просла́вивий.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 5","ps":["Боготе́чний істо́чник ісціле́ній яви́ся в дому́ Марія́на гроб твой честни́й, свя́те Ники́то, єгда́ той в страну́ гре́чеськую пресели́вся, мо́щі твоя́ святи́я та́мо пренесе́ і в хра́мі Бо́жиєм, во і́м'я твоє́ созда́нном, о́ния положи́ на о́бщеє поклоне́ніє ві́рним, Бо́гу, тя просла́вльшему, воспе́вшим: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше чудеса́ пресла́вная, Ники́то свя́те, от моще́й твої́х істека́ющая, Авксе́нтій єпи́скоп восхоті́ часть їх в і́ний град отдели́ти; но того́ начина́ніє дерзнове́нноє а́біє восп'яти́л єси́ і ру́ку, моще́м твої́м прикосну́вшуюся, омертве́нієм порази́л єси́, до́ндеже Авксе́нтій о́ний с покая́нієм к тебі́ припаде́ і, ісціле́ніє от тебе́ прия́в, си́це глаго́лаше:","Ра́дуйся, долготерпіли́вий Христо́в подража́телю;","ра́дуйся, с наказа́нієм твої́м ми́лость і мні яви́вий.","Ра́дуйся, начина́ніє дерзнове́нноє чуде́сно восп'яти́вий;","ра́дуйся, усо́хшую ру́ку а́біє ісціли́вий.","Ра́дуйся, і по сме́рті о Христі́ жив пребива́яй;","ра́дуйся, і по уме́ртвії чудеса́ соверша́яй.","Ра́дуйся, нетлі́нієм просла́вленний на землі́;","ра́дуйся, за по́двиг твой вінча́нний на небесі́.","Ра́дуйся, ізві́стний умилостиви́телю Царя́ Христа́;","ра́дуйся, за ві́рних мо́щний пред Ним предста́телю.","Ра́дуйся, і согріша́ющия вразумля́яй;","ра́дуйся, і малові́рния умудря́яй.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 6","ps":["Пропові́дуєм чудеса́ твоя́, не таї́м ми́лостей твої́х ціле́бних, великому́чениче Ники́то; от літ бо дре́вніх отце́м на́шим сія́ ві́доми би́ша, і хра́ми Бо́жії во і́м'я твоє́ свято́є в страні́ на́шей Украї́нській созида́хуся, іді́же і ли́ка твоєго́ о́бразі чудеси́ просла́вишася, і вся ві́рния во ві́рі утвержда́ють, к небесі́ же сердця́ їх восхища́ють, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ша чудеса́ мно́гая от святи́я іко́ни чудотво́рця Ники́ти, во оби́телі єго́ пребива́ющия і вся ві́рния к пі́нію му́ченика подвиза́ющия; ті́мже і ми с любо́вію святу́ю па́м'ять єго́ чтим і пі́сненно єму́ вопіє́м:","Ра́дуйся, чуде́с істо́чниче преізоби́льний;","ра́дуйся, ми́лости пода́телю преди́вний.","Ра́дуйся, побідоно́сче, Бо́гом просла́вленний;","ра́дуйся, ціле́бниче неду́гов душе́вних і тіле́сних.","Ра́дуйся, боля́щих младе́нцев при́сний врачева́телю;","ра́дуйся, скорб'я́щих і унива́ющих благода́тний посіти́телю.","Ра́дуйся, си́ли дия́вольстій крі́пкий посрами́телю;","ра́дуйся, на ду́хи нечи́стия власть от Го́спода приє́мий.","Ра́дуйся, ді́йства дия́вольськаго от челові́к прогони́телю;","ра́дуйся, от біснова́нія лю́таго стра́ждущих свободи́телю.","Ра́дуйся, апо́стольських даро́в приє́мниче;","ра́дуйся, а́нгельськия кро́тости подража́телю.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 7","ps":["Хотя́щим нам сла́вити по́двиги твоя́ і чудеса́, великому́чениче пресла́вне, помози́ сви́ше да́нною ті благода́тію, сердця́ же на́ша от гріхо́вних помишле́ній очи́сти, да досто́йно і неосужде́нно просла́вим тя, о тебі́ воспіва́я Христу́ Бо́гу хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́внаго побідоно́сця і сла́внаго во́їна Христо́ва, Ники́ту великоімени́таго кто просла́вить по достоя́нію от земноро́дних; сей бо Велія́ра побіди́ і вся слуги́ єго́ низложи́, Христа́ же, Царя́ і Бо́га, ві́рно да́же до сме́рти іспові́да і от Него́ просла́влен бисть. Ті́мже, в хра́мі Єго́ святі́м лику́юще і пред чудотво́рною іко́ною того́ моля́щеся, взива́єм та́ко:","Ра́дуйся, в юдо́лі сей земно́й на́ше утіше́ніє;","ра́дуйся, по Бо́зі і Пресвяті́й Богоро́дице на́ше упова́ніє.","Ра́дуйся, а́нгельських лико́в собесі́дниче;","ра́дуйся, святи́х всіх соприча́стниче.","Ра́дуйся, му́ченичеськаго пресві́тлаго собо́ра сія́ющая звіздо́;","ра́дуйся, от го́рних висо́т нас грі́шних посіща́яй.","Ра́дуйся, да́ри ціле́бния земноро́дним подава́яй;","ра́дуйся, к бе́дствующим на по́мощ ускоря́яй.","Ра́дуйся, моля́щихся моли́тви ми́лостиво приє́мляй;","ра́дуйся, лю́б'ящим тя любо́вію свято́ю воздава́яй.","Ра́дуйся, всеще́дрий і ми́лостивий наш предста́телю;","ра́дуйся, всеблаги́й і скоропредста́тельний наш покрови́телю.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є соверши́в і путь муче́ній проше́д побідоно́сно, великому́чениче Ники́то, от діл благотворе́нія не почи́л єси́, но от го́рних висо́т оби́тель твою́ і лю́ди, ві́рно тебі́ моля́щіяся, назира́я, разли́чная нам подає́ши дарова́нія: даде́ся бо тебі́ от Го́спода ве́лія благода́ть неду́жния врачева́ти, оби́димия заступа́ти, сиро́тствующия младе́нці окормля́ти. Ті́мже благода́рно тя сла́вим і Бо́гу, тя просла́вльшему, поє́м піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі бив, страстоте́рпче Христо́в, о Бо́зі чудеса́ мно́гія соверши́л єси́ в жи́зні і по сме́рті і, дерзнове́ніє к Тому́ получи́в, ви́ну мо́лишися за лю́ди христоімени́тия і ві́рно тя на по́мощ призива́ющим посо́бствуєши. Не оста́ви у́бо і нас благода́тною твоє́ю по́мощію і заступле́нієм, да благода́рно тебі́ зове́м:","Ра́дуйся, преди́вний христия́н помо́щниче;","ра́дуйся, пресла́вний ві́рующих засту́пниче.","Ра́дуйся, великоімени́тий во́їнов спобо́рниче;","ра́дуйся, вдови́ць, і сиро́т прибі́жище.","Ра́дуйся, в со́ніїх і виді́ніїх ві́рния посіща́яй;","ра́дуйся, в біда́х і напа́стіх їх на по́мощ ускоря́яй.","Ра́дуйся, побі́ди тезоимени́тий;","ра́дуйся, вінцено́сче нарочи́тий.","Ра́дуйся, святи́я Це́ркве крі́пкий сто́лпе;","ра́дуйся, правосла́вних щі́те і забра́ло.","Ра́дуйся, ца́рськаго ски́птра утвержде́ніє;","ра́дуйся, правосла́внаго ца́рства сохране́ніє.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 9","ps":["Всі си́нове Украї́нськії от літ дре́вніх пропові́дують благода́тную твою́ по́мощ во бра́ніх, Ники́то преди́вний, я́ко во́єм правосла́вним при́сно на супоста́ти посо́бствуєши і моли́твами твої́ми на іноплеме́нники, вою́ющия на нас і на ві́ру на́шу, пра́во побі́ди нам да́руєши: сіє́ бо во дні наше́ствій тата́рських мно́жицею от літ дре́вніх отці́ на́ша уві́діша. Ті́мже, тя по до́лгу ублажа́юще, поє́м о тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство на́ше не довлі́єть просла́вити тя по достоя́нію, великому́чениче Христо́в Ники́то, оба́че ти, я́ко благи́й і ми́лостивий подража́тель Христо́в, не возгнуша́йся на́ших убо́гих песноглаше́ній, но прийми́ сія́ в бла́го, проізволе́нія серде́ць на́ших ві́дий, і неотсту́пен бу́ди нам помо́щник, вся блага́я да́руя нам твої́ми моли́твами, да благоумиле́нно тебі́ зове́м:","Ра́дуйся, ке́дре благосенноли́ственний, і́мже покрива́ються мно́зі;","ра́дуйся, цві́те прекра́сний, і́мже утіша́ються лю́діє.","Ра́дуйся, ма́слино благопло́дная, єле́й ми́лости нам оби́льно істоча́ющая;","ра́дуйся, кипари́сі са́да Христо́ва, приходя́щия к тебі́ благоуха́яй.","Ра́дуйся, христолюби́вому во́їнству неви́димий воєво́до;","ра́дуйся, інові́рних во́єв страх і пораже́ніє.","Ра́дуйся, страни́ христия́нськия великоімени́тий покрови́телю;","ра́дуйся, со святи́телем Никола́єм при́сний єя́ предста́телю.","Ра́дуйся, на нечести́ваго Мама́я вели́кому кня́зю Дими́трію неви́димо посо́бствовавий;","ра́дуйся, царю́ Іоа́нну под Каза́нію благода́тно спобо́рствовавший.","Ра́дуйся, соіме́ннаго ті боля́рина Рома́нова, твоєго́ усе́рднаго чти́теля, родонача́льника до́ма ца́рськаго яви́вий;","ра́дуйся, храм Бо́жий, во і́м'я твоє́ їм созда́нний, благоволе́нієм твої́м осени́вий.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 10","ps":["Спа́са Христа́ за лю́ди, тя чту́щия, умоли́, Ники́то чудоді́йственне, і, я́коже отце́м на́шим дре́вле, та́ко і ни́ні нам смире́нним во блага́я посо́бствовати не преста́й, страстоте́рпче Христо́в, побі́ди тезоімені́те, но і на враги́ одолі́ніє у Го́спода наро́ду на́шему іспроси́, да сла́вим тя при́сно і поє́м Царю́ царе́й побі́дную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю моли́тв твої́х, великому́чениче Ники́то, оби́тель твою́ святу́ю ви́ну сохраня́й от вся́каго зла і в ней вся живу́щия і подвиза́ющия путе́м пра́вим во Ца́рствіє Христо́во руководи́, зане́ даде́ся тебі́ благода́ть моли́тися о лю́діх. Сего́ ра́ди со усе́рдієм тебі́ поє́м:","Ра́дуйся, ді́вственних ликостоя́ній неотсту́пний храни́телю;","ра́дуйся, дів і вдови́ць, благоче́стно і́ночествующих, небе́сний наста́вниче.","Ра́дуйся, моли́твами твої́ми, я́ко ко́кош птенці́ своя́, нас сохраня́яй;","ра́дуйся, я́ко оре́л крила́ма свої́ма, нас покрива́яй і соблюда́яй.","Ра́дуйся, ста́рим сіди́нам си́ли обновля́яй;","ра́дуйся, ю́ним в благоче́стії і цілому́дрії утвержде́ніє.","Ра́дуйся, нача́льствующим во бла́го помо́щниче;","ра́дуйся, всім ревну́ющим о спасе́нії при́сний споспі́шниче.","Ра́дуйся, чудеси́ твої́ми нас утіша́яй;","ра́дуйся, враги́ неви́димия от нас отража́яй.","Ра́дуйся, ца́рствующаго гра́да свяще́нноє украше́ніє;","ра́дуйся, небе́снаго рая́ сві́тлий граждани́не.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє на́ше, пред чудотво́рною іко́ною твоє́ю приноси́моє днесь, ми́лостиво усли́ши, великому́чениче Христо́в Ники́то, і утро́бу щедро́т твої́х не затвори́ нам, ви́ну тре́бующим твоєя́ благода́тния по́мощі, но бу́ди, я́коже і до днесь бил єси́, благи́й наш предста́тель і при́сний за ни ко Го́споду моли́твенник, да о тебі́ ра́дующеся і Бо́га сла́в'яще, поє́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рний світи́льник і преди́вний чудотво́рець великому́ченик Ники́та яви́ся, той бо от літ дре́вніх оте́чествіє на́ше і оби́тель на́шу свої́ми моли́твами і щедро́тами не оставля́єть, но я́ко побіди́тель, вся враги́ на́ша ви́димия же і неви́димия отража́єть і благоче́стно в ми́рі жи́ти нас устроя́єть. Ті́мже і от нас, уго́дниче Бо́жий, сіє́ благода́рноє славосло́віє прийми́:","Ра́дуйся, вели́кий наш предста́телю;","ра́дуйся, на́ших враго́в неви́димих побіди́телю.","Ра́дуйся, преоблада́ти їм над на́ми не попуща́яй;","ра́дуйся, вся ко́зні їх, а́ки паучи́ну, расторга́яй.","Ра́дуйся, і в час сме́ртний лю́б'ящих і чту́щих тя не оставля́яй;","ра́дуйся, от наси́лія дия́вольськаго їх мо́щно сохраня́яй.","Ра́дуйся, о спасе́нії на́шем Бо́га ви́ну умоля́яй;","ра́дуйся, на мита́рствах возду́шних ві́рним по́мощ твою́ явля́яй.","Ра́дуйся, і на землі́ неду́гов лю́тих прогони́телю;","ра́дуйся, болі́зней неісціли́мих ціли́телю.","Ра́дуйся, безнаде́жних наде́ждо;","ра́дуйся, христия́н похвало́.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жию ви́дим от святи́я і чудотво́рния іко́ни твоєя́ ді́йствующую, Ники́то великоімени́те, к ней бо с ві́рою притека́ющії ісціле́нія получа́ють і здра́ви із хра́ма твоєго́ отхо́дять, ті́мже і ми твой свяще́нний о́браз благогові́йно почита́єм і с любо́вію лобиза́єм, і поє́м тобо́ю чудоді́йствующему Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ ми́лості і мно́гоє к стра́ждущим сострада́ніє, великому́чениче Ники́то, сла́вим і велича́єм тя, Бо́гом возвели́ченнаго, і от любве́ серде́чния воспіва́єм ті пі́сні такови́я:","Ра́дуйся, бі́дствующих ско́рий помо́щниче;","ра́дуйся, богатя́щихся вразумле́ніє.","Ра́дуйся, всей Украї́ни Бо́гом да́нний покрови́телю;","ра́дуйся, оби́телі твоєя́ при́сноє ра́дованіє.","Ра́дуйся, хода́таю о ней немо́лчний;","ра́дуйся, моля́щихся врачу́ безме́здний.","Ра́дуйся, ко ісціле́нію єди́ния то́кмо ві́ри тре́буяй;","ра́дуйся, ду́ші і тілеса́ ісціля́яй.","Ра́дуйся, ві́рним ви́ну помога́яй;","ра́дуйся, малове́рних во ві́рі утвержда́яй.","Ра́дуйся, ві́ри отвра́щшихся гро́зно наказу́яй;","ра́дуйся, стра́ха Бо́жия учи́телю.","Ра́дуйся, де́рзости самочи́нния обличи́телю.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 13","ps":["О вели́кий уго́дниче Бо́жий, страстоте́рпче Христо́в і чудотво́рче Ники́то! Воньми́ моли́тві на́шей і ма́лаго моле́нія сего́ на́шего не пре́зри, но Христа́ Бо́га умоли́ ізба́витися нам от муче́ній ві́чних, небе́снаго же Ца́рствія чрез покая́ніє сподо́битися, да с тобо́ю воспоє́м на землі́ живи́х піснь Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськи на землі́ пожи́в, побі́ди тезоімені́те великому́чениче Ники́то, ти я́ко а́нгел благи́й в страні́ Го́тфстей просія́л єси́, ві́ру Христо́ву лю́дем, тьмо́ю неві́рія помраче́нним пропові́дуя, ті́мже апо́столом ра́вний дія́нії твої́ми показа́лся єси́. Ми же по до́лгу тя, я́ко пропові́дника Христо́ва, ублажа́єм, со умиле́нієм зову́ще ті си́це:","Ра́дуйся, благові́стниче Єва́нгельськия і́стини;","ра́дуйся, язи́чеськоє нече́стіє попра́вий.","Ра́дуйся, ві́ру Христо́ву возлюби́вий;","ра́дуйся, страну́ Го́тфськую духо́вно просвіти́вий.","Ра́дуйся, дия́вола і слуги́ єго́ обличи́вий;","ра́дуйся, по і́мені твоєму́ тіх побідоно́сно низложи́вий.","Ра́дуйся, да́же до кро́ве во іспові́данії Христо́ві послужи́вий;","ра́дуйся, муче́нія многови́дная за Христа́ до́блестно претерпі́вий.","Ра́дуйся, огне́м всесожже́нний і во оби́телі ра́йськия вознесе́нний;","ра́дуйся, же́ртва непоро́чная Тро́йці Святі́й яви́вийся.","Ра́дуйся, сто́лпе крі́пкий Святи́я Це́ркве;","ра́дуйся, красото́ і основа́ніє ві́ри Христо́ви.","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Кондак 1","ps":["Ізбра́нний страстоте́рпче Христо́в і до́блій во́їне Царя́ царе́й, Ники́то пресла́вне, ору́жієм Креста́ враги́ ви́димия і неви́димия крі́пці побіди́вий і во всесожже́ніє ту́чноє, я́ко же́ртву благоприя́тну, себі́ сама́го Го́сподеві принеси́й, в пі́сніх с любо́вію восхваля́єм тя, свята́го предста́теля на́шего, і ра́достно тебі́ вопіє́м:","Ра́дуйся, великому́чениче і чудотво́рче Ники́то."]},{"h":"Молитва","ps":["О, вели́кий страстоте́рпче Христо́в і чудотво́рче великому́чениче Ники́то! Припа́дающе к свято́му і чудотво́рному о́бразу твоєму́, по́двиги же і чудеса́ твоя́ і мно́гоє сострада́ніє твоє́ к лю́дем прославля́юще, мо́лим тя прилі́жно: яви́ нам, смире́нним і грі́шним, свято́є і многомо́щноє твоє́ заступле́ніє, се бо гріх ра́ди на́ших не і́мами свобо́ди чад Бо́жиїх, є́же о потре́бах на́ших Го́спода і Влади́ку на́шего дерзнове́нно проси́ти, но тебі́ моли́твенника к нему́ благоприя́тнаго предлага́єм і о твоє́м предста́тельстві взива́єм, іспроси́ нам у Го́спода благопотре́бния да́ри душа́м і тілесе́м на́шим, ві́ру пра́вую, спасе́нія наде́жду несумні́нную, любо́в же ко всім нелицемі́рную, во іскуше́ніїх му́жество, в злострада́ніїх терпі́ніє, в моли́твах постоя́нство, душ і тіле́с здра́віє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, жите́йських потре́б дово́льство, ми́рноє і благоче́стноє на землі́ житіє́, христия́нськую житія́ кончи́ну і до́брий отві́т на стра́шнім суди́щі Христо́вом. Мо́лим тя, страстоте́рпче Христо́в, моли́ся Го́сподеві: всім же лю́дем правосла́вним яви́ твоє́ свято́є заступле́ніє: боля́щия ісціли́, скорб'я́щия уті́ши, бе́дствующим помози́. Єй, уго́дниче Бо́жий і му́чениче долготерпіли́вий! Не забу́ди святу́ю оби́тель твою́ і вся живу́щия в ней і подвиза́ющіяся і́нокини же і мирськи́я, но поспіши́ їм в смире́нії і терпі́нії носи́ти і́го Христо́во і от вся́ких бід і іскуше́ній ми́лостивне ізба́ви. Всіх у́бо нас приведи́ в ти́хоє приста́нище спасе́нія і наслі́дники сподо́би би́ти пресві́тлаго Ца́рствія Христо́ва святи́ми твої́ми моли́твами, да сла́вим і поє́м вели́кия щедро́ти Отця́, і Си́на, і Свята́го Ду́ха, в Тро́йці сла́вимаго і покланя́ємаго Бо́га, і твоє́ свято́є заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Му́ченик Твой, Го́споди, Ники́та / во страда́нії своє́м віне́ць прия́т нетлі́нний от Тебе́, Бо́га на́шего: / імі́яй бо крі́пость Твою́, / мучи́телей низложи́, / сокруши́ і де́монов немощни́я де́рзости. / Того́ моли́твами // спаси́ ду́ші на́ша."]},{"h":"Інший тропар, глас 4","ps":["Крест Христо́в, я́ко ні́коє ору́жіє усе́рдно восприї́м, / і к боре́нію враго́в прите́кл єси́, / і за Христа́ пострада́в, / посліди́ огне́м свяще́нную твою́ ду́шу Го́споду пре́дал єси́: / отону́дуже і даро́в ісціле́нія / от Него́ сподо́бился єси́ прия́ти, / великому́чениче Ники́то. / Моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Пре́лести посі́к держа́ву стоя́нієм твої́м, / і побі́ди приї́м віне́ць во страда́льчествіх твої́х, / со А́нгели сла́вне ра́дуєшися, / Ники́то тезоімені́те, // с ни́ми Христа́ Бо́га моля́ непреста́нно о всіх нас."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпче святи́й Ники́то, і чтим честна́я страда́нія твоя́, я́же за Христа́ претерпі́л єси́."]}],"notes":[]}];
export default D;
